use clap::Command;
use clap_complete::{generate, Shell};
use std::io;

pub fn run(shell: &str) {
    let mut cmd = crate::cli::build_cli();
    let name = cmd.get_name().to_string();
    let mut stdout = io::stdout();
    match shell {
        "bash" => generate(Shell::Bash, &mut cmd, &name, &mut stdout),
        "elvish" => generate(Shell::Elvish, &mut cmd, &name, &mut stdout),
        "fish" => generate(Shell::Fish, &mut cmd, &name, &mut stdout),
        "power-shell" => generate(Shell::PowerShell, &mut cmd, &name, &mut stdout),
        "zsh" => generate(Shell::Zsh, &mut cmd, &name, &mut stdout),
        "nushell" => {
            let mut out = String::new();
            nushell::generate(&mut cmd, &mut out);
            print!("{out}");
        }
        _ => unreachable!(),
    }
}

/// Custom nushell completion generator matching the clap_complete_nushell format.
mod nushell {
    use clap::{Arg, ArgAction, Command};
    use std::fmt::Write;

    pub fn generate(cmd: &mut Command, out: &mut String) {
        cmd.build();
        out.push_str("module completions {\n\n");
        generate_completion(out, cmd, false);
        for sub in cmd.get_subcommands() {
            generate_completion(out, sub, true);
        }
        out.push_str("}\n\nexport use completions *\n");
    }

    fn append_value(arg: &Arg, name: &str, s: &mut String) {
        let takes_values = arg
            .get_num_args()
            .map(|r| r.takes_values())
            .unwrap_or(false);
        if takes_values {
            s.push_str(": ");
            let is_path = arg
                .get_value_parser()
                .type_id()
                == clap::builder::TypeId::of::<std::path::PathBuf>()
                || matches!(
                    arg.get_value_hint(),
                    clap::ValueHint::AnyPath
                        | clap::ValueHint::FilePath
                        | clap::ValueHint::DirPath
                        | clap::ValueHint::ExecutablePath
                );
            s.push_str(if is_path { "path" } else { "string" });
            if !arg.get_possible_values().is_empty() {
                let _ = write!(s, "@\"nu-complete {} {}\"", name, arg.get_id());
            }
        }
    }

    fn append_help(arg: &Arg, s: &mut String) {
        if let Some(help) = arg.get_help() {
            let help = help.to_string().replace('\n', " ");
            // pad to column 30 (relative to the 4-space indent)
            let len = s.len();
            if len < 30 {
                for _ in len..30 {
                    s.push(' ');
                }
            } else {
                s.push(' ');
            }
            let _ = write!(s, "# {}", help);
        }
    }

    fn generate_completion(out: &mut String, cmd: &Command, is_subcommand: bool) {
        let bin_name = cmd.get_bin_name().unwrap_or_else(|| cmd.get_name());
        let name = bin_name;

        for arg in cmd.get_arguments() {
            if arg.is_hide_set() {
                continue;
            }
            let pv = arg.get_possible_values();
            if pv.is_empty() {
                continue;
            }
            let _ = writeln!(out, "  def \"nu-complete {} {}\" [] {{", name, arg.get_id());
            out.push_str("    [");
            for v in &pv {
                let _ = write!(out, " \"{}\"", v.get_name());
            }
            out.push_str(" ]\n  }\n\n");
        }

        if let Some(about) = cmd.get_about() {
            let _ = writeln!(out, "  # {}", about);
        }
        if is_subcommand {
            let _ = writeln!(out, "  export extern \"{}\" [", name);
        } else {
            let _ = writeln!(out, "  export extern {} [", name);
        }

        // flags and options
        for arg in cmd.get_arguments() {
            if arg.is_positional() {
                continue;
            }
            let mut s = String::new();
            if let Some(long) = arg.get_long() {
                let _ = write!(s, "--{long}");
                if let Some(short) = arg.get_short() {
                    let _ = write!(s, "(-{short})");
                }
            } else if let Some(short) = arg.get_short() {
                let _ = write!(s, "-{short}");
            }
            append_value(arg, name, &mut s);
            append_help(arg, &mut s);
            let _ = writeln!(out, "    {s}");
        }
        // positionals
        for arg in cmd.get_positionals() {
            let mut s = String::new();
            let id = arg.get_id().to_string().replace('-', "_");
            let multiple = matches!(arg.get_action(), ArgAction::Append)
                || arg
                    .get_num_args()
                    .map(|r| r.max_values() > 1)
                    .unwrap_or(false);
            if multiple {
                let _ = write!(s, "...{id}");
            } else if arg.is_required_set() {
                let _ = write!(s, "{id}");
            } else {
                let _ = write!(s, "{id}?");
            }
            append_value(arg, name, &mut s);
            append_help(arg, &mut s);
            let _ = writeln!(out, "    {s}");
        }
        out.push_str("  ]\n\n");
    }
}
