use anyhow::{anyhow, Context, Result};
use serde_json::Value;
use std::env;
use std::fs;
use std::path::PathBuf;

pub struct Config {
    pub location: PathBuf,
    pub config: Value,
}

impl Config {
    pub fn find_config_file() -> Result<Option<PathBuf>> {
        if let Ok(path) = env::var("TREE_SITTER_DIR") {
            let mut path = PathBuf::from(path);
            path.push("config.json");
            if path.is_file() {
                return Ok(Some(path));
            }
        }
        let xdg_path = Self::xdg_config_file()?;
        if xdg_path.is_file() {
            return Ok(Some(xdg_path));
        }
        let legacy_path = dirs::home_dir()
            .ok_or_else(|| anyhow!("Cannot determine home directory"))?
            .join(".tree-sitter/config.json");
        if legacy_path.is_file() {
            return Ok(Some(legacy_path));
        }
        Ok(None)
    }

    fn xdg_config_file() -> Result<PathBuf> {
        let xdg_path = dirs::config_dir().ok_or_else(|| anyhow!("Cannot determine config directory"))?;
        Ok(xdg_path.join("tree-sitter").join("config.json"))
    }

    pub fn initial() -> Result<Self> {
        let location = if let Ok(path) = env::var("TREE_SITTER_DIR") {
            let mut path = PathBuf::from(path);
            path.push("config.json");
            path
        } else {
            Self::xdg_config_file()?
        };
        Ok(Self {
            location,
            config: Value::Object(serde_json::Map::new()),
        })
    }

    pub fn load(path: Option<PathBuf>) -> Result<Self> {
        let location = match path {
            Some(path) => path,
            None => match Self::find_config_file()? {
                Some(path) => path,
                None => return Self::initial(),
            },
        };
        let content = fs::read_to_string(&location)
            .with_context(|| format!("Failed to read {}", location.to_string_lossy()))?;
        let config = serde_json::from_str(&content)
            .with_context(|| format!("Bad JSON config {}", location.to_string_lossy()))?;
        Ok(Self { location, config })
    }

    pub fn save(&self) -> Result<()> {
        let json = serde_json::to_string_pretty(&self.config)?;
        fs::create_dir_all(self.location.parent().unwrap())?;
        fs::write(&self.location, json)?;
        Ok(())
    }

    pub fn parser_directories(&self) -> Vec<PathBuf> {
        match self.config.get("parser-directories") {
            Some(Value::Array(arr)) => arr
                .iter()
                .filter_map(|v| v.as_str().map(PathBuf::from))
                .collect(),
            _ => Vec::new(),
        }
    }
}

pub fn initial_config_json() -> Result<Value> {
