pub fn run(update: bool, grammar_path: Option<PathBuf>) -> Result<()> {
    let current_dir = std::env::current_dir()?;
    let repo_path = grammar_path.unwrap_or(current_dir);
    let json_path = repo_path.join("tree-sitter.json");

    if !json_path.exists() {
        // Interactive flow requires a terminal.
        if !crate::util::all_std_streams_are_terminals() {
            return Err(anyhow!("IO error: not a terminal"));
        }
        return crate::init_interactive::run(&repo_path);
    }

    let json = TreeSitterJSON::from_file(&json_path)?;
    let language_name = json.grammars[0].name.clone();
    generate_grammar_files(&repo_path, &language_name, update, &json)?;
    Ok(())
}

pub fn generate_grammar_files(
    repo_path: &Path,
    language_name: &str,
    allow_update: bool,
    tree_sitter_config: &TreeSitterJSON,
) -> Result<()> {
    let grammar = &tree_sitter_config.grammars[0];
    let metadata = &tree_sitter_config.metadata;
    let authors = metadata.authors.as_ref();
    let first_author = authors.and_then(|a| a.first());

    let generate_opts = GenerateOpts {
        author_name: first_author.map(|a| a.name.as_str()),
        author_email: first_author.and_then(|a| a.email.as_deref()),
        author_url: first_author.and_then(|a| a.url.as_deref()),
        license: metadata.license.as_deref(),
        description: metadata.description.as_deref(),
        repository: metadata.links.as_ref().map(|l| l.repository.as_str()),
        version: &metadata.version,
        camel_parser_name: grammar.camelcase.as_deref(),
        title_parser_name: grammar.title.as_deref(),
        class_name: grammar.class_name.as_deref(),
        funding: metadata.links.as_ref().and_then(|l| l.funding.as_deref()),
    };

    let bindings = &tree_sitter_config.bindings;
    let json_path = repo_path.join("tree-sitter.json");

    // With --update, add the schema key if it is missing.
    if allow_update && tree_sitter_config.schema.is_none() {
        eprintln!("Updating tree-sitter.json");
        let mut json = tree_sitter_config.clone();
        json.schema = Some(TREE_SITTER_JSON_SCHEMA.to_string());
        fs::write(&json_path, serde_json::to_string_pretty(&json)?)?;
    }

    // grammar.js
    if tree_sitter_config.grammars.len() == 1 {
        missing_path(repo_path.join("grammar.js"), |path| {
            generate_file(path, GRAMMAR_JS_TEMPLATE, language_name, &generate_opts)
        })?;
    }

    // dot files
    missing_path(repo_path.join(".gitignore"), |path| {
        generate_file(path, GITIGNORE_TEMPLATE, language_name, &generate_opts)
    })?;
    missing_path(repo_path.join(".gitattributes"), |path| {
        generate_file(path, GITATTRIBUTES_TEMPLATE, language_name, &generate_opts)
    })?;
    missing_path(repo_path.join(".editorconfig"), |path| {
        generate_file(path, EDITORCONFIG_TEMPLATE, language_name, &generate_opts)
    })?;

    let bindings_dir = repo_path.join("bindings");

    // C bindings
    if bindings.c {
        missing_path(bindings_dir.join("c"), create_dir)?.apply(|path| {
            missing_path(path.join("tree_sitter"), create_dir)?.apply(|path| {
                missing_path(
                    path.join(format!("tree-sitter-{}.h", language_name.to_kebab_case())),
                    |path| generate_file(path, PARSER_H_TEMPLATE, language_name, &generate_opts),
                )?;
                Ok(())
            })?;
            missing_path(
                path.join(format!("tree-sitter-{}.pc.in", language_name.to_kebab_case())),
                |path| generate_file(path, PARSER_PC_IN_TEMPLATE, language_name, &generate_opts),
            )?;
            missing_path(repo_path.join("Makefile"), |path| {
                generate_file(path, MAKEFILE_TEMPLATE, language_name, &generate_opts)
            })?;
            missing_path(repo_path.join("CMakeLists.txt"), |path| {
                generate_file(path, CMAKELISTS_TXT_TEMPLATE, language_name, &generate_opts)
            })?;
            Ok(())
        })?;
    }

    // Go bindings
    if bindings.go {
        missing_path(bindings_dir.join("go"), create_dir)?.apply(|path| {
            missing_path(path.join("binding.go"), |path| {
                generate_file(path, BINDING_GO_TEMPLATE, language_name, &generate_opts)
            })?;
            missing_path(path.join("binding_test.go"), |path| {
                generate_file(path, BINDING_TEST_GO_TEMPLATE, language_name, &generate_opts)
            })?;
            missing_path(repo_path.join("go.mod"), |path| {
                generate_file(path, GO_MOD_TEMPLATE, language_name, &generate_opts)
            })?;
            Ok(())
        })?;
    }

    // Node bindings
    if bindings.node {
        missing_path(bindings_dir.join("node"), create_dir)?.apply(|path| {
            missing_path(path.join("index.js"), |path| {
                generate_file(path, INDEX_JS_TEMPLATE, language_name, &generate_opts)
            })?;
            missing_path(path.join("index.d.ts"), |path| {
                generate_file(path, INDEX_D_TS_TEMPLATE, language_name, &generate_opts)
            })?;
            missing_path(path.join("binding_test.js"), |path| {
                generate_file(path, BINDING_TEST_JS_TEMPLATE, language_name, &generate_opts)
            })?;
            missing_path(path.join("binding.cc"), |path| {
                generate_file(path, BINDING_CC_TEMPLATE, language_name, &generate_opts)
            })?;
            missing_path(repo_path.join("binding.gyp"), |path| {
                generate_file(path, BINDING_GYP_TEMPLATE, language_name, &generate_opts)
            })?;
            Ok(())
        })?;
    }

    // package.json is always generated
    missing_path(repo_path.join("package.json"), |path| {
        generate_file(path, PACKAGE_JSON_TEMPLATE, language_name, &generate_opts)
    })?;

    // Python bindings
    if bindings.python {
        missing_path(bindings_dir.join("python"), create_dir)?.apply(|path| {
            let lang_path = path.join(format!("tree_sitter_{}", language_name.to_snake_case()));
            missing_path(&lang_path, create_dir)?;
            missing_path(lang_path.join("binding.c"), |path| {
                generate_file(path, BINDING_C_TEMPLATE, language_name, &generate_opts)
            })?;
            missing_path_else(
                lang_path.join("__init__.py"),
                allow_update,
                |path| generate_file(path, INIT_PY_TEMPLATE, language_name, &generate_opts),
                |path| {
                    eprintln!("Replacing __init__.py");
                    generate_file(path, INIT_PY_TEMPLATE, language_name, &generate_opts)
                },
            )?;
            missing_path(lang_path.join("__init__.pyi"), |path| {
                generate_file(path, INIT_PYI_TEMPLATE, language_name, &generate_opts)
            })?;
            missing_path(lang_path.join("py.typed"), |path| {
                generate_file(path, "", language_name, &generate_opts)
            })?;
            missing_path(path.join("tests"), create_dir)?.apply(|path| {
                missing_path(path.join("test_binding.py"), |path| {
                    generate_file(path, TEST_BINDING_PY_TEMPLATE, language_name, &generate_opts)
                })?;
                Ok(())
            })?;
            missing_path(repo_path.join("setup.py"), |path| {
                generate_file(path, SETUP_PY_TEMPLATE, language_name, &generate_opts)
            })?;
            missing_path(repo_path.join("pyproject.toml"), |path| {
                generate_file(path, PYPROJECT_TOML_TEMPLATE, language_name, &generate_opts)
            })?;
            Ok(())
        })?;
    }

    // Rust bindings
    if bindings.rust {
        missing_path(bindings_dir.join("rust"), create_dir)?.apply(|path| {
            missing_path(path.join("lib.rs"), |path| {
                generate_file(path, LIB_RS_TEMPLATE, language_name, &generate_opts)
            })?;
            missing_path(path.join("build.rs"), |path| {
                generate_file(path, BUILD_RS_TEMPLATE, language_name, &generate_opts)
            })?;
            missing_path(repo_path.join("Cargo.toml"), |path| {
                generate_file(path, CARGO_TOML_TEMPLATE, language_name, &generate_opts)
            })?;
            Ok(())
        })?;
    }

    // Swift bindings
    if bindings.swift {
        missing_path(bindings_dir.join("swift"), create_dir)?.apply(|path| {
            let class_name = class_name_for(language_name, &generate_opts);
            missing_path(path.join(&class_name), create_dir)?.apply(|path| {
                missing_path(path.join(format!("{language_name}.h")), |path| {
                    generate_file(path, PARSER_H_TEMPLATE, language_name, &generate_opts)
                })?;
                Ok(())
            })?;
            missing_path(path.join(format!("{class_name}Tests")), create_dir)?.apply(|path| {
                missing_path(path.join(format!("{class_name}Tests.swift")), |path| {
                    generate_file(path, BINDING_TEST_SWIFT_TEMPLATE, language_name, &generate_opts)
                })?;
                Ok(())
            })?;
            missing_path(repo_path.join("Package.swift"), |path| {
                generate_file(path, PACKAGE_SWIFT_TEMPLATE, language_name, &generate_opts)
            })?;
            Ok(())
        })?;
    }

    // Zig bindings
    if bindings.zig {
        missing_path(bindings_dir.join("zig"), create_dir)?.apply(|path| {
            missing_path(path.join("root.zig"), |path| {
                generate_file(path, ROOT_ZIG_TEMPLATE, language_name, &generate_opts)
            })?;
            missing_path(path.join("test.zig"), |path| {
                generate_file(path, TEST_ZIG_TEMPLATE, language_name, &generate_opts)
            })?;
            missing_path(repo_path.join("build.zig"), |path| {
                generate_file(path, BUILD_ZIG_TEMPLATE, language_name, &generate_opts)
            })?;
            missing_path(repo_path.join("build.zig.zon"), |path| {
                generate_file(path, BUILD_ZIG_ZON_TEMPLATE, language_name, &generate_opts)
            })?;
            Ok(())
        })?;
    }

    // Java bindings
    if bindings.java {
        missing_path(bindings_dir.join("java"), create_dir)?.apply(|path| {
            let class_name = class_name_for(language_name, &generate_opts);
            let package_dir = path
                .join("main")
                .join("io")
                .join("github")
                .join("treesitter")
                .join("jtreesitter")
                .join(language_name.to_lowercase().replace('_', ""));
            fs::create_dir_all(&package_dir)?;
            missing_path(package_dir.join(format!("{class_name}.java")), |path| {
                generate_file(path, BINDING_JAVA_TEMPLATE, language_name, &generate_opts)
            })?;
            let test_dir = path.join("test");
            fs::create_dir_all(&test_dir)?;
            missing_path(test_dir.join(format!("{class_name}Test.java")), |path| {
                generate_file(path, BINDING_TEST_JAVA_TEMPLATE, language_name, &generate_opts)
            })?;
            missing_path(repo_path.join("pom.xml"), |path| {
                generate_file(path, POM_XML_TEMPLATE, language_name, &generate_opts)
            })?;
            Ok(())
        })?;
    }

    let _ = Bindings::default;
    Ok(())
}

fn class_name_for(language_name: &str, opts: &GenerateOpts) -> String {
    opts.class_name
        .map(|s| s.to_string())
        .unwrap_or_else(|| format!("TreeSitter{}", language_name.to_upper_camel_case()))
}

pub fn generate_file(
    path: &Path,
    template: &str,
    language_name: &str,
    generate_opts: &GenerateOpts,
) -> Result<()> {
    let filename = path.file_name().unwrap().to_str().unwrap();

    let camel_name = generate_opts
        .camel_parser_name
        .map(|s| s.to_string())
        .unwrap_or_else(|| language_name.to_upper_camel_case());
    let title_name = generate_opts
        .title_parser_name
        .map(|s| s.to_string())
        .unwrap_or_else(|| language_name.to_upper_camel_case());
    let class_name = class_name_for(language_name, generate_opts);
    let description = generate_opts
        .description
        .map(|s| s.to_string())
        .unwrap_or_else(|| format!("{title_name} grammar for tree-sitter"));
    let repository = generate_opts
        .repository
        .map(|s| s.to_string())
        .unwrap_or_else(|| {
            format!(
                "https://github.com/tree-sitter/tree-sitter-{}",
                language_name.to_kebab_case()
            )
        });
    let repository_stripped = repository
        .strip_prefix("https://")
        .or_else(|| repository.strip_prefix("http://"))
        .unwrap_or(&repository)
        .to_string();

    let mut replacement = template
        .replace(CLASS_NAME_PLACEHOLDER, &class_name)
        .replace(CAMEL_PARSER_NAME_PLACEHOLDER, &camel_name)
        .replace(TITLE_PARSER_NAME_PLACEHOLDER, &title_name)
        .replace(UPPER_PARSER_NAME_PLACEHOLDER, &language_name.to_shouty_snake_case())
        .replace(LOWER_PARSER_NAME_PLACEHOLDER, &language_name.to_lowercase().replace('_', ""))
        .replace(KEBAB_PARSER_NAME_PLACEHOLDER, &language_name.to_kebab_case())
        .replace(PARSER_NAME_PLACEHOLDER, language_name)
        .replace(PARSER_DESCRIPTION_PLACEHOLDER, &description)
        .replace(PARSER_LICENSE_PLACEHOLDER, generate_opts.license.unwrap_or("MIT"))
        .replace(PARSER_VERSION_PLACEHOLDER, &generate_opts.version.to_string())
        .replace(PARSER_URL_STRIPPED_PLACEHOLDER, &repository_stripped)
        .replace(PARSER_URL_PLACEHOLDER, &repository);

    if filename == "build.zig.zon" {
        let crc = crc32fast::hash(format!("tree_sitter_{language_name}").as_bytes());
        let rand_part: u32 = rand::random();
        let fingerprint = ((crc as u64) << 32) | rand_part as u64;
        replacement = replacement.replace(ZIG_FINGERPRINT_PLACEHOLDER, &format!("0x{fingerprint:016x}"));
    }

    match generate_opts.author_name {
        Some(name) => replacement = replacement.replace(PARSER_AUTHOR_NAME_PLACEHOLDER, name),
        None => match filename {
            "package.json" => {
                replacement = replacement.replace(
                    "  \"author\": {\n    \"name\": \"PARSER_AUTHOR_NAME\",\n    \"email\": \"PARSER_AUTHOR_EMAIL\",\n    \"url\": \"PARSER_AUTHOR_URL\"\n  },\n",
                    "",
                );
            }
            "pyproject.toml" => {
                replacement = replacement.replace("name = \"PARSER_AUTHOR_NAME\"", "");
            }
            "pom.xml" => {
                replacement = replacement.replace(
                    "    <developer>\n      <name>PARSER_AUTHOR_NAME</name>\n      <email>PARSER_AUTHOR_EMAIL</email>\n      <url>PARSER_AUTHOR_URL</url>\n    </developer>\n",
                    "",
                );
            }
            _ => replacement = replacement.replace(PARSER_AUTHOR_NAME_PLACEHOLDER, ""),
        },
    }

    match generate_opts.author_email {
        Some(email) => replacement = replacement.replace(PARSER_AUTHOR_EMAIL_PLACEHOLDER, email),
        None => match filename {
            "package.json" => {
                replacement = replacement.replace(",\n    \"email\": \"PARSER_AUTHOR_EMAIL\"", "");
            }
            "grammar.js" | "Cargo.toml" => {
                replacement = replacement.replace(" <PARSER_AUTHOR_EMAIL>", "");
            }
            "pom.xml" => {
                replacement = replacement.replace("      <email>PARSER_AUTHOR_EMAIL</email>\n", "");
            }
            _ => {}
        },
    }

    match generate_opts.author_url {
        Some(url) => replacement = replacement.replace(PARSER_AUTHOR_URL_PLACEHOLDER, url),
        None => match filename {
            "package.json" => {
                replacement = replacement.replace(",\n    \"url\": \"PARSER_AUTHOR_URL\"", "");
            }
            "pom.xml" => {
                replacement = replacement.replace("      <url>PARSER_AUTHOR_URL</url>\n", "");
            }
            _ => {}
        },
    }

    match generate_opts.funding {
        Some(funding) => replacement = replacement.replace(FUNDING_URL_PLACEHOLDER, funding),
        None => match filename {
            "package.json" => {
                replacement = replacement.replace("  \"funding\": \"FUNDING_URL\",\n", "");
            }
            _ => {}
        },
    }

    write_file(path, replacement)
}

pub fn write_file(path: &Path, body: impl AsRef<[u8]>) -> Result<()> {
    fs::write(path, body).with_context(|| format!("Failed to write {:?}", path.file_name().unwrap()))
}

fn create_dir(path: &Path) -> Result<()> {
    fs::create_dir_all(path)
        .with_context(|| format!("Failed to create {:?}", path.to_string_lossy()))
}

pub enum PathState<P: AsRef<Path>> {
    Exists(P),
    Missing(P),
}

impl<P: AsRef<Path>> PathState<P> {
    pub fn exists(&self, mut action: impl FnMut(&Path) -> Result<()>) -> Result<&Self> {
        if let Self::Exists(path) = self {
            action(path.as_ref())?;
        }
        Ok(self)
    }

    pub fn missing(&self, mut action: impl FnMut(&Path) -> Result<()>) -> Result<&Self> {
        if let Self::Missing(path) = self {
            action(path.as_ref())?;
        }
        Ok(self)
    }

    pub fn apply(&self, mut action: impl FnMut(&Path) -> Result<()>) -> Result<&Self> {
        action(self.as_path())?;
        Ok(self)
    }

    pub fn as_path(&self) -> &Path {
        match self {
            Self::Exists(path) | Self::Missing(path) => path.as_ref(),
        }
    }
}

fn missing_path<P: AsRef<Path>, F: Fn(&Path) -> Result<()>>(path: P, action: F) -> Result<PathState<P>> {
    let path_ref = path.as_ref();
    if !path_ref.exists() {
        action(path_ref)?;
        Ok(PathState::Missing(path))
    } else {
        Ok(PathState::Exists(path))
    }
}

fn missing_path_else<P: AsRef<Path>, T, F>(
    path: P,
    allow_update: bool,
    action: T,
    else_action: F,
) -> Result<PathState<P>>
where
    T: Fn(&Path) -> Result<()>,
    F: Fn(&Path) -> Result<()>,
{
    let path_ref = path.as_ref();
    if !path_ref.exists() {
        action(path_ref)?;
        Ok(PathState::Missing(path))
    } else {
        if allow_update {
            else_action(path_ref)?;
        }
        Ok(PathState::Exists(path))
    }
}
