    Major,
}

pub fn run(grammar_path: Option<PathBuf>, version: Option<Version>, bump: Option<Bump>) -> Result<()> {
    let current_dir = match grammar_path {
        Some(p) => p,
        None => std::env::current_dir()?,
    };
    let json_path = current_dir.join("tree-sitter.json");
    let json = TreeSitterJSON::from_file(&json_path)?;
    let current_version = json.metadata.version.clone();
    let is_multigrammar = json.grammars.len() > 1;

    let new_version = if let Some(bump) = bump {
        let mut v = current_version.clone();
        match bump {
            Bump::Patch => v.patch += 1,
            Bump::Minor => {
                v.minor += 1;
                v.patch = 0;
            }
            Bump::Major => {
                v.major += 1;
                v.minor = 0;
                v.patch = 0;
            }
        }
        v
    } else if let Some(v) = version {
        v
    } else {
        println!("Current version: {current_version}");
        return Ok(());
    };

    if new_version < current_version {
        eprintln!("{} New version is lower than current!", warning_prefix());
        eprintln!(
            "{} Reverting version {current_version} to {new_version}",
            warning_prefix()
        );
    } else {
        println!("Bumping version {current_version} to {new_version}");
    }

    let mut errors: Vec<(PathBuf, anyhow::Error)> = Vec::new();
    let mut record = |path: PathBuf, r: Result<()>| {
        if let Err(e) = r {
            errors.push((path, e));
        }
    };

    let ver = new_version.to_string();

    // tree-sitter.json
    let p = json_path.clone();
    record(p.clone(), update_lines(&p, |line| replace_json_version(line, &ver)));

    // Cargo.toml
    let p = current_dir.join("Cargo.toml");
    if p.exists() {
        record(
            p.clone(),
            update_lines(&p, |line| {
                if line.starts_with("version = ") {
                    format!("version = \"{ver}\"")
                } else {
                    line.to_string()
                }
            }),
        );
    }

    // package.json
    let p = current_dir.join("package.json");
    if p.exists() {
        record(p.clone(), update_lines(&p, |line| replace_json_version(line, &ver)));
    }

    // Makefile (or common/common.mak for multi grammar repos)
    let p = if is_multigrammar {
        current_dir.join("common").join("common.mak")
    } else {
        current_dir.join("Makefile")
    };
    record(
        p.clone(),
        update_lines(&p, |line| {
            if line.starts_with("VERSION") {
                format!("VERSION := {ver}")
            } else {
                line.to_string()
            }
        }),
    );

    // CMakeLists.txt
    let p = current_dir.join("CMakeLists.txt");
    if p.exists() {
        record(p.clone(), update_cmake(&p, &ver));
    }

    // pyproject.toml
    let p = current_dir.join("pyproject.toml");
    if p.exists() {
        record(
            p.clone(),
            update_lines(&p, |line| {
                if line.starts_with("version = \"") {
                    format!("version = \"{ver}\"")
                } else {
                    line.to_string()
                }
            }),
        );
    }

    // build.zig.zon
    let p = current_dir.join("build.zig.zon");
    if p.exists() {
        let re = Regex::new(r#"(\.version = ")[^"]*(")"#).unwrap();
        record(
            p.clone(),
            update_lines(&p, |line| {
                re.replace(line, |caps: &regex::Captures| format!("{}{}{}", &caps[1], ver, &caps[2]))
                    .into_owned()
            }),
        );
    }

    if !errors.is_empty() {
        let mut msg = String::from("Failed to update one or more files:\n\n");
        for (path, err) in errors {
            msg.push_str(&format!("Failed to update {}:\n{err}\n\n", path.display()));
        }
        return Err(anyhow!(msg));
    }
    Ok(())
}

fn replace_json_version(line: &str, ver: &str) -> String {
    let re = Regex::new(r#"("version":\s*")[^"]*(")"#).unwrap();
    re.replace(line, |caps: &regex::Captures| format!("{}{}{}", &caps[1], ver, &caps[2]))
        .into_owned()
}

fn update_lines(path: &Path, f: impl Fn(&str) -> String) -> Result<()> {
    let content = fs::read_to_string(path)?;
    let mut out = String::new();
    for line in content.lines() {
        out.push_str(&f(line));
        out.push('\n');
    }
    fs::write(path, out)?;
    Ok(())
}

fn update_cmake(path: &Path, ver: &str) -> Result<()> {
    let content = fs::read_to_string(path)?;
    let re = Regex::new(r#"(?m)^(\s+VERSION ")[^"]*(")"#).unwrap();
    let out = re.replace(&content, |caps: &regex::Captures| format!("{}{}{}", &caps[1], ver, &caps[2]));
    let mut out = out.into_owned();
    // normalize to line based output (ensure trailing newline)
    if !out.ends_with('\n') {
        out.push('\n');
    }
    fs::write(path, out)?;
    Ok(())
}
