}

pub struct Loader {
    pub parser_lib_path: PathBuf,
    pub languages_by_id: Vec<LanguageEntry>,
    pub language_configurations: Vec<LanguageConfiguration>,
    pub language_configuration_ids_by_file_type: HashMap<String, Vec<usize>>,
    pub language_configuration_in_current_path: Option<usize>,
    pub language_configuration_ids_by_first_line_regex: HashMap<String, Vec<usize>>,
    pub debug_build: bool,
    pub force_rebuild: bool,
}

impl Loader {
    pub fn new() -> Result<Self> {
        let parser_lib_path = match std::env::var("TREE_SITTER_LIBDIR") {
            Ok(path) => PathBuf::from(path),
            _ => dirs::cache_dir()
                .ok_or_else(|| anyhow!("Cannot determine cache directory"))?
                .join("tree-sitter")
                .join("lib"),
        };
        Ok(Self::with_parser_lib_path(parser_lib_path))
    }

    pub fn with_parser_lib_path(parser_lib_path: PathBuf) -> Self {
        Self {
            parser_lib_path,
            languages_by_id: Vec::new(),
            language_configurations: Vec::new(),
            language_configuration_ids_by_file_type: HashMap::new(),
            language_configuration_in_current_path: None,
            language_configuration_ids_by_first_line_regex: HashMap::new(),
            debug_build: false,
            force_rebuild: false,
        }
    }

    pub fn find_all_languages(&mut self, config: &Config) -> Result<()> {
        let parser_directories = config.parser_directories();
        if parser_directories.is_empty() {
            eprintln!(
                "{} You have not configured any parser directories!\nPlease run `tree-sitter init-config` and edit the resulting\nconfiguration file to indicate where we should look for\nlanguage grammars.\n",
                warning_prefix()
            );
        }
        for parser_container_dir in &parser_directories {
            if let Ok(entries) = fs::read_dir(parser_container_dir) {
                for entry in entries {
                    let entry = entry?;
                    if let Some(parser_dir_name) = entry.file_name().to_str() {
                        if parser_dir_name.starts_with("tree-sitter-") {
                            self.find_language_configurations_at_path(
                                &parser_container_dir.join(parser_dir_name),
                                false,
                            )
                            .ok();
                        }
                    }
                }
            }
        }
        Ok(())
    }

    pub fn find_language_configurations_at_path(
        &mut self,
        parser_path: &Path,
        set_current_path_config: bool,
    ) -> Result<&[LanguageConfiguration]> {
        let initial_language_configuration_count = self.language_configurations.len();

        let ts_json_path = parser_path.join("tree-sitter.json");
        let ts_json = TreeSitterJSON::from_file(&ts_json_path)
            .with_context(|| format!("Failed to read {}", ts_json_path.display()))?;

        for grammar in ts_json.grammars {
            let language_path = parser_path.join(&grammar.path);
            let language_id = match self.languages_by_id.iter().position(|e| e.path == language_path) {
                Some(id) => id,
                None => {
                    self.languages_by_id.push(LanguageEntry {
                        path: language_path,
                        external_files: grammar.external_files.clone().map(|p| {
                            p.into_vec()
                                .into_iter()
                                .map(|f| parser_path.join(f))
                                .collect()
                        }),
                    });
                    self.languages_by_id.len() - 1
                }
            };

            let configuration = LanguageConfiguration {
                root_path: parser_path.to_path_buf(),
                language_name: grammar.name.clone(),
                scope: Some(grammar.scope.clone()),
                language_id,
                file_types: grammar.file_types.clone().unwrap_or_default(),
                content_regex: Self::regex(grammar.content_regex.as_deref()),
                first_line_regex: Self::regex(grammar.first_line_regex.as_deref()),
                injection_regex: Self::regex(grammar.injection_regex.as_deref()),
                injections_filenames: grammar.injections.clone().map(|p| p.into_vec()),
                locals_filenames: grammar.locals.clone().map(|p| p.into_vec()),
                tags_filenames: grammar.tags.clone().map(|p| p.into_vec()),
                highlights_filenames: grammar.highlights.clone().map(|p| p.into_vec()),
            };

            for file_type in &configuration.file_types {
                self.language_configuration_ids_by_file_type
                    .entry(file_type.to_string())
                    .or_default()
                    .push(self.language_configurations.len());
            }
            if let Some(first_line_regex) = &configuration.first_line_regex {
                self.language_configuration_ids_by_first_line_regex
                    .entry(first_line_regex.to_string())
                    .or_default()
                    .push(self.language_configurations.len());
            }

            self.language_configurations.push(configuration);

            if set_current_path_config && self.language_configuration_in_current_path.is_none() {
                self.language_configuration_in_current_path = Some(self.language_configurations.len() - 1);
            }
        }

        if self.language_configurations.len() == initial_language_configuration_count
            && parser_path.join("src").join("grammar.json").exists()
        {
            let language_path = parser_path.to_path_buf();
            let language_id = match self.languages_by_id.iter().position(|e| e.path == language_path) {
                Some(id) => id,
                None => {
                    self.languages_by_id.push(LanguageEntry {
                        path: language_path,
                        external_files: None,
                    });
                    self.languages_by_id.len() - 1
                }
            };
            let grammar_path = parser_path.join("src").join("grammar.json");
            let name = grammar_name_from_json(&grammar_path)?;
            self.language_configurations.push(LanguageConfiguration {
                root_path: parser_path.to_owned(),
                language_name: name,
                language_id,
                file_types: Vec::new(),
                scope: None,
                content_regex: None,
                first_line_regex: None,
                injection_regex: None,
                injections_filenames: None,
                locals_filenames: None,
                tags_filenames: None,
                highlights_filenames: None,
            });
            if set_current_path_config && self.language_configuration_in_current_path.is_none() {
                self.language_configuration_in_current_path = Some(self.language_configurations.len() - 1);
            }
        }

        Ok(&self.language_configurations[initial_language_configuration_count..])
    }

    fn regex(pattern: Option<&str>) -> Option<Regex> {
        pattern.and_then(|r| Regex::new(r).ok())
    }

    pub fn get_all_language_configurations(&self) -> Vec<(&LanguageConfiguration, &Path)> {
        self.language_configurations
            .iter()
            .map(|c| (c, self.languages_by_id[c.language_id].path.as_ref()))
            .collect()
    }
}

pub fn grammar_name_from_json(grammar_path: &Path) -> Result<String> {
    let content = fs::read_to_string(grammar_path)
        .with_context(|| format!("Failed to read grammar file {}", grammar_path.display()))?;
    let value: serde_json::Value = serde_json::from_str(&content)
        .with_context(|| format!("Failed to parse grammar file {}", grammar_path.display()))?;
    value
        .get("name")
        .and_then(|n| n.as_str())
        .map(|s| s.to_string())
        .ok_or_else(|| anyhow!("Grammar file {} is missing a `name` field", grammar_path.display()))
}

pub fn dump_languages(config_path: Option<PathBuf>) -> Result<()> {
    let config = Config::load(config_path)?;
    let mut loader = Loader::new()?;
    loader.find_all_languages(&config)?;
    for (configuration, language_path) in loader.get_all_language_configurations() {
        println!(
            concat!(
                "name: {}\n",
                "scope: {}\n",
                "parser: {:?}\n",
                "highlights: {:?}\n",
                "file_types: {:?}\n",
                "content_regex: {:?}\n",
                "injection_regex: {:?}\n",
            ),
            configuration.language_name,
            configuration.scope.as_ref().unwrap_or(&String::new()),
            language_path,
            configuration.highlights_filenames,
            configuration.file_types,
            configuration.content_regex,
            configuration.injection_regex,
        );
    }
    Ok(())
}
