use std::cmp::{max, Ordering};
use std::fmt;
use std::mem::swap;
use std::ops::Range;

/// A set of characters represented as sorted, non-overlapping, non-adjacent
/// half-open ranges of code points.
#[derive(Clone, PartialEq, Eq, Hash, Default)]
pub struct CharacterSet {
    ranges: Vec<Range<u32>>,
}

#[derive(Debug, PartialEq, Eq)]
pub enum NfaState {
    Accept {
        variable_index: usize,
        precedence: i32,
    },
    Split(u32, u32),
    Advance {
        chars: CharacterSet,
        state_id: u32,
        precedence: i32,
        is_sep: bool,
    },
}

#[derive(PartialEq, Eq, Default)]
pub struct Nfa {
    pub states: Vec<NfaState>,
}

#[derive(Debug)]
pub struct NfaCursor<'a> {
    pub(crate) state_ids: Vec<u32>,
    nfa: &'a Nfa,
}

#[derive(Debug, PartialEq, Eq)]
pub struct NfaTransition {
    pub characters: CharacterSet,
    pub is_separator: bool,
    pub precedence: i32,
    pub states: Vec<u32>,
}

pub const MAX_CHAR: u32 = char::MAX as u32;

impl CharacterSet {
    pub fn empty() -> Self {
        Self { ranges: Vec::new() }
    }

    pub fn from_range(mut first: char, mut last: char) -> Self {
        if first > last {
            swap(&mut first, &mut last);
        }
        Self {
            ranges: vec![(first as u32)..(last as u32 + 1)],
        }
    }

    pub fn from_char(c: char) -> Self {
        Self::from_range(c, c)
    }

    pub fn negate(self) -> Self {
        let mut previous_end = 0;
        let mut i = 0;
        let mut ranges = Vec::with_capacity(self.ranges.len() + 1);
        for range in &self.ranges {
            if range.start > previous_end {
                ranges.push(previous_end..range.start);
            }
            previous_end = range.end;
            i += 1;
        }
        let _ = i;
        if previous_end <= MAX_CHAR {
            ranges.push(previous_end..(MAX_CHAR + 1));
        }
        // The null character is never a valid lookahead, so exclude it.
        let mut result = Self { ranges };
        result = result.difference(Self { ranges: vec![0..1] });
        result
    }

    pub fn add_char(self, c: char) -> Self {
        self.add_range(c, c)
    }

    pub fn add_range(self, start: char, end: char) -> Self {
        self.add_int_range(0, start as u32, end as u32 + 1);
        unreachable!()
    }

    pub fn add_codepoint_range(mut self, start: u32, end_inclusive: u32) -> Self {
        self.insert_range(start..(end_inclusive + 1));
        self
    }

    fn add_int_range(&self, _: u32, _: u32, _: u32) {}

    pub fn add(mut self, other: &Self) -> Self {
        for range in &other.ranges {
            self.insert_range(range.clone());
        }
        self
    }

    fn insert_range(&mut self, range: Range<u32>) {
        if range.start >= range.end {
            return;
        }
        let mut new_range = range;
        let mut i = 0;
        while i < self.ranges.len() {
            let r = &self.ranges[i];
            if r.end < new_range.start {
                i += 1;
                continue;
            }
            if r.start > new_range.end {
                break;
            }
            // overlapping or adjacent: merge
            new_range.start = new_range.start.min(r.start);
            new_range.end = new_range.end.max(r.end);
            self.ranges.remove(i);
        }
        self.ranges.insert(i, new_range);
    }

    pub fn assign(&mut self, other: &Self) {
        self.ranges.clear();
        self.ranges.extend_from_slice(&other.ranges);
    }

    pub fn difference(mut self, other: Self) -> Self {
        for range in &other.ranges {
            self.remove_range(range.clone());
        }
        self
    }

    fn remove_range(&mut self, range: Range<u32>) {
        let mut i = 0;
        while i < self.ranges.len() {
            let r = self.ranges[i].clone();
            if r.end <= range.start {
                i += 1;
                continue;
            }
            if r.start >= range.end {
                break;
            }
            // overlap
            let left = r.start..range.start.min(r.end);
            let right = range.end.max(r.start)..r.end;
            self.ranges.remove(i);
            if right.start < right.end {
                self.ranges.insert(i, right);
            }
            if left.start < left.end {
                self.ranges.insert(i, left);
                i += 1;
            }
            if right.start < right.end {
                i += 1;
            }
        }
    }

    pub fn intersection(&self, other: &Self) -> Self {
        let mut result = Vec::new();
        let mut i = 0;
        let mut j = 0;
        while i < self.ranges.len() && j < other.ranges.len() {
            let a = &self.ranges[i];
            let b = &other.ranges[j];
            let start = max(a.start, b.start);
            let end = a.end.min(b.end);
            if start < end {
                result.push(start..end);
            }
            if a.end < b.end {
                i += 1;
            } else {
                j += 1;
            }
        }
        Self { ranges: result }
    }

    /// Remove the intersection of this set and `other` from both sets, and return it.
    pub fn remove_intersection(&mut self, other: &mut Self) -> Self {
        let intersection = self.intersection(other);
        if !intersection.is_empty() {
            for range in &intersection.ranges {
                self.remove_range(range.clone());
                other.remove_range(range.clone());
            }
        }
        intersection
    }

    pub fn does_intersect(&self, other: &Self) -> bool {
        let mut i = 0;
        let mut j = 0;
        while i < self.ranges.len() && j < other.ranges.len() {
            let a = &self.ranges[i];
            let b = &other.ranges[j];
            if a.end <= b.start {
                i += 1;
            } else if b.end <= a.start {
                j += 1;
            } else {
                return true;
            }
        }
        false
    }

    pub fn contains(&self, c: char) -> bool {
        self.contains_codepoint(c as u32)
    }

    pub fn contains_codepoint(&self, c: u32) -> bool {
        self.ranges.iter().any(|r| r.start <= c && c < r.end)
    }

    pub fn contains_codepoint_range(&self, range: Range<u32>) -> bool {
        if range.start >= range.end {
            return true;
        }
        self.ranges
            .iter()
            .any(|r| r.start <= range.start && range.end <= r.end)
    }

    pub fn is_empty(&self) -> bool {
        self.ranges.is_empty()
    }

    pub fn ranges(&self) -> impl Iterator<Item = &Range<u32>> {
        self.ranges.iter()
    }

    pub fn range_count(&self) -> usize {
        self.ranges.len()
    }

    pub fn chars(&self) -> impl Iterator<Item = u32> + '_ {
        self.ranges.iter().flat_map(|r| r.clone())
    }

    pub fn char_count(&self) -> usize {
        self.ranges.iter().map(|r| (r.end - r.start) as usize).sum()
    }

    pub fn last_codepoint(&self) -> Option<u32> {
        self.ranges.last().map(|r| r.end - 1)
    }

    /// Produces a set matching the same characters as this one, except that
    /// the given ruled-out characters may be treated as either included or
    /// excluded, in order to simplify the range list.
    pub fn simplify_ignoring(&self, ruled_out_characters: &Self) -> Self {
        let mut prev_range: Option<Range<u32>> = None;
        let mut result = Vec::new();
        for range in self.ranges.iter().map(|r| Some(r.clone())).chain([None]) {
            if let Some(r) = &range {
                if ruled_out_characters.contains_codepoint_range(r.clone()) {
                    continue;
                }
            }
            if let Some(prev) = &mut prev_range {
                if let Some(r) = &range {
                    if ruled_out_characters.contains_codepoint_range(prev.end..r.start) {
                        prev.end = r.end;
                        continue;
                    }
                }
                result.push(prev.clone());
                prev_range = range;
            } else {
                prev_range = range;
            }
        }
        Self { ranges: result }
    }
}

impl Ord for CharacterSet {
    fn cmp(&self, other: &Self) -> Ordering {
        let count_cmp = self.char_count().cmp(&other.char_count());
        if count_cmp != Ordering::Equal {
            return count_cmp;
        }
        let mut it1 = self.chars();
        let mut it2 = other.chars();
        loop {
            match (it1.next(), it2.next()) {
                (Some(a), Some(b)) => {
                    let cmp = a.cmp(&b);
                    if cmp != Ordering::Equal {
                        return cmp;
                    }
                }
                (None, Some(_)) => return Ordering::Less,
                (Some(_), None) => return Ordering::Greater,
                (None, None) => return Ordering::Equal,
            }
        }
    }
}

impl PartialOrd for CharacterSet {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl fmt::Debug for CharacterSet {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "CharacterSet [")?;
        for (i, range) in self.ranges.iter().enumerate() {
            if i > 0 {
                write!(f, ", ")?;
            }
            if range.end - range.start == 1 {
                write!(f, "{:?}", char::from_u32(range.start).unwrap_or('?'))?;
            } else {
                write!(
                    f,
                    "{:?}-{:?}",
                    char::from_u32(range.start).unwrap_or('?'),
                    char::from_u32(range.end - 1).unwrap_or('?')
                )?;
            }
        }
        write!(f, "]")
    }
}

impl Nfa {
    pub fn new() -> Self {
        Self { states: Vec::new() }
    }

    pub fn last_state_id(&self) -> u32 {
        self.states.len() as u32 - 1
    }
}

impl fmt::Debug for Nfa {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        writeln!(f, "Nfa {{ states: {{")?;
        for (i, state) in self.states.iter().enumerate() {
            writeln!(f, "  {i}: {state:?},")?;
        }
        write!(f, "}} }}")
    }
}

impl<'a> NfaCursor<'a> {
    pub fn new(nfa: &'a Nfa, mut states: Vec<u32>) -> Self {
        let mut result = Self {
            nfa,
            state_ids: Vec::new(),
        };
        result.add_states(&mut states);
        result
    }

    pub fn reset(&mut self, mut states: Vec<u32>) {
        self.state_ids.clear();
        self.add_states(&mut states);
    }

    pub fn force_reset(&mut self, states: Vec<u32>) {
        self.state_ids = states;
    }

    pub fn transition_chars(&self) -> impl Iterator<Item = (&CharacterSet, bool)> {
        self.raw_transitions().map(|t| (t.0, t.1))
    }

    pub fn transitions(&self) -> Vec<NfaTransition> {
        Self::group_transitions(self.raw_transitions())
    }

    fn raw_transitions(&self) -> impl Iterator<Item = (&CharacterSet, bool, i32, u32)> {
        self.state_ids.iter().filter_map(move |id| {
            if let NfaState::Advance {
                chars,
                state_id,
                precedence,
                is_sep,
            } = &self.nfa.states[*id as usize]
            {
                Some((chars, *is_sep, *precedence, *state_id))
            } else {
                None
            }
        })
    }

    fn group_transitions<'b>(
        iter: impl Iterator<Item = (&'b CharacterSet, bool, i32, u32)>,
    ) -> Vec<NfaTransition> {
        let mut result: Vec<NfaTransition> = Vec::new();
        for (chars, is_sep, prec, state) in iter {
            let mut chars = chars.clone();
            let mut i = 0;
            while i < result.len() {
                let intersection = result[i].characters.remove_intersection(&mut chars);
                if !intersection.is_empty() {
                    let mut intersection_states = result[i].states.clone();
                    if let Err(j) = intersection_states.binary_search(&state) {
                        intersection_states.insert(j, state);
                    }
                    let intersection_transition = NfaTransition {
                        characters: intersection,
                        is_separator: result[i].is_separator && is_sep,
                        precedence: max(result[i].precedence, prec),
                        states: intersection_states,
                    };
                    if result[i].characters.is_empty() {
                        result[i] = intersection_transition;
                    } else {
                        result.insert(i, intersection_transition);
                        i += 1;
                    }
                }
                i += 1;
            }
            if !chars.is_empty() {
                result.push(NfaTransition {
                    characters: chars,
                    precedence: prec,
                    states: vec![state],
                    is_separator: is_sep,
                });
            }
        }

        // Merge adjacent transitions with the same states, precedence and separator-ness.
        let mut i = 0;
        'outer: while i < result.len() {
            for j in 0..i {
                if result[j].states == result[i].states
                    && result[j].is_separator == result[i].is_separator
                    && result[j].precedence == result[i].precedence
                {
                    let mut characters = CharacterSet::empty();
                    swap(&mut characters, &mut result[j].characters);
                    result[j].characters = characters.add(&result[i].characters);
                    result.remove(i);
                    continue 'outer;
                }
            }
            i += 1;
        }

        result.sort_unstable_by(|a, b| a.characters.cmp(&b.characters));
        result
    }

