                Ok(did_push)
            }
            Rule::Reserved { rule, context_name } => {
                let id = self
                    .reserved_word_set_names
                    .iter()
                    .position(|n| *n == context_name)
                    .ok_or_else(|| anyhow!("Undeclared reserved word set '{context_name}'"))?;
                self.reserved_word_stack.push(id + 1);
                let did_push = self.apply(*rule, at_end)?;
                self.reserved_word_stack.pop();
                Ok(did_push)
            }
            Rule::Symbol(symbol) => {
                self.production.steps.push(ProductionStep {
                    symbol,
                    precedence: self
                        .precedence_stack
                        .last()
                        .cloned()
                        .unwrap_or(Precedence::None),
                    associativity: self.associativity_stack.last().copied(),
                    alias: self.alias_stack.last().cloned(),
                    field_name: self.field_name_stack.last().cloned(),
                    reserved_word_set_id: self.reserved_word_stack.last().copied().unwrap_or(0),
                });
                Ok(true)
            }
            _ => Ok(false),
        }
    }
}

fn extract_choices(rule: Rule) -> Vec<Rule> {
    match rule {
        Rule::Seq(elements) => {
            let mut result = vec![Rule::Blank];
            for element in elements {
                let extraction = extract_choices(element);
                let mut next_result = Vec::new();
                for entry in result {
                    for extraction_entry in &extraction {
                        next_result.push(Rule::Seq(vec![entry.clone(), extraction_entry.clone()]));
                    }
                }
                result = next_result;
            }
            result
        }
        Rule::Choice(elements) => {
            let mut result = Vec::new();
            for element in elements {
                for rule in extract_choices(element) {
                    result.push(rule);
                }
            }
            result
        }
        Rule::Metadata { rule, params } => extract_choices(*rule)
            .into_iter()
            .map(|rule| Rule::Metadata {
                rule: Box::new(rule),
                params: params.clone(),
            })
            .collect(),
        Rule::Reserved { rule, context_name } => extract_choices(*rule)
            .into_iter()
            .map(|rule| Rule::Reserved {
                rule: Box::new(rule),
                context_name: context_name.clone(),
            })
            .collect(),
        _ => vec![rule],
    }
}

fn symbol_is_used(variables: &[SyntaxVariable], symbol: Symbol) -> bool {
    for variable in variables {
        for production in &variable.productions {
            for step in &production.steps {
                if step.symbol == symbol {
                    return true;
                }
            }
        }
    }
    false
}

pub(super) fn flatten_grammar(grammar: ExtractedSyntaxGrammar) -> Result<SyntaxGrammar> {
    let reserved_word_set_names: Vec<String> =
        grammar.reserved_words.iter().map(|c| c.name.clone()).collect();
    let mut flattener = RuleFlattener::new(reserved_word_set_names);

    let mut variables = Vec::new();
    for variable in grammar.variables {
        variables.push(flattener.flatten_variable(variable)?);
    }

    for (i, variable) in variables.iter().enumerate() {
        for production in &variable.productions {
            if i > 0 && production.steps.is_empty() && symbol_is_used(&variables, Symbol::non_terminal(i)) {
                return Err(anyhow!(
                    "The rule `{}` matches the empty string.\n\nTree-sitter does not support syntactic rules that match the empty string\nunless they are used only as the grammar's start rule.\n",
                    variable.name
                ));
            }
        }
    }

    // Build the reserved word sets. Set 0 is the default (global) set.
    let mut reserved_word_sets = Vec::with_capacity(grammar.reserved_words.len() + 1);
    reserved_word_sets.push(TokenSet::new());
    for context in &grammar.reserved_words {
        let mut set = TokenSet::new();
        for rule in &context.reserved_words {
            if let Rule::Symbol(symbol) = rule {
                set.insert(*symbol);
            } else {
                return Err(anyhow!(
                    "Reserved word set `{}` contains a non-token rule",
                    context.name
                ));
            }
        }
        reserved_word_sets.push(set);
    }

    Ok(SyntaxGrammar {
        extra_symbols: grammar.extra_symbols,
        expected_conflicts: grammar.expected_conflicts,
        variables_to_inline: grammar.variables_to_inline,
        precedence_orderings: grammar.precedence_orderings,
        external_tokens: grammar.external_tokens,
        supertype_symbols: grammar.supertype_symbols,
        word_token: grammar.word_token,
        variables,
        reserved_word_sets,
    })
}
