use super::ExtractedLexicalGrammar;
use crate::generate::grammars::{LexicalGrammar, LexicalVariable};
use crate::generate::nfa::{CharacterSet, Nfa, NfaState};
use crate::generate::rules::{Precedence, Rule};
use anyhow::{anyhow, Context, Result};
use regex_syntax::ast::{
    parse, Ast, ClassAsciiKind, ClassBracketed, ClassPerlKind, ClassSet, ClassSetBinaryOpKind,
    ClassSetItem, ClassUnicodeKind, RepetitionKind, RepetitionRange,
};

struct NfaBuilder {
    nfa: Nfa,
    is_sep: bool,
    precedence_stack: Vec<i32>,
}

/// Preprocess a JS-style regex so that it can be parsed by the Rust regex parser.
pub fn preprocess_regex(content: &str) -> String {
    let mut result = String::with_capacity(content.len());
    let mut is_escaped = false;
    for c in content.chars() {
        if is_escaped {
            if c != '/' {
                result.push('\\');
            }
            result.push(c);
            is_escaped = false;
        } else if c == '\\' {
            is_escaped = true;
        } else {
            result.push(c);
        }
    }
    if is_escaped {
        result.push('\\');
    }
    result
}

pub(super) fn expand_tokens(mut grammar: ExtractedLexicalGrammar) -> Result<LexicalGrammar> {
    let mut builder = NfaBuilder {
        nfa: Nfa::new(),
        is_sep: true,
        precedence_stack: vec![0],
    };

    let separator_rule = if grammar.separators.is_empty() {
        Rule::Blank
    } else {
        grammar.separators.push(Rule::Blank);
        Rule::repeat(Rule::choice(grammar.separators))
    };

    let mut variables = Vec::new();
    for (i, variable) in grammar.variables.into_iter().enumerate() {
        let is_immediate_token = match &variable.rule {
            Rule::Metadata { params, .. } => params.is_main_token,
            _ => false,
        };

        builder.is_sep = false;
        builder.nfa.states.push(NfaState::Accept {
            variable_index: i,
            precedence: 0,
        });
        let last_state_id = builder.nfa.last_state_id();
        builder
            .expand_rule(&variable.rule, last_state_id)
            .with_context(|| format!("Error processing rule {}", variable.name))?;

        if !is_immediate_token {
            builder.is_sep = true;
            let last_state_id = builder.nfa.last_state_id();
            builder
                .expand_rule(&separator_rule, last_state_id)
                .with_context(|| format!("Error processing rule {}", variable.name))?;
        }

        variables.push(LexicalVariable {
            name: variable.name,
            kind: variable.kind,
            implicit_precedence: 0,
            start_state: builder.nfa.last_state_id(),
        });
    }

    Ok(LexicalGrammar {
        nfa: builder.nfa,
        variables,
    })
}

#[derive(Debug)]
enum ExpandErr {
    Parse(String),
    ExpandRegex(ExpandRegexErr),
}

#[derive(Debug)]
enum ExpandRegexErr {
    Flags,
    Assertion,
    #[allow(dead_code)]
    UnicodeClass(String),
}

impl NfaBuilder {
    fn expand_rule(&mut self, rule: &Rule, mut next_state_id: u32) -> Result<bool> {
        match rule {
            Rule::Pattern(s, f) => {
                let s = preprocess_regex(s);
                let ast = match parse::Parser::new().parse(&s) {
                    Ok(ast) => ast,
                    Err(e) => {
                        return Err(anyhow!(
                            "Grammar error: Unexpected rule {:?}",
                            ExpandErr::Parse(e.to_string())
                        ))
                    }
                };
                match self.expand_regex(&ast, next_state_id, f.contains('i')) {
                    Ok(r) => Ok(r),
                    Err(e) => Err(anyhow!(
                        "Grammar error: Unexpected rule {:?}",
                        ExpandErr::ExpandRegex(e)
                    )),
                }
            }
            Rule::String(s) => {
                for c in s.chars().rev() {
                    self.push_advance(CharacterSet::empty().add_char(c), next_state_id);
                    next_state_id = self.nfa.last_state_id();
                }
                Ok(!s.is_empty())
            }
            Rule::Choice(elements) => {
                let mut alternative_state_ids = Vec::new();
                for element in elements {
                    if self.expand_rule(element, next_state_id)? {
                        alternative_state_ids.push(self.nfa.last_state_id());
                    } else {
                        alternative_state_ids.push(next_state_id);
                    }
                }
                alternative_state_ids.sort_unstable();
                alternative_state_ids.dedup();
                alternative_state_ids.retain(|i| *i != self.nfa.last_state_id());
                for alternative_state_id in alternative_state_ids {
                    self.push_split(alternative_state_id);
                }
                Ok(true)
            }
            Rule::Seq(elements) => {
                let mut result = false;
                for element in elements.iter().rev() {
                    if self.expand_rule(element, next_state_id)? {
                        result = true;
                    }
                    next_state_id = self.nfa.last_state_id();
                }
                Ok(result)
            }
            Rule::Repeat(rule) => {
                self.nfa.states.push(NfaState::Accept {
                    variable_index: 0,
                    precedence: 0,
                }); // Placeholder for split
                let split_state_id = self.nfa.last_state_id();
                if self.expand_rule(rule, split_state_id)? {
                    self.nfa.states[split_state_id as usize] =
                        NfaState::Split(self.nfa.last_state_id(), next_state_id);
                    Ok(true)
                } else {
                    Ok(false)
                }
            }
            Rule::Metadata { rule, params } => {
                let has_precedence = if let Precedence::Integer(precedence) = &params.precedence {
                    self.precedence_stack.push(*precedence);
                    true
                } else {
                    false
                };
                let result = self.expand_rule(rule, next_state_id);
                if has_precedence {
                    self.precedence_stack.pop();
                }
                result
            }
            Rule::Blank => Ok(false),
            _ => Err(anyhow!("Grammar error: Unexpected rule {rule:?}")),
        }
    }

    fn expand_regex(
        &mut self,
        ast: &Ast,
        mut next_state_id: u32,
        case_insensitive: bool,
    ) -> Result<bool, ExpandRegexErr> {
        match ast {
            Ast::Empty(_) => Ok(false),
            Ast::Flags(_) => Err(ExpandRegexErr::Flags),
            Ast::Literal(literal) => {
                let mut char_set = CharacterSet::from_char(literal.c);
                if case_insensitive {
                    char_set = add_case_variants(char_set, literal.c);
                }
                self.push_advance(char_set, next_state_id);
                Ok(true)
            }
            Ast::Dot(_) => {
                self.push_advance(CharacterSet::from_char('\n').negate(), next_state_id);
                Ok(true)
            }
            Ast::Assertion(_) => Err(ExpandRegexErr::Assertion),
            Ast::ClassUnicode(class) => {
                let mut chars = self.expand_unicode_character_class(&class.kind)?;
                if class.negated {
                    chars = chars.negate();
                }
                self.push_advance(chars, next_state_id);
                Ok(true)
            }
            Ast::ClassPerl(class) => {
                let mut chars = self.expand_perl_character_class(&class.kind);
                if class.negated {
                    chars = chars.negate();
                }
                self.push_advance(chars, next_state_id);
                Ok(true)
            }
            Ast::ClassBracketed(class) => {
                let mut chars = self.translate_class_set(&class.kind, case_insensitive)?;
                if class.negated {
                    chars = chars.negate();
                }
                self.push_advance(chars, next_state_id);
                Ok(true)
            }
            Ast::Repetition(repetition) => match repetition.op.kind {
                RepetitionKind::ZeroOrOne => {
                    self.expand_zero_or_one(&repetition.ast, next_state_id, case_insensitive)
                }
                RepetitionKind::OneOrMore => {
                    self.expand_one_or_more(&repetition.ast, next_state_id, case_insensitive)
                }
                RepetitionKind::ZeroOrMore => {
                    self.expand_zero_or_more(&repetition.ast, next_state_id, case_insensitive)
                }
                RepetitionKind::Range(RepetitionRange::Exactly(count)) => {
                    self.expand_count(&repetition.ast, count, next_state_id, case_insensitive)
                }
                RepetitionKind::Range(RepetitionRange::AtLeast(min)) => {
                    if self.expand_zero_or_more(&repetition.ast, next_state_id, case_insensitive)? {
                        self.expand_count(
                            &repetition.ast,
                            min,
                            self.nfa.last_state_id(),
                            case_insensitive,
                        )
                    } else {
                        Ok(false)
                    }
                }
                RepetitionKind::Range(RepetitionRange::Bounded(min, max)) => {
                    let mut result =
                        self.expand_count(&repetition.ast, min, next_state_id, case_insensitive)?;
                    for _ in min..max {
                        if result {
                            next_state_id = self.nfa.last_state_id();
                        }
                        if self.expand_zero_or_one(&repetition.ast, next_state_id, case_insensitive)? {
                            result = true;
                        }
                    }
                    Ok(result)
                }
            },
            Ast::Group(group) => self.expand_regex(&group.ast, next_state_id, case_insensitive),
            Ast::Alternation(alternation) => {
                let mut alternative_state_ids = Vec::new();
                for ast in &alternation.asts {
                    if self.expand_regex(ast, next_state_id, case_insensitive)? {
                        alternative_state_ids.push(self.nfa.last_state_id());
                    } else {
                        alternative_state_ids.push(next_state_id);
                    }
                }
                alternative_state_ids.sort_unstable();
                alternative_state_ids.dedup();
                alternative_state_ids.retain(|i| *i != self.nfa.last_state_id());
                for alternative_state_id in alternative_state_ids {
                    self.push_split(alternative_state_id);
                }
                Ok(true)
            }
            Ast::Concat(concat) => {
                let mut result = false;
                for ast in concat.asts.iter().rev() {
                    if self.expand_regex(ast, next_state_id, case_insensitive)? {
                        result = true;
                        next_state_id = self.nfa.last_state_id();
                    }
                }
                Ok(result)
            }
        }
    }

    fn translate_class_set(
        &self,
        class_set: &ClassSet,
        case_insensitive: bool,
    ) -> Result<CharacterSet, ExpandRegexErr> {
        match &class_set {
            ClassSet::Item(item) => self.expand_character_class(item, case_insensitive),
            ClassSet::BinaryOp(binary_op) => {
                let mut lhs_char_class = self.translate_class_set(&binary_op.lhs, case_insensitive)?;
                let mut rhs_char_class = self.translate_class_set(&binary_op.rhs, case_insensitive)?;
                match binary_op.kind {
                    ClassSetBinaryOpKind::Intersection => {
                        Ok(lhs_char_class.remove_intersection(&mut rhs_char_class))
                    }
                    ClassSetBinaryOpKind::Difference => {
                        Ok(lhs_char_class.difference(rhs_char_class))
                    }
                    ClassSetBinaryOpKind::SymmetricDifference => {
                        Ok(lhs_char_class.symmetric_difference(rhs_char_class))
                    }
                }
            }
        }
    }

    fn expand_one_or_more(
        &mut self,
        ast: &Ast,
        next_state_id: u32,
        case_insensitive: bool,
    ) -> Result<bool, ExpandRegexErr> {
        self.nfa.states.push(NfaState::Accept {
            variable_index: 0,
            precedence: 0,
        }); // Placeholder for split
        let split_state_id = self.nfa.last_state_id();
        if self.expand_regex(ast, split_state_id, case_insensitive)? {
            self.nfa.states[split_state_id as usize] =
                NfaState::Split(self.nfa.last_state_id(), next_state_id);
            Ok(true)
        } else {
            self.nfa.states.pop();
            Ok(false)
        }
    }

    fn expand_zero_or_one(
        &mut self,
        ast: &Ast,
        next_state_id: u32,
        case_insensitive: bool,
    ) -> Result<bool, ExpandRegexErr> {
        if self.expand_regex(ast, next_state_id, case_insensitive)? {
            self.push_split(next_state_id);
            Ok(true)
        } else {
            Ok(false)
        }
    }

    fn expand_zero_or_more(
        &mut self,
        ast: &Ast,
        next_state_id: u32,
        case_insensitive: bool,
    ) -> Result<bool, ExpandRegexErr> {
        if self.expand_one_or_more(ast, next_state_id, case_insensitive)? {
            self.push_split(next_state_id);
            Ok(true)
        } else {
            Ok(false)
        }
    }

    fn expand_count(
        &mut self,
        ast: &Ast,
        count: u32,
        mut next_state_id: u32,
        case_insensitive: bool,
    ) -> Result<bool, ExpandRegexErr> {
        let mut result = false;
        for _ in 0..count {
            if self.expand_regex(ast, next_state_id, case_insensitive)? {
                result = true;
                next_state_id = self.nfa.last_state_id();
            }
        }
        Ok(result)
    }

    fn expand_character_class(
        &self,
        item: &ClassSetItem,
        case_insensitive: bool,
    ) -> Result<CharacterSet, ExpandRegexErr> {
        match item {
            ClassSetItem::Empty(_) => Ok(CharacterSet::empty()),
            ClassSetItem::Literal(literal) => {
                let mut set = CharacterSet::from_char(literal.c);
                if case_insensitive {
                    set = add_case_variants(set, literal.c);
                }
                Ok(set)
            }
            ClassSetItem::Range(range) => {
                let mut set = CharacterSet::from_range(range.start.c, range.end.c);
                if case_insensitive {
                    for c in range.start.c..=range.end.c {
                        set = add_case_variants(set, c);
                    }
                }
                Ok(set)
            }
            ClassSetItem::Ascii(class) => Ok(self.expand_ascii_character_class(class)),
            ClassSetItem::Unicode(class) => {
                let mut set = self.expand_unicode_character_class(&class.kind)?;
                if class.negated {
                    set = set.negate();
                }
                Ok(set)
            }
            ClassSetItem::Perl(class) => {
                let mut set = self.expand_perl_character_class(&class.kind);
                if class.negated {
                    set = set.negate();
                }
                Ok(set)
            }
            ClassSetItem::Bracketed(class) => {
                let mut set = self.translate_class_set(&class.kind, case_insensitive)?;
                if class.negated {
                    set = set.negate();
                }
                Ok(set)
            }
            ClassSetItem::Union(union) => {
                let mut result = CharacterSet::empty();
                for item in &union.items {
                    result = result.add(&self.expand_character_class(item, case_insensitive)?);
                }
                Ok(result)
            }
        }
    }

    fn expand_ascii_character_class(&self, class: &regex_syntax::ast::ClassAscii) -> CharacterSet {
        let mut set = match class.kind {
            ClassAsciiKind::Alnum => CharacterSet::empty()
                .add_range('a', 'z')
                .add_range('A', 'Z')
                .add_range('0', '9'),
            ClassAsciiKind::Alpha => CharacterSet::empty().add_range('a', 'z').add_range('A', 'Z'),
            ClassAsciiKind::Ascii => CharacterSet::empty().add_range('\x00', '\x7f'),
            ClassAsciiKind::Blank => CharacterSet::empty().add_char(' ').add_char('\t'),
            ClassAsciiKind::Cntrl => CharacterSet::empty().add_range('\x00', '\x1f').add_char('\x7f'),
            ClassAsciiKind::Digit => CharacterSet::empty().add_range('0', '9'),
            ClassAsciiKind::Graph => CharacterSet::empty().add_range('!', '~'),
            ClassAsciiKind::Lower => CharacterSet::empty().add_range('a', 'z'),
            ClassAsciiKind::Print => CharacterSet::empty().add_range(' ', '~'),
            ClassAsciiKind::Punct => CharacterSet::empty()
                .add_range('!', '/')
                .add_range(':', '@')
                .add_range('[', '`')
                .add_range('{', '~'),
            ClassAsciiKind::Space => CharacterSet::empty()
                .add_char(' ')
                .add_char('\t')
                .add_char('\n')
                .add_char('\x0b')
                .add_char('\x0c')
                .add_char('\r'),
            ClassAsciiKind::Upper => CharacterSet::empty().add_range('A', 'Z'),
            ClassAsciiKind::Word => CharacterSet::empty()
                .add_range('a', 'z')
                .add_range('A', 'Z')
                .add_range('0', '9')
                .add_char('_'),
            ClassAsciiKind::Xdigit => CharacterSet::empty()
                .add_range('0', '9')
                .add_range('a', 'f')
                .add_range('A', 'F'),
        };
        if class.negated {
            set = set.negate();
        }
        set
    }

    fn expand_perl_character_class(&self, item: &ClassPerlKind) -> CharacterSet {
        match item {
            ClassPerlKind::Digit => CharacterSet::empty().add_range('0', '9'),
            ClassPerlKind::Space => CharacterSet::empty()
                .add_char(' ')
                .add_char('\t')
                .add_char('\r')
                .add_char('\n')
                .add_char('\x0b')
                .add_char('\x0c'),
            ClassPerlKind::Word => CharacterSet::empty()
                .add_char('_')
                .add_range('A', 'Z')
                .add_range('a', 'z')
                .add_range('0', '9'),
        }
    }

    fn expand_unicode_character_class(
        &self,
        kind: &ClassUnicodeKind,
    ) -> Result<CharacterSet, ExpandRegexErr> {
        let name = match kind {
            ClassUnicodeKind::OneLetter(c) => c.to_string(),
            ClassUnicodeKind::Named(name) => name.clone(),
            ClassUnicodeKind::NamedValue { name, value, .. } => format!("{name}={value}"),
        };
        super::super::unicode::character_set_for_class(&name)
            .ok_or_else(|| ExpandRegexErr::UnicodeClass(name))
    }

    fn push_advance(&mut self, chars: CharacterSet, state_id: u32) {
        let precedence = *self.precedence_stack.last().unwrap();
        self.nfa.states.push(NfaState::Advance {
            chars,
            state_id,
            precedence,
            is_sep: self.is_sep,
        });
    }

    fn push_split(&mut self, state_id: u32) {
        let last_state_id = self.nfa.last_state_id();
        self.nfa
            .states
            .push(NfaState::Split(state_id, last_state_id));
    }
}

fn add_case_variants(mut set: CharacterSet, c: char) -> CharacterSet {
    for lower in c.to_lowercase() {
        set = set.add_char(lower);
    }
    for upper in c.to_uppercase() {
        set = set.add_char(upper);
    }
    set
}
