use super::nfa::CharacterSet;

/// Returns the set of characters for a unicode character class, if known.
pub fn character_set_for_class(name: &str) -> Option<CharacterSet> {
    // Only a small set of general categories is supported here.
    let ranges: &[(u32, u32)] = match name {
        "L" | "Letter" => LETTER_RANGES,
        "Lu" | "Uppercase_Letter" => UPPERCASE_RANGES,
        "Ll" | "Lowercase_Letter" => LOWERCASE_RANGES,
        "N" | "Number" | "Nd" | "Decimal_Number" => DIGIT_RANGES,
        _ => return None,
    };
    let mut set = CharacterSet::empty();
    for (start, end) in ranges {
        set = set.add_codepoint_range(*start, *end);
    }
    Some(set)
}

