    dynamic_precedence: 0,
    steps: vec![ProductionStep {
        symbol: Symbol {
            index: 0,
            kind: SymbolType::NonTerminal,
        },
        precedence: Precedence::None,
        associativity: None,
        alias: None,
        field_name: None,
        reserved_word_set_id: 0,
    }],
});

/// A set of tokens, represented as bit vectors over terminals and externals,
/// plus flags for the special end-of-input tokens.
#[derive(Clone, Debug, Default, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct TokenSet {
    terminal_bits: Vec<bool>,
    external_bits: Vec<bool>,
    eof: bool,
    end_of_nonterminal_extra: bool,
}

impl TokenSet {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn iter(&self) -> impl Iterator<Item = Symbol> + '_ {
        self.terminal_bits
            .iter()
            .enumerate()
            .filter_map(|(i, b)| if *b { Some(Symbol::terminal(i)) } else { None })
            .chain(
                self.external_bits
                    .iter()
                    .enumerate()
                    .filter_map(|(i, b)| if *b { Some(Symbol::external(i)) } else { None }),
            )
            .chain(if self.eof { Some(Symbol::end()) } else { None })
            .chain(if self.end_of_nonterminal_extra {
                Some(Symbol::end_of_nonterminal_extra())
            } else {
                None
            })
    }

    pub fn terminals(&self) -> impl Iterator<Item = Symbol> + '_ {
        self.terminal_bits
            .iter()
            .enumerate()
            .filter_map(|(i, b)| if *b { Some(Symbol::terminal(i)) } else { None })
    }

    pub fn contains(&self, symbol: &Symbol) -> bool {
        match symbol.kind {
            SymbolType::NonTerminal => panic!("Cannot store non-terminals in a TokenSet"),
            SymbolType::Terminal => self.terminal_bits.get(symbol.index).copied().unwrap_or(false),
            SymbolType::External => self.external_bits.get(symbol.index).copied().unwrap_or(false),
            SymbolType::End => self.eof,
            SymbolType::EndOfNonTerminalExtra => self.end_of_nonterminal_extra,
        }
    }

    pub fn contains_terminal(&self, index: usize) -> bool {
        self.terminal_bits.get(index).copied().unwrap_or(false)
    }

    pub fn insert(&mut self, other: Symbol) -> bool {
        let vec = match other.kind {
            SymbolType::NonTerminal => panic!("Cannot store non-terminals in a TokenSet"),
            SymbolType::Terminal => &mut self.terminal_bits,
            SymbolType::External => &mut self.external_bits,
            SymbolType::End => {
                let result = !self.eof;
                self.eof = true;
                return result;
            }
            SymbolType::EndOfNonTerminalExtra => {
                let result = !self.end_of_nonterminal_extra;
                self.end_of_nonterminal_extra = true;
                return result;
            }
        };
        if other.index >= vec.len() {
            vec.resize(other.index + 1, false);
        }
        let result = !vec[other.index];
        vec[other.index] = true;
        result
    }

    pub fn remove(&mut self, other: &Symbol) -> bool {
        let vec = match other.kind {
            SymbolType::NonTerminal => panic!("Cannot store non-terminals in a TokenSet"),
            SymbolType::Terminal => &mut self.terminal_bits,
            SymbolType::External => &mut self.external_bits,
            SymbolType::End => {
                let result = self.eof;
                self.eof = false;
                return result;
            }
            SymbolType::EndOfNonTerminalExtra => {
                let result = self.end_of_nonterminal_extra;
                self.end_of_nonterminal_extra = false;
                return result;
            }
        };
        if other.index < vec.len() && vec[other.index] {
            vec[other.index] = false;
            Self::trim(vec);
            true
        } else {
            false
        }
    }

    fn trim(vec: &mut Vec<bool>) {
        while vec.last() == Some(&false) {
            vec.pop();
        }
    }

    pub fn is_empty(&self) -> bool {
        !self.eof
            && !self.end_of_nonterminal_extra
            && !self.terminal_bits.iter().any(|b| *b)
            && !self.external_bits.iter().any(|b| *b)
    }

    pub fn len(&self) -> usize {
        self.iter().count()
    }

    pub fn insert_all_terminals(&mut self, other: &Self) -> bool {
        let mut result = false;
        if other.terminal_bits.len() > self.terminal_bits.len() {
            self.terminal_bits.resize(other.terminal_bits.len(), false);
        }
        for (i, b) in other.terminal_bits.iter().enumerate() {
            if *b && !self.terminal_bits[i] {
                self.terminal_bits[i] = true;
                result = true;
            }
        }
        result
    }

    fn insert_all_externals(&mut self, other: &Self) -> bool {
        let mut result = false;
        if other.external_bits.len() > self.external_bits.len() {
            self.external_bits.resize(other.external_bits.len(), false);
        }
        for (i, b) in other.external_bits.iter().enumerate() {
            if *b && !self.external_bits[i] {
                self.external_bits[i] = true;
                result = true;
            }
        }
        result
    }

    pub fn insert_all(&mut self, other: &Self) -> bool {
        let mut result = false;
        if other.eof {
            result |= !self.eof;
            self.eof = true;
        }
        if other.end_of_nonterminal_extra {
            result |= !self.end_of_nonterminal_extra;
            self.end_of_nonterminal_extra = true;
        }
        result |= self.insert_all_terminals(other);
        result |= self.insert_all_externals(other);
        result
    }
}

impl FromIterator<Symbol> for TokenSet {
    fn from_iter<T: IntoIterator<Item = Symbol>>(iter: T) -> Self {
        let mut result = Self::default();
        for symbol in iter {
            result.insert(symbol);
        }
        result
    }
}

#[derive(Clone, Copy, Debug)]
pub struct ParseItem<'a> {
    pub variable_index: u32,
    pub step_index: u32,
    pub production: &'a Production,
    /// If this item is a non-terminal extra, then it must be reduced from a
    /// state that has consumed a hidden child with fields.
    pub has_preceding_inherited_fields: bool,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ParseItemSetEntry<'a> {
    pub item: ParseItem<'a>,
    pub lookaheads: TokenSet,
    pub following_reserved_word_set: ReservedWordSetId,
}

#[derive(Clone, Debug, Default, PartialEq, Eq, Hash)]
pub struct ParseItemSet<'a> {
    pub entries: Vec<ParseItemSetEntry<'a>>,
}

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct ParseItemSetCore<'a> {
    pub entries: Vec<ParseItem<'a>>,
}

pub struct ParseItemDisplay<'a>(
    pub &'a ParseItem<'a>,
    pub &'a SyntaxGrammar,
    pub &'a LexicalGrammar,
);

pub struct TokenSetDisplay<'a>(
    pub &'a TokenSet,
    pub &'a SyntaxGrammar,
    pub &'a LexicalGrammar,
);

pub struct ParseItemSetDisplay<'a>(
    pub &'a ParseItemSet<'a>,
    pub &'a SyntaxGrammar,
    pub &'a LexicalGrammar,
);

impl<'a> ParseItem<'a> {
    pub fn start() -> Self {
        ParseItem {
            variable_index: u32::MAX,
            production: &START_PRODUCTION,
            step_index: 0,
            has_preceding_inherited_fields: false,
        }
    }

    pub fn step(&self) -> Option<&'a ProductionStep> {
        self.production.steps.get(self.step_index as usize)
    }

    pub fn symbol(&self) -> Option<Symbol> {
        self.step().map(|step| step.symbol)
    }

    pub fn associativity(&self) -> Option<Associativity> {
        self.prev_step().and_then(|step| step.associativity)
    }

    pub fn precedence(&self) -> &Precedence {
        self.prev_step()
            .map_or(&Precedence::None, |step| &step.precedence)
    }

    pub fn prev_step(&self) -> Option<&'a ProductionStep> {
        if self.step_index > 0 {
            self.production.steps.get(self.step_index as usize - 1)
        } else {
            None
        }
    }

    pub fn is_done(&self) -> bool {
        self.step_index as usize == self.production.steps.len()
    }

    pub fn is_augmented(&self) -> bool {
        self.variable_index == u32::MAX
    }

    pub fn successor(&self) -> ParseItem<'a> {
        ParseItem {
            variable_index: self.variable_index,
            production: self.production,
            step_index: self.step_index + 1,
            has_preceding_inherited_fields: self.has_preceding_inherited_fields,
        }
    }

    pub fn substitute_production(&self, production: &'a Production) -> ParseItem<'a> {
        let mut result = *self;
        result.production = production;
        result
    }
}

impl<'a> ParseItemSet<'a> {
    pub fn start() -> Self {
        let mut result = Self::default();
        result.insert(ParseItem::start(), &TokenSet::from_iter([Symbol::end()]), 0);
        result
    }

    pub fn insert(
        &mut self,
        item: ParseItem<'a>,
        lookaheads: &TokenSet,
        following_reserved_word_set: ReservedWordSetId,
    ) -> &mut ParseItemSetEntry<'a> {
        match self.entries.binary_search_by(|e| e.item.cmp(&item)) {
            Err(i) => {
                self.entries.insert(
                    i,
                    ParseItemSetEntry {
                        item,
                        lookaheads: lookaheads.clone(),
                        following_reserved_word_set,
                    },
                );
                &mut self.entries[i]
            }
            Ok(i) => {
                self.entries[i].lookaheads.insert_all(lookaheads);
                if following_reserved_word_set != 0 {
                    self.entries[i].following_reserved_word_set = following_reserved_word_set;
                }
                &mut self.entries[i]
            }
        }
    }

    pub fn core(&self) -> ParseItemSetCore<'a> {
        ParseItemSetCore {
            entries: self.entries.iter().map(|e| e.item).collect(),
        }
    }
}

impl fmt::Display for ParseItemDisplay<'_> {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        if self.0.is_augmented() {
            write!(f, "START →")?;
        } else {
            write!(
                f,
                "{} →",
                &self.1.variables[self.0.variable_index as usize].name
            )?;
        }

        for (i, step) in self.0.production.steps.iter().enumerate() {
            if i == self.0.step_index as usize {
                write!(f, " •")?;
                if let Some(associativity) = step.associativity {
                    if step.precedence.is_none() {
                        write!(f, " ({associativity:?})")?;
                    } else {
                        write!(f, " ({} {associativity:?})", step.precedence)?;
                    }
                } else if !step.precedence.is_none() {
                    write!(f, " ({})", step.precedence)?;
                }
            }

            write!(f, " ")?;
            if step.symbol.is_terminal() {
                if let Some(variable) = self.2.variables.get(step.symbol.index) {
                    write!(f, "{}", &variable.name)?;
                } else {
                    write!(f, "terminal-{}", step.symbol.index)?;
                }
            } else if step.symbol.is_external() {
                write!(f, "{}", &self.1.external_tokens[step.symbol.index].name)?;
            } else {
                write!(f, "{}", &self.1.variables[step.symbol.index].name)?;
            }

            if let Some(alias) = &step.alias {
                write!(f, "@{}", alias.value)?;
            }
        }

        if self.0.is_done() {
            write!(f, " •")?;
            if let Some(step) = self.0.production.steps.last() {
                if let Some(associativity) = step.associativity {
                    if step.precedence.is_none() {
                        write!(f, " ({associativity:?})")?;
                    } else {
                        write!(f, " ({} {associativity:?})", step.precedence)?;
                    }
                } else if !step.precedence.is_none() {
                    write!(f, " ({})", step.precedence)?;
                }
            }
        }

        Ok(())
    }
}

impl fmt::Display for TokenSetDisplay<'_> {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "[")?;
        for (i, symbol) in self.0.iter().enumerate() {
            if i > 0 {
                write!(f, ", ")?;
            }
            if symbol.is_terminal() {
                if let Some(variable) = self.2.variables.get(symbol.index) {
                    write!(f, "{}", &variable.name)?;
                } else {
                    write!(f, "{}-{}", "terminal", symbol.index)?;
                }
            } else if symbol.is_external() {
                write!(f, "{}", &self.1.external_tokens[symbol.index].name)?;
            } else {
                write!(f, "{}", &self.1.variables[symbol.index].name)?;
            }
        }
        write!(f, "]")?;
        Ok(())
    }
}

impl fmt::Display for ParseItemSetDisplay<'_> {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        for entry in &self.0.entries {
            writeln!(
                f,
                "{}\t{}",
                ParseItemDisplay(&entry.item, self.1, self.2),
                TokenSetDisplay(&entry.lookaheads, self.1, self.2)
            )?;
        }
        Ok(())
    }
}

impl Hash for ParseItem<'_> {
    fn hash<H: Hasher>(&self, hasher: &mut H) {
        hasher.write_u32(self.variable_index);
        hasher.write_u32(self.step_index);
        hasher.write_i32(self.production.dynamic_precedence);
        hasher.write_usize(self.production.steps.len());
        hasher.write_i32(self.precedence().hash_code());
        self.associativity().hash(hasher);
        self.has_preceding_inherited_fields.hash(hasher);

        // Note: `alias` and `field_name` are not hashed because they do not affect
        // the parse behavior. Any items with the same symbols & precedences
        // are considered equivalent.
        for step in &self.production.steps[0..self.step_index as usize] {
            step.symbol.hash(hasher);
            if self.has_preceding_inherited_fields {
                step.alias.hash(hasher);
            }
        }
        for step in &self.production.steps[self.step_index as usize..] {
            step.symbol.hash(hasher);
            step.alias.hash(hasher);
            step.field_name.hash(hasher);
        }
    }
}

impl PartialEq for ParseItem<'_> {
    fn eq(&self, other: &Self) -> bool {
        self.cmp(other) == Ordering::Equal
    }
}

impl Eq for ParseItem<'_> {}

impl PartialOrd for ParseItem<'_> {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for ParseItem<'_> {
    fn cmp(&self, other: &Self) -> Ordering {
        let o = self.step_index.cmp(&other.step_index);
        if o != Ordering::Equal {
            return o;
        }
        let o = self.variable_index.cmp(&other.variable_index);
        if o != Ordering::Equal {
            return o;
        }
        let o = self
            .production
            .dynamic_precedence
            .cmp(&other.production.dynamic_precedence);
        if o != Ordering::Equal {
            return o;
        }
        let o = self
            .production
            .steps
            .len()
            .cmp(&other.production.steps.len());
        if o != Ordering::Equal {
            return o;
        }
        let o = self.precedence().cmp(other.precedence());
        if o != Ordering::Equal {
            return o;
        }
        let o = self.associativity().cmp(&other.associativity());
        if o != Ordering::Equal {
            return o;
        }
        let o = self
            .has_preceding_inherited_fields
            .cmp(&other.has_preceding_inherited_fields);
        if o != Ordering::Equal {
            return o;
        }

        for (i, step) in self.production.steps.iter().enumerate() {
            let other_step = &other.production.steps[i];

            let o = step.symbol.cmp(&other_step.symbol);
            if o != Ordering::Equal {
                return o;
            }

            // Aliases and field names only matter for the steps *after* the current
            // position, since the steps before it have already been consumed, and
            // for consumed steps when fields are inherited.
            if i >= self.step_index as usize || self.has_preceding_inherited_fields {
                let o = step.alias.cmp(&other_step.alias);
                if o != Ordering::Equal {
                    return o;
                }
            }
            if i >= self.step_index as usize {
                let o = step.field_name.cmp(&other_step.field_name);
                if o != Ordering::Equal {
                    return o;
                }
            }
        }

        Ordering::Equal
    }
}

impl Hash for ParseItemSetEntry<'_> {
    fn hash<H: Hasher>(&self, hasher: &mut H) {
        self.item.hash(hasher);
        self.lookaheads.hash(hasher);
        self.following_reserved_word_set.hash(hasher);
    }
}

impl Precedence {
    fn hash_code(&self) -> i32 {
        match self {
            Precedence::None => 0,
            Precedence::Integer(i) => *i,
            Precedence::Name(n) => {
                let mut h: i32 = 7;
                for b in n.bytes() {
                    h = h.wrapping_mul(31).wrapping_add(b as i32);
                }
                h
            }
        }
    }
}
