                self.terminal_entries[&symbol].actions[action_index]
            {
                self.terminal_entries.get_mut(&symbol).unwrap().actions[action_index] =
                    ParseAction::Shift {
                        state: new_state,
                        is_repetition,
                    };
            }
        }
    }
}

impl ParseAction {
    pub fn precedence(&self) -> &Precedence {
        if let Self::Reduce { precedence, .. } = self {
            precedence
        } else {
            &Precedence::None
        }
    }
}
