use super::coincident_tokens::CoincidentTokenIndex;
use super::item::TokenSet;
use super::token_conflicts::TokenConflictMap;
use crate::generate::grammars::{LexicalGrammar, SyntaxGrammar};
use crate::generate::nfa::{NfaCursor, NfaTransition};
use crate::generate::parse_table::{AdvanceAction, LexState, LexTable, ParseStateId, ParseTable};
use crate::generate::rules::Symbol;
use std::collections::hash_map::Entry;
use std::collections::{HashMap, VecDeque};
use std::mem;

pub fn build_lex_table(
    parse_table: &mut ParseTable,
    syntax_grammar: &SyntaxGrammar,
    lexical_grammar: &LexicalGrammar,
    keywords: &TokenSet,
    coincident_token_index: &CoincidentTokenIndex,
    token_conflict_map: &TokenConflictMap,
) -> (LexTable, LexTable) {
    let keyword_lex_table = if syntax_grammar.word_token.is_some() {
        let mut builder = LexTableBuilder::new(lexical_grammar);
        builder.add_state_for_tokens(keywords);
        builder.table
    } else {
        LexTable::default()
    };

    let mut parse_state_ids_by_token_set: Vec<(TokenSet, Vec<ParseStateId>)> = Vec::new();
    for (i, state) in parse_table.states.iter().enumerate() {
        let tokens = state
            .terminal_entries
            .keys()
            .filter_map(|token| {
                if token.is_terminal() {
                    if keywords.contains(token) {
                        syntax_grammar.word_token
                    } else {
                        Some(*token)
                    }
                } else if token.is_eof() {
                    Some(*token)
                } else {
                    None
                }
            })
            .collect();

        let mut did_merge = false;
        for entry in &mut parse_state_ids_by_token_set {
            if merge_token_set(
                &mut entry.0,
                &tokens,
                lexical_grammar,
                token_conflict_map,
                coincident_token_index,
            ) {
                entry.1.push(i);
                did_merge = true;
                break;
            }
        }

        if !did_merge {
            parse_state_ids_by_token_set.push((tokens, vec![i]));
        }
    }

    let mut builder = LexTableBuilder::new(lexical_grammar);
    for (tokens, parse_state_ids) in parse_state_ids_by_token_set {
        let lex_state_id = builder.add_state_for_tokens(&tokens);
        for id in parse_state_ids {
            parse_table.states[id].lex_state_id = lex_state_id;
        }
    }

    let mut table = builder.table;
    minimize_lex_table(&mut table, parse_table);
    sort_states(&mut table, parse_table);
    (table, keyword_lex_table)
}

fn merge_token_set(
    tokens: &mut TokenSet,
    other: &TokenSet,
    lexical_grammar: &LexicalGrammar,
    token_conflict_map: &TokenConflictMap,
    coincident_token_index: &CoincidentTokenIndex,
) -> bool {
    for i in 0..lexical_grammar.variables.len() {
        let symbol = Symbol::terminal(i);
        let set_without_terminal = match (tokens.contains(&symbol), other.contains(&symbol)) {
            (true, false) => other,
            (false, true) => tokens,
            _ => continue,
        };

        for existing_token in set_without_terminal.iter() {
            if !existing_token.is_terminal() {
                continue;
            }
            if coincident_token_index.contains(symbol, existing_token) {
                continue;
            }
            if token_conflict_map.does_conflict(symbol.index, existing_token.index)
                || token_conflict_map.does_match_same_string(symbol.index, existing_token.index)
            {
                return false;
            }
        }
    }

    tokens.insert_all(other);
    true
}

struct QueueEntry {
    state_id: usize,
    nfa_states: Vec<u32>,
    eof_valid: bool,
}

struct LexTableBuilder<'a> {
    lexical_grammar: &'a LexicalGrammar,
    cursor: NfaCursor<'a>,
    table: LexTable,
    state_queue: VecDeque<QueueEntry>,
    state_ids_by_nfa_state_set: HashMap<(Vec<u32>, bool), usize>,
}

impl<'a> LexTableBuilder<'a> {
    fn new(lexical_grammar: &'a LexicalGrammar) -> Self {
        Self {
            lexical_grammar,
            cursor: NfaCursor::new(&lexical_grammar.nfa, Vec::new()),
            table: LexTable::default(),
            state_queue: VecDeque::new(),
            state_ids_by_nfa_state_set: HashMap::new(),
        }
    }

    fn add_state_for_tokens(&mut self, tokens: &TokenSet) -> usize {
        let mut eof_valid = false;
        let nfa_states = tokens
            .iter()
            .filter_map(|token| {
                if token.is_terminal() {
                    Some(self.lexical_grammar.variables[token.index].start_state)
                } else {
                    if token.is_eof() {
                        eof_valid = true;
                    }
                    None
                }
            })
            .collect();
        let (state_id, _) = self.add_state(nfa_states, eof_valid);

        while let Some(QueueEntry {
            state_id,
            nfa_states,
            eof_valid,
        }) = self.state_queue.pop_front()
        {
            self.populate_state(state_id, nfa_states, eof_valid);
        }
        state_id
    }

    fn add_state(&mut self, nfa_states: Vec<u32>, eof_valid: bool) -> (usize, bool) {
        self.cursor.reset(nfa_states);
        match self
            .state_ids_by_nfa_state_set
            .entry((self.cursor.state_ids.clone(), eof_valid))
        {
            Entry::Occupied(o) => (*o.get(), false),
            Entry::Vacant(v) => {
                let state_id = self.table.states.len();
                self.table.states.push(LexState::default());
                self.state_queue.push_back(QueueEntry {
                    state_id,
                    nfa_states: self.cursor.state_ids.clone(),
                    eof_valid,
                });
                v.insert(state_id);
                (state_id, true)
            }
        }
    }

    fn populate_state(&mut self, state_id: usize, nfa_states: Vec<u32>, eof_valid: bool) {
        self.cursor.force_reset(nfa_states);

        // The EOF state is represented as an empty list of NFA states.
        let mut completion = None;
        for (id, prec) in self.cursor.completions() {
            if let Some((prev_id, prev_precedence)) = completion {
                if TokenConflictMap::prefer_token(
                    self.lexical_grammar,
                    (prev_precedence, prev_id),
                    (prec, id),
                ) {
                    continue;
                }
            }
            completion = Some((id, prec));
        }

        let transitions = self.cursor.transitions();
        let has_sep = transitions.iter().any(|t| t.is_separator);

        // If EOF is a valid lookahead token, add a transition predicated on the null
        // character that leads to the empty set of NFA states.
        if eof_valid {
            let (next_state_id, _) = self.add_state(Vec::new(), false);
            self.table.states[state_id].eof_action = Some(AdvanceAction {
                state: next_state_id,
                in_main_token: true,
            });
        }

        for transition in transitions {
            if let Some((completed_id, completed_precedence)) = completion {
                if !TokenConflictMap::prefer_transition(
                    self.lexical_grammar,
                    &transition,
                    completed_id,
                    completed_precedence,
                    has_sep,
                ) {
                    continue;
                }
            }
            let NfaTransition {
                characters,
                states,
                is_separator,
                ..
            } = transition;
            let (next_state_id, _) = self.add_state(states, eof_valid && is_separator);
            self.table.states[state_id].advance_actions.push((
                characters,
                AdvanceAction {
                    state: next_state_id,
                    in_main_token: !is_separator,
                },
            ));
        }

        if self.cursor.state_ids.is_empty() {
            self.table.states[state_id].accept_action = Some(Symbol::end());
        } else if let Some((completion_id, _)) = completion {
            self.table.states[state_id].accept_action = Some(Symbol::terminal(completion_id));
        }
    }
}

fn minimize_lex_table(table: &mut LexTable, parse_table: &mut ParseTable) {
    // Initially group the states by their accept action and their
    // valid lookahead characters.
    let mut state_ids_by_signature = HashMap::new();
    let mut group_ids_by_state_id = Vec::with_capacity(table.states.len());
    let mut state_ids_by_group_id: Vec<Vec<usize>> = Vec::new();
    for (i, state) in table.states.iter().enumerate() {
        let signature = (
            state.accept_action,
            state.eof_action.is_some(),
            state
                .advance_actions
                .iter()
                .map(|(chars, action)| (chars.clone(), action.in_main_token))
                .collect::<Vec<_>>(),
        );
        let group_id = *state_ids_by_signature.entry(signature).or_insert_with(|| {
            state_ids_by_group_id.push(Vec::new());
            state_ids_by_group_id.len() - 1
        });
        state_ids_by_group_id[group_id].push(i);
        group_ids_by_state_id.push(group_id);
    }

    // Iteratively refine the groups until no changes
    let mut done = false;
    while !done {
        done = true;
        for group_id in 0..state_ids_by_group_id.len() {
            let state_ids = state_ids_by_group_id[group_id].clone();
            let first_state_id = state_ids[0];
            let mut new_group_ids = Vec::new();
            for state_id in &state_ids[1..] {
                if lex_states_differ(
                    &table.states[first_state_id],
                    &table.states[*state_id],
                    &group_ids_by_state_id,
                ) {
                    new_group_ids.push(*state_id);
                }
            }
            if !new_group_ids.is_empty() {
                done = false;
                let new_group_id = state_ids_by_group_id.len();
                for id in &new_group_ids {
                    group_ids_by_state_id[*id] = new_group_id;
                }
                state_ids_by_group_id[group_id].retain(|id| !new_group_ids.contains(id));
                state_ids_by_group_id.push(new_group_ids);
            }
        }
    }

    let mut new_states = Vec::with_capacity(state_ids_by_group_id.len());
    for state_ids in &state_ids_by_group_id {
        let mut new_state = LexState::default();
        mem::swap(&mut new_state, &mut table.states[state_ids[0]]);
        for (_, advance_action) in &mut new_state.advance_actions {
            advance_action.state = group_ids_by_state_id[advance_action.state];
        }
        if let Some(eof_action) = &mut new_state.eof_action {
            eof_action.state = group_ids_by_state_id[eof_action.state];
        }
        new_states.push(new_state);
    }

    for state in &mut parse_table.states {
        state.lex_state_id = group_ids_by_state_id[state.lex_state_id];
    }

    table.states = new_states;
}

fn lex_states_differ(
    state1: &LexState,
    state2: &LexState,
    group_ids_by_state_id: &[usize],
) -> bool {
    if state1.accept_action != state2.accept_action {
        return true;
    }
    match (&state1.eof_action, &state2.eof_action) {
        (Some(a), Some(b)) => {
            if group_ids_by_state_id[a.state] != group_ids_by_state_id[b.state] {
                return true;
            }
        }
        (None, None) => {}
        _ => return true,
    }
    if state1.advance_actions.len() != state2.advance_actions.len() {
        return true;
    }
    state1
        .advance_actions
        .iter()
        .zip(state2.advance_actions.iter())
        .any(|((chars1, action1), (chars2, action2))| {
            chars1 != chars2
                || action1.in_main_token != action2.in_main_token
                || group_ids_by_state_id[action1.state] != group_ids_by_state_id[action2.state]
        })
}

fn sort_states(table: &mut LexTable, parse_table: &mut ParseTable) {
    // Get a mapping of old state index -> new_state_index
    let mut old_ids_by_new_id = (0..table.states.len()).collect::<Vec<_>>();
    old_ids_by_new_id.sort_by_key(|id| table.states[*id].accept_action);

    // Get the inverse mapping
    let mut new_ids_by_old_id = vec![0; old_ids_by_new_id.len()];
    for (id, old_id) in old_ids_by_new_id.iter().enumerate() {
        new_ids_by_old_id[*old_id] = id;
    }

    // Reorder the parse states and update their references to other states
    table.states = old_ids_by_new_id
        .iter()
        .map(|old_id| {
            let mut state = LexState::default();
            mem::swap(&mut state, &mut table.states[*old_id]);
            for (_, advance_action) in &mut state.advance_actions {
                advance_action.state = new_ids_by_old_id[advance_action.state];
            }
            if let Some(eof_action) = &mut state.eof_action {
                eof_action.state = new_ids_by_old_id[eof_action.state];
            }
            state
        })
        .collect();

    // Update the parse table's lex state references
    for state in &mut parse_table.states {
        state.lex_state_id = new_ids_by_old_id[state.lex_state_id];
    }
}
