use super::item::TokenSet;
use super::token_conflicts::TokenConflictMap;
use crate::generate::grammars::{LexicalGrammar, SyntaxGrammar};
use crate::generate::parse_table::{
    GotoAction, ParseAction, ParseState, ParseStateId, ParseTable, ParseTableEntry,
};
use crate::generate::rules::{AliasMap, Symbol, VariableType};
use std::collections::{HashMap, HashSet};
use std::mem;

pub fn minimize_parse_table(
    parse_table: &mut ParseTable,
    syntax_grammar: &SyntaxGrammar,
    lexical_grammar: &LexicalGrammar,
    simple_aliases: &AliasMap,
    token_conflict_map: &TokenConflictMap,
    keywords: &TokenSet,
    merge_states: bool,
) {
    let mut minimizer = Minimizer {
        parse_table,
        syntax_grammar,
        lexical_grammar,
        token_conflict_map,
        keywords,
        simple_aliases,
    };
    minimizer.remove_unit_reductions();
    minimizer.remove_unused_states();
    if merge_states {
        minimizer.merge_compatible_states();
        minimizer.remove_unused_states();
    }
    minimizer.reorder_states_by_descending_size();
}

struct Minimizer<'a> {
    parse_table: &'a mut ParseTable,
    syntax_grammar: &'a SyntaxGrammar,
    lexical_grammar: &'a LexicalGrammar,
    token_conflict_map: &'a TokenConflictMap<'a>,
    keywords: &'a TokenSet,
    simple_aliases: &'a AliasMap,
}

impl Minimizer<'_> {
    fn remove_unit_reductions(&mut self) {
        let mut aliased_symbols = HashSet::new();
        for variable in &self.syntax_grammar.variables {
            for production in &variable.productions {
                for step in &production.steps {
                    if step.alias.is_some() {
                        aliased_symbols.insert(step.symbol);
                    }
                }
            }
        }

        let mut unit_reduction_symbols_by_state = HashMap::new();
        for (i, state) in self.parse_table.states.iter().enumerate() {
            let mut only_unit_reductions = true;
            let mut unit_reduction_symbol = None;
            for (_, entry) in &state.terminal_entries {
                for action in &entry.actions {
                    match action {
                        ParseAction::ShiftExtra => continue,
                        ParseAction::Reduce {
                            child_count: 1,
                            production_id: 0,
                            symbol,
                            ..
                        } => {
                            if !self.simple_aliases.contains_key(symbol)
                                && !self.syntax_grammar.supertype_symbols.contains(symbol)
                                && !aliased_symbols.contains(symbol)
                                && self.syntax_grammar.variables[symbol.index].kind
                                    != VariableType::Named
                                && (unit_reduction_symbol.is_none()
                                    || unit_reduction_symbol == Some(symbol))
                            {
                                unit_reduction_symbol = Some(symbol);
                                continue;
                            }
                        }
                        _ => {}
                    }
                    only_unit_reductions = false;
                    break;
                }

                if !only_unit_reductions {
                    break;
                }
            }

            if let (true, Some(symbol)) = (only_unit_reductions, unit_reduction_symbol) {
                unit_reduction_symbols_by_state.insert(i, *symbol);
            }
        }

        for state in &mut self.parse_table.states {
            let mut done = false;
            while !done {
                done = true;
                state.update_referenced_states(|other_state_id, state| {
                    if let Some(symbol) = unit_reduction_symbols_by_state.get(&other_state_id) {
                        done = false;
                        match state.nonterminal_entries.get(symbol) {
                            Some(GotoAction::Goto(state_id)) => *state_id,
                            _ => other_state_id,
                        }
                    } else {
                        other_state_id
                    }
                });
            }
        }
    }

    fn merge_compatible_states(&mut self) {
        // Initially group the states by their item set cores.
        let mut group_ids_by_state_id = Vec::with_capacity(self.parse_table.states.len());
        let mut state_ids_by_group_id: Vec<Vec<ParseStateId>> = Vec::new();
        let mut group_ids_by_core_id: HashMap<usize, usize> = HashMap::new();
        for (i, state) in self.parse_table.states.iter().enumerate() {
            let group_id = *group_ids_by_core_id.entry(state.core_id).or_insert_with(|| {
                state_ids_by_group_id.push(Vec::new());
                state_ids_by_group_id.len() - 1
            });
            state_ids_by_group_id[group_id].push(i);
            group_ids_by_state_id.push(group_id);
        }

        let error_group_index = group_ids_by_state_id[0];
        let start_group_index = group_ids_by_state_id[1];
        let _ = (error_group_index, start_group_index);

        let mut done = false;
        while !done {
            done = true;
            for group_id in 0..state_ids_by_group_id.len() {
                let state_ids = state_ids_by_group_id[group_id].clone();
                if state_ids.len() <= 1 {
                    continue;
                }
                let mut split_state_ids = Vec::new();
                let left_id = state_ids[0];
                for right_id in &state_ids[1..] {
                    let left_state = &self.parse_table.states[left_id];
                    let right_state = &self.parse_table.states[*right_id];
                    if self.states_conflict(left_state, right_state, &group_ids_by_state_id)
                        || self.state_successors_differ(left_state, right_state, &group_ids_by_state_id)
                    {
                        split_state_ids.push(*right_id);
                    }
                }

                if !split_state_ids.is_empty() {
                    done = false;
                    let new_group_id = state_ids_by_group_id.len();
                    for id in &split_state_ids {
                        group_ids_by_state_id[*id] = new_group_id;
                    }
                    state_ids_by_group_id[group_id].retain(|id| !split_state_ids.contains(id));
                    state_ids_by_group_id.push(split_state_ids);
                }
            }
        }

        // Create a new parse table with one state per group.
        let mut new_states = Vec::with_capacity(state_ids_by_group_id.len());
        for state_ids in &state_ids_by_group_id {
            // Initialize the new state based on the first old state in the group.
            let mut parse_state = ParseState::default();
            mem::swap(&mut parse_state, &mut self.parse_table.states[state_ids[0]]);

            // Extend the new state with all of the actions from the other old states
            // in the group.
            for state_id in &state_ids[1..] {
                let mut other_parse_state = ParseState::default();
                mem::swap(&mut other_parse_state, &mut self.parse_table.states[*state_id]);

                parse_state
                    .terminal_entries
                    .extend(other_parse_state.terminal_entries);
                parse_state
                    .nonterminal_entries
                    .extend(other_parse_state.nonterminal_entries);
                parse_state
                    .reserved_words
                    .insert_all(&other_parse_state.reserved_words);
            }

            // Update the new state's outgoing references using the new grouping.
            parse_state.update_referenced_states(|state_id, _| group_ids_by_state_id[state_id]);
            new_states.push(parse_state);
        }

        self.parse_table.states = new_states;
    }

    fn states_conflict(
        &self,
        state1: &ParseState,
        state2: &ParseState,
        group_ids_by_state_id: &[ParseStateId],
    ) -> bool {
        for (token, entry1) in &state1.terminal_entries {
            if let Some(entry2) = state2.terminal_entries.get(token) {
                if Self::entries_conflict(entry1, entry2, group_ids_by_state_id) {
                    return true;
                }
            } else if self.token_conflicts(state2.terminal_entries.keys(), *token) {
                return true;
            }
        }

        for (token, _) in &state2.terminal_entries {
            if !state1.terminal_entries.contains_key(token)
                && self.token_conflicts(state1.terminal_entries.keys(), *token)
            {
                return true;
            }
        }

        false
    }

    fn state_successors_differ(
        &self,
        state1: &ParseState,
        state2: &ParseState,
        group_ids_by_state_id: &[ParseStateId],
    ) -> bool {
        for (symbol, s1) in &state1.nonterminal_entries {
            if let Some(s2) = state2.nonterminal_entries.get(symbol) {
                match (s1, s2) {
                    (GotoAction::Goto(s1), GotoAction::Goto(s2)) => {
                        if group_ids_by_state_id[*s1] != group_ids_by_state_id[*s2] {
                            return true;
                        }
                    }
                    (GotoAction::ShiftExtra, GotoAction::ShiftExtra) => {}
                    _ => return true,
                }
            }
        }
        false
    }

    fn entries_conflict(
        entry1: &ParseTableEntry,
        entry2: &ParseTableEntry,
        group_ids_by_state_id: &[ParseStateId],
    ) -> bool {
        // To be compatible, entries need to have the same actions, except that
        // shift actions need only have the same destination *group*.
        if entry1.actions.len() != entry2.actions.len() {
            return true;
        }
        for (i, action1) in entry1.actions.iter().enumerate() {
            let action2 = &entry2.actions[i];
            match (action1, action2) {
                (
                    ParseAction::Shift {
                        state: s1,
                        is_repetition: r1,
                    },
                    ParseAction::Shift {
                        state: s2,
                        is_repetition: r2,
                    },
                ) => {
                    if group_ids_by_state_id[*s1] != group_ids_by_state_id[*s2] || r1 != r2 {
                        return true;
                    }
                }
                _ => {
                    if action1 != action2 {
                        return true;
                    }
                }
            }
        }
        false
    }

    fn token_conflicts<'b>(
        &self,
        existing_tokens: impl Iterator<Item = &'b Symbol>,
        new_token: Symbol,
    ) -> bool {
        if new_token == Symbol::end_of_nonterminal_extra() {
            return false;
        }

        // Do not add external tokens; they could conflict lexically with any of the state's
        // existing lookahead tokens.
        if new_token.is_external() {
            return true;
        }

        // Do not add tokens which are both internal and external. Their validity could
        // influence the behavior of the external scanner.
        if self
            .syntax_grammar
            .external_tokens
            .iter()
            .any(|token| token.corresponding_internal_token == Some(new_token))
        {
            return true;
        }

        if !new_token.is_terminal() {
            return false;
        }

        // Do not add a token if it conflicts with an existing token.
        for token in existing_tokens {
            if !token.is_terminal() {
                continue;
            }
            if *token == new_token {
                continue;
            }
            if self.is_keyword_conflict(*token, new_token) {
                return true;
            }
            if self
                .token_conflict_map
                .does_match_same_string(new_token.index, token.index)
                || self
                    .token_conflict_map
                    .does_conflict(new_token.index, token.index)
            {
                return true;
            }
        }

        false
    }

    fn is_keyword_conflict(&self, existing: Symbol, new_token: Symbol) -> bool {
        // When a keyword is substituted by the word token during lexing, the existing
        // state's tokens must have the same conflict status with the word token.
        if let Some(word_token) = self.syntax_grammar.word_token {
            if self.keywords.contains(&new_token) && !self.keywords.contains(&existing) {
                if existing != word_token
                    && !self.token_conflict_map.has_same_conflict_status(
                        new_token.index,
                        word_token.index,
                        existing.index,
                    )
                {
                    return true;
                }
            }
        }
        let _ = self.lexical_grammar;
        false
    }

    fn remove_unused_states(&mut self) {
        let mut state_usage_map = vec![false; self.parse_table.states.len()];

        state_usage_map[0] = true;
        state_usage_map[1] = true;

        for state in &self.parse_table.states {
            for referenced_state in state.referenced_states() {
                state_usage_map[referenced_state] = true;
            }
        }
        let mut removed_predecessor_count = 0;
        let mut state_replacement_map = vec![0; self.parse_table.states.len()];
        for state_id in 0..self.parse_table.states.len() {
            state_replacement_map[state_id] = state_id - removed_predecessor_count;
            if !state_usage_map[state_id] {
                removed_predecessor_count += 1;
            }
        }
        let mut state_id = 0;
        let mut original_state_id = 0;
        while state_id < self.parse_table.states.len() {
            if state_usage_map[original_state_id] {
                self.parse_table.states[state_id].update_referenced_states(|other_state_id, _| {
                    state_replacement_map[other_state_id]
                });
                state_id += 1;
            } else {
                self.parse_table.states.remove(state_id);
            }
            original_state_id += 1;
        }
    }

    fn reorder_states_by_descending_size(&mut self) {
        // Get a mapping of old state index -> new_state_index
        let mut old_ids_by_new_id = (0..self.parse_table.states.len()).collect::<Vec<_>>();
        old_ids_by_new_id.sort_unstable_by_key(|i| {
            // Don't changes states 0 (the error state) or 1 (the start state).
            if *i <= 1 {
                return *i as i64 - 1_000_000;
            }

            // Reorder all the other states by descending symbol count.
            let state = &self.parse_table.states[*i];
            -((state.terminal_entries.len() + state.nonterminal_entries.len()) as i64)
        });

        // Get the inverse mapping
        let mut new_ids_by_old_id = vec![0; old_ids_by_new_id.len()];
        for (id, old_id) in old_ids_by_new_id.iter().enumerate() {
            new_ids_by_old_id[*old_id] = id;
        }

        // Reorder the parse states and update their references to other states
        self.parse_table.states = old_ids_by_new_id
            .iter()
            .map(|old_id| {
                let mut state = ParseState::default();
                mem::swap(&mut state, &mut self.parse_table.states[*old_id]);
                state.update_referenced_states(|other_id, _| new_ids_by_old_id[other_id]);
                state
            })
            .collect();
    }
}
