use super::rules::{Alias, AliasMap, Symbol, SymbolType, VariableType};
use std::cmp;
use std::collections::{BTreeMap, HashMap, HashSet};
use std::fmt::Write;
use std::mem::swap;

const SMALL_STATE_THRESHOLD: usize = 64;
const ABI_VERSION_MIN: usize = 14;
const ABI_VERSION_MAX: usize = 15;
const ABI_VERSION_WITH_RESERVED_WORDS: usize = 15;
const LARGE_CHARACTER_RANGE_COUNT: usize = 8;

