    fn add_field_sequences(&mut self) {
        let mut flat_field_maps = vec![];
        let mut next_flat_field_map_index = 0;
        self.get_field_map_id(
            Vec::new(),
            &mut flat_field_maps,
            &mut next_flat_field_map_index,
        );

        let mut field_map_ids = Vec::new();
        for production_info in &self.parse_table.production_infos {
            if production_info.field_map.is_empty() {
                field_map_ids.push((0, 0));
            } else {
                let mut flat_field_map = Vec::new();
                for (field_name, locations) in &production_info.field_map {
                    for location in locations {
                        flat_field_map.push((field_name.clone(), *location));
                    }
                }
                field_map_ids.push((
                    self.get_field_map_id(
                        flat_field_map.clone(),
                        &mut flat_field_maps,
                        &mut next_flat_field_map_index,
                    ),
                    flat_field_map.len(),
                ));
            }
        }

        add_line!(
            self,
            "static const TSMapSlice ts_field_map_slices[PRODUCTION_ID_COUNT] = {{"
        );
        indent!(self);
        for (production_id, (row_id, length)) in field_map_ids.into_iter().enumerate() {
            if length > 0 {
                add_line!(
                    self,
                    "[{production_id}] = {{.index = {row_id}, .length = {length}}},"
                );
            }
        }
        dedent!(self);
        add_line!(self, "}};");
        add_line!(self, "");

        add_line!(
            self,
            "static const TSFieldMapEntry ts_field_map_entries[] = {{"
        );
        indent!(self);
        for (row_index, field_pairs) in flat_field_maps.into_iter().skip(1) {
            add_line!(self, "[{row_index}] =");
            indent!(self);
            for (field_name, location) in field_pairs {
                add_whitespace!(self);
                add!(self, "{{{}, {}", self.field_id(&field_name), location.index);
                if location.inherited {
                    add!(self, ", .inherited = true");
                }
                add!(self, "}},\n");
            }
            dedent!(self);
        }

        dedent!(self);
        add_line!(self, "}};");
        add_line!(self, "");
    }

    fn add_lex_function(&mut self, name: &str, lex_table: LexTable) {
        add_line!(
            self,
            "static bool {name}(TSLexer *lexer, TSStateId state) {{"
        );
        indent!(self);
        add_line!(self, "START_LEXER();");
        add_line!(self, "eof = lexer->eof(lexer);");
        add_line!(self, "switch (state) {{");

        indent!(self);
        for (i, state) in lex_table.states.into_iter().enumerate() {
            add_line!(self, "case {i}:");
            indent!(self);
            self.add_lex_state(state);
            dedent!(self);
        }

        add_line!(self, "default:");
        indent!(self);
        add_line!(self, "return false;");
        dedent!(self);

        dedent!(self);
        add_line!(self, "}}");

        dedent!(self);
        add_line!(self, "}}");
        add_line!(self, "");
    }

    fn add_lex_state(&mut self, state: LexState) {
        if let Some(accept_action) = state.accept_action {
            add_line!(self, "ACCEPT_TOKEN({});", self.symbol_ids[&accept_action]);
        }

        if let Some(eof_action) = state.eof_action {
            add_line!(self, "if (eof) ADVANCE({});", eof_action.state);
        }

        let mut chars_copy = CharacterSet::empty();
        let mut large_set = CharacterSet::empty();
        let mut ruled_out_chars = CharacterSet::empty();

        // The transitions in a lex state are sorted with the single-character
        // transitions first. If there are many single-character transitions,
        // then implement them using an array of (lookahead character, state)
        // pairs, instead of individual if statements, in order to reduce compile
        // time.
        let mut leading_simple_transition_count = 0;
        let mut leading_simple_transition_range_count = 0;
        for (chars, action) in &state.advance_actions {
            if action.in_main_token
                && chars.ranges().all(|r| {
                    let start = r.start;
                    let end = r.end - 1;
                    end <= start + 1 && end <= u16::MAX as u32
                })
            {
                leading_simple_transition_count += 1;
                leading_simple_transition_range_count += chars.range_count();
            } else {
                break;
            }
        }

        if leading_simple_transition_range_count >= 8 {
            add_line!(self, "ADVANCE_MAP(");
            indent!(self);
            for (chars, action) in &state.advance_actions[0..leading_simple_transition_count] {
                for range in chars.ranges() {
                    add_whitespace!(self);
                    self.add_character(range.start);
                    add!(self, ", {},\n", action.state);
                    if range.end - 1 > range.start {
                        add_whitespace!(self);
                        self.add_character(range.end - 1);
                        add!(self, ", {},\n", action.state);
                    }
                }
                ruled_out_chars = ruled_out_chars.add(chars);
            }
            dedent!(self);
            add_line!(self, ");");
        } else {
            leading_simple_transition_count = 0;
        }

        for (chars, action) in &state.advance_actions[leading_simple_transition_count..] {
            add_whitespace!(self);

            // The lex state's transitions are sorted in a particular order? Determine how to
            // render this transition's character set, as either an inclusion or an exclusion.
            let (simplified, is_included) = {
                let included = chars.simplify_ignoring(&ruled_out_chars);
                if chars.last_codepoint() == Some(MAX_CHAR) {
                    let excluded = chars
                        .clone()
                        .negate_full()
                        .simplify_ignoring(&ruled_out_chars);
                    (excluded, false)
                } else {
                    (included, true)
                }
            };

            let mut line_break = "\n".to_string();
            for _ in 0..self.indent_level + 2 {
                line_break.push_str("  ");
            }

            // If the character set is large, then render it as a static array of ranges,
            // referenced via the `set_contains` helper.
            if simplified.range_count() > LARGE_CHARACTER_RANGE_COUNT {
                large_set.assign(&simplified);
                chars_copy.assign(&large_set);

                let symbol = state.accept_action;
                let mut index = None;
                for (i, (existing_symbol, existing_set)) in
                    self.large_character_sets.iter().enumerate()
                {
                    if *existing_set == large_set {
                        index = Some(i);
                        let _ = existing_symbol;
                        break;
                    }
                }
                let index = match index {
                    Some(i) => i,
                    None => {
                        let count = self
                            .large_character_sets
                            .iter()
                            .filter(|(s, _)| *s == symbol)
                            .count();
                        let constant_name = if let Some(symbol) = symbol {
                            format!("{}_character_set_{}", self.symbol_ids[&symbol], count + 1)
                        } else {
                            format!("extras_character_set_{}", count + 1)
                        };
                        self.large_character_sets.push((symbol, large_set.clone()));
                        self.large_character_set_info.push(LargeCharacterSetInfo {
                            constant_name,
                            is_used: false,
                        });
                        self.large_character_sets.len() - 1
                    }
                };
                self.large_character_set_info[index].is_used = true;
                let constant_name = self.large_character_set_info[index].constant_name.clone();
                let range_count = large_set.range_count();
                if is_included {
                    add!(
                        self,
                        "if (set_contains({constant_name}, {range_count}, lookahead)) "
                    );
                } else {
                    add!(
                        self,
                        "if (!set_contains({constant_name}, {range_count}, lookahead)) "
                    );
                }
            } else {
                add!(self, "if (");
                self.add_character_range_conditions(&simplified, is_included, &line_break);
                add!(self, ") ");
            }

            if action.in_main_token {
                add!(self, "ADVANCE({});", action.state);
            } else {
                add!(self, "SKIP({});", action.state);
            }
            add!(self, "\n");

            ruled_out_chars = ruled_out_chars.add(chars);
        }

        add_line!(self, "END_STATE();");
    }

    fn add_character_range_conditions(
        &mut self,
        characters: &CharacterSet,
        is_included: bool,
        line_break: &str,
    ) -> bool {
        let mut did_add = false;
        for range in characters.ranges() {
            let start = range.start;
            let end = range.end - 1;
            if did_add {
                add!(self, "{line_break}");
            }

            if is_included {
                if did_add {
                    add!(self, "|| ");
                }
                if start == end {
                    add!(self, "lookahead == ");
                    self.add_character(start);
                } else {
                    add!(self, "(");
                    self.add_character(start);
                    add!(self, " <= lookahead && lookahead <= ");
                    self.add_character(end);
                    add!(self, ")");
                }
            } else {
                if did_add {
                    add!(self, "&& ");
                }
                if start == end {
                    add!(self, "lookahead != ");
                    self.add_character(start);
                } else {
                    add!(self, "(lookahead < ");
                    self.add_character(start);
                    add!(self, " || ");
                    self.add_character(end);
                    add!(self, " < lookahead)");
                }
            }
            did_add = true;
        }
        did_add
    }

    fn add_character_set(&mut self, name: &str, characters: &CharacterSet, _symbol: Option<Symbol>) {
        add_line!(
            self,
            "static TSCharacterRange {name}[] = {{"
        );
        indent!(self);
        let ranges: Vec<_> = characters.ranges().cloned().collect();
        for (ix, range) in ranges.iter().enumerate() {
            if ix % 8 == 0 {
                add_whitespace!(self);
            } else {
                add!(self, " ");
            }
            add!(self, "{{");
            self.add_character(range.start);
            add!(self, ", ");
            self.add_character(range.end - 1);
            add!(self, "}},");
            if ix % 8 == 7 || ix == ranges.len() - 1 {
                add!(self, "\n");
            }
        }
        dedent!(self);
        add_line!(self, "}};");
        add_line!(self, "");
    }

    fn add_lex_modes_list(&mut self) {
        let lex_mode_type = if self.abi_version >= ABI_VERSION_WITH_RESERVED_WORDS {
            "TSLexerMode"
        } else {
            "TSLexMode"
        };
        add_line!(
            self,
            "static const {lex_mode_type} ts_lex_modes[STATE_COUNT] = {{"
        );
        indent!(self);
        for (i, state) in self.parse_table.states.iter().enumerate() {
            if state.is_end_of_non_terminal_extra() {
                add_line!(self, "[{i}] = {{(TSStateId)(-1)}},");
            } else {
                add_whitespace!(self);
                add!(self, "[{i}] = {{.lex_state = {}", state.lex_state_id);
                if state.external_lex_state_id > 0 {
                    add!(
                        self,
                        ", .external_lex_state = {}",
                        state.external_lex_state_id
                    );
                }
                if self.abi_version >= ABI_VERSION_WITH_RESERVED_WORDS {
                    let reserved_word_set_id = self.reserved_word_set_id_for_state(i);
                    if reserved_word_set_id > 0 {
                        add!(self, ", .reserved_word_set_id = {reserved_word_set_id}");
                    }
                }
                add!(self, "}},\n");
            }
        }
        dedent!(self);
        add_line!(self, "}};");
        add_line!(self, "");
    }

    fn reserved_word_set_id_for_state(&self, state_index: usize) -> usize {
        let state = &self.parse_table.states[state_index];
        if state.reserved_words.is_empty() {
            return 0;
        }
        let sets = self.reserved_word_sets();
        sets.iter()
            .position(|s| *s == state.reserved_words)
            .unwrap_or(0)
    }

    fn reserved_word_sets(&self) -> Vec<super::build_tables::TokenSet> {
        let mut result = vec![super::build_tables::TokenSet::new()];
        for state in &self.parse_table.states {
            if !state.reserved_words.is_empty() && !result.contains(&state.reserved_words) {
                result.push(state.reserved_words.clone());
            }
        }
        result
    }

    fn add_reserved_word_sets(&mut self) {
        let sets = self.reserved_word_sets();
        if sets.len() <= 1 {
            return;
        }
        add_line!(
            self,
            "static const TSSymbol ts_reserved_words[{}][MAX_RESERVED_WORD_SET_SIZE] = {{",
            sets.len()
        );
        indent!(self);
        for (i, set) in sets.iter().enumerate() {
            if set.is_empty() {
                continue;
            }
            add_line!(self, "[{i}] = {{");
            indent!(self);
            for symbol in set.iter() {
                add_line!(self, "{},", self.symbol_ids[&symbol]);
            }
            dedent!(self);
            add_line!(self, "}},");
        }
        dedent!(self);
        add_line!(self, "}};");
        add_line!(self, "");
    }

