                        '\u{FEFF}' => "BOM",
                        '\u{0080}'..='\u{FFFF}' => {
                            result.push_str(&format!("u{:04x}", c as u32));
                            break 'special_chars;
                        }
                        '\u{10000}'..='\u{10FFFF}' => {
                            result.push_str(&format!("U{:08x}", c as u32));
                            break 'special_chars;
                        }
                        '0'..='9' | 'a'..='z' | 'A'..='Z' | '_' => unreachable!(),
                        ' ' => break 'special_chars,
                    };
                    if !result.is_empty() && !result.ends_with('_') {
                        result.push('_');
                    }
                    result += replacement;
                }
            }
        }
        result
    }

    fn sanitize_string(&self, name: &str) -> String {
        let mut result = String::with_capacity(name.len());
        for c in name.chars() {
            match c {
                '\"' => result += "\\\"",
                '?' => result += "\\?",
                '\\' => result += "\\\\",
                '\u{0007}' => result += "\\a",
                '\u{0008}' => result += "\\b",
                '\u{000b}' => result += "\\v",
                '\u{000c}' => result += "\\f",
                '\n' => result += "\\n",
                '\r' => result += "\\r",
                '\t' => result += "\\t",
                '\0' => result += "\\0",
                '\u{0001}'..='\u{001f}' => write!(result, "\\x{:02x}", c as u32).unwrap(),
                _ => result.push(c),
            }
        }
        result
    }

    fn add_character(&mut self, c: u32) {
        match char::from_u32(c) {
            Some('\'') => add!(self, "'\\''"),
            Some('\\') => add!(self, "'\\\\'"),
            Some('\u{000c}') => add!(self, "'\\f'"),
            Some('\n') => add!(self, "'\\n'"),
            Some('\t') => add!(self, "'\\t'"),
            Some('\r') => add!(self, "'\\r'"),
            Some(ch) => {
                if c == 0 {
                    add!(self, "0");
                } else if ch == ' ' || ch.is_ascii_graphic() {
                    add!(self, "'{ch}'");
                } else {
                    add!(self, "0x{c:02x}");
                }
            }
            None => add!(self, "0x{c:02x}"),
        }
    }
}

