        .map_err(|e| anyhow!("{e}"))?;

    let src_path = opts.out_path.unwrap_or_else(|| repo_path.join("src"));
    let header_path = src_path.join("tree_sitter");

    // Ensure that the output directory exists.
    fs::create_dir_all(&src_path)?;

    let grammar_json_path = src_path.join("grammar.json");
    let same_file = match (grammar_path.canonicalize(), grammar_json_path.canonicalize()) {
        (Ok(a), Ok(b)) => a == b,
        _ => false,
    };
    if !same_file {
        fs::write(&grammar_json_path, &grammar_json)
            .with_context(|| format!("Failed to write grammar.json to {}", grammar_json_path.display()))?;
    }

    // Parse and preprocess the grammar.
    let input_grammar = parse_grammar(&grammar_json)?;

    // Determine the ABI version and semantic version from tree-sitter.json
    let tree_sitter_json_path = std::env::current_dir()?.join("tree-sitter.json");
    let mut abi_version = opts.abi_version;
    let mut semantic_version = None;
    if tree_sitter_json_path.exists() {
        if let Ok(json) = crate::tsjson::TreeSitterJSON::from_file(&tree_sitter_json_path) {
            let v = &json.metadata.version;
            semantic_version = Some(SemanticVersion {
                major: v.major as u8,
                minor: v.minor as u8,
                patch: v.patch as u8,
            });
        }
    } else if abi_version == ABI_VERSION_MAX && !opts.abi_explicit {
        eprintln!(
            "{} No `tree-sitter.json` file found in your grammar, this file is required to generate with ABI {ABI_VERSION_MAX}. Using ABI version {} instead.\nThis file can be set up with `tree-sitter init`. For more information, see https://tree-sitter.github.io/tree-sitter/cli/init.\n",
            warning_prefix(),
            ABI_VERSION_MAX - 1
        );
        abi_version = ABI_VERSION_MAX - 1;
    }

    // Generate the parser and related files.
    let GeneratedParser {
        c_code,
        node_types_json,
    } = generate_parser_for_grammar_with_opts(
        &input_grammar,
        abi_version,
        opts.report_symbol_name,
        semantic_version,
        opts.merge_compatible_states,
    )?;

    write_file(&src_path.join("node-types.json"), node_types_json)?;

    if opts.generate_parser {
        write_file(&src_path.join("parser.c"), c_code)?;
        fs::create_dir_all(&header_path)?;
        write_file(&header_path.join("alloc.h"), ALLOC_HEADER)?;
        write_file(&header_path.join("array.h"), ARRAY_HEADER)?;
        write_file(&header_path.join("parser.h"), PARSER_HEADER)?;
    }

    Ok(())
}

pub fn generate_parser_for_grammar(grammar_json: &str) -> Result<(String, GeneratedParser)> {
    let input_grammar = parse_grammar(grammar_json)?;
    let parser = generate_parser_for_grammar_with_opts(&input_grammar, ABI_VERSION_MAX, None, None, true)?;
    Ok((input_grammar.name.clone(), parser))
}

fn generate_parser_for_grammar_with_opts(
    input_grammar: &InputGrammar,
    abi_version: usize,
    report_symbol_name: Option<&str>,
    semantic_version: Option<SemanticVersion>,
    merge_compatible_states: bool,
) -> Result<GeneratedParser> {
    if !(ABI_VERSION_MIN..=ABI_VERSION_MAX).contains(&abi_version) {
        return Err(anyhow!(
            "This version of Tree-sitter can only generate parsers with ABI version {ABI_VERSION_MIN} - {ABI_VERSION_MAX}, not {abi_version}"
        ));
    }

    let (syntax_grammar, lexical_grammar, inlines, simple_aliases) =
        prepare_grammar(input_grammar)?;
    let variable_info =
        node_types::get_variable_info(&syntax_grammar, &lexical_grammar, &simple_aliases)?;
    let supertype_symbol_map =
        node_types::get_supertype_symbol_map(&syntax_grammar, &simple_aliases, &variable_info);
    let node_types_json = node_types::generate_node_types_json(
        &syntax_grammar,
        &lexical_grammar,
        &simple_aliases,
        &variable_info,
    );
    let tables = build_tables(
        &syntax_grammar,
        &lexical_grammar,
        &simple_aliases,
        &variable_info,
        &inlines,
        report_symbol_name,
        merge_compatible_states,
    )?;
    let c_code = render_c_code(
        &input_grammar.name,
        tables,
        syntax_grammar,
        lexical_grammar,
        simple_aliases,
        abi_version,
        semantic_version,
        supertype_symbol_map,
    );
    Ok(GeneratedParser {
        c_code,
        node_types_json: serde_json::to_string_pretty(&node_types_json).unwrap(),
    })
}

pub fn load_grammar_file(grammar_path: &Path, js_runtime: Option<&str>) -> Result<String, LoadGrammarError> {
    if grammar_path.is_dir() {
        return Err(LoadGrammarError::Other(format!(
            "Path to a grammar file with `.js` or `.json` extension is required ({})",
            grammar_path.display()
        )));
    }
    match grammar_path.extension().and_then(|e| e.to_str()) {
        Some("js") => load_js_grammar_file(grammar_path, js_runtime),
        Some("json") => fs::read_to_string(grammar_path).map_err(|error| {
            LoadGrammarError::Io(IoErrorWithPath {
                error,
                path: grammar_path.to_path_buf(),
            })
        }),
        _ => Err(LoadGrammarError::Other(format!(
            "Unknown grammar file extension: {}",
            grammar_path.display()
        ))),
    }
}

fn load_js_grammar_file(grammar_path: &Path, js_runtime: Option<&str>) -> Result<String, LoadGrammarError> {
    let grammar_path = match fs::canonicalize(grammar_path) {
        Ok(p) => p,
        Err(error) => {
            return Err(LoadGrammarError::Io(IoErrorWithPath {
                error,
                path: grammar_path.to_path_buf(),
            }))
        }
    };

    let js_runtime = js_runtime.unwrap_or("node");
    if js_runtime == "native" {
        return crate::js::evaluate_grammar_file(&grammar_path)
            .map_err(|e| LoadGrammarError::Other(e.to_string()));
    }

    let mut js_command = Command::new(js_runtime);
    match js_runtime {
        "node" => {
            js_command.args(["--input-type=module", "-"]);
        }
        "bun" => {
            js_command.arg("-");
        }
        "deno" => {
            js_command.args(["run", "--allow-all", "-"]);
        }
        _ => {}
    }

    let mut js_process = match js_command
        .env("TREE_SITTER_GRAMMAR_PATH", &grammar_path)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
    {
        Ok(p) => p,
        Err(error) => return Err(LoadGrammarError::Runtime(js_runtime.to_string(), error)),
    };

    let mut js_stdin = js_process.stdin.take().unwrap();
    let dsl = crate::js::DSL_JS;
    let script = format!(
        "{dsl}\nglobalThis.__tree_sitter_grammar_path = {:?};\n",
        grammar_path.display()
    );
    let _ = js_stdin.write_all(script.as_bytes());
    drop(js_stdin);

    let output = js_process
        .wait_with_output()
        .map_err(|e| LoadGrammarError::Runtime(js_runtime.to_string(), e))?;
    if !output.status.success() {
        return Err(LoadGrammarError::Other(format!(
            "`{js_runtime}` process exited with status {}",
            output.status
        )));
    }
    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
    Ok(stdout)
}

pub fn write_file(path: &Path, body: impl AsRef<[u8]>) -> Result<()> {
    fs::write(path, body)
        .with_context(|| format!("Failed to write {:?}", path.file_name().unwrap()))
}
