import re,sys
def lex_states(path, fn="ts_lex"):
    s=open(path).read()
    m=re.search(r'static bool '+fn+r'\(TSLexer \*lexer, TSStateId state\) \{(.*?)\n\}\n', s, re.S)
    body=m.group(1)
    states={}
    for cm in re.finditer(r'    case (\d+):\n(.*?)      END_STATE\(\);', body, re.S):
        st=int(cm.group(1)); b=cm.group(2)
        acc=re.search(r'ACCEPT_TOKEN\((\w+)\)', b)
        eof='if (eof)' in b
        trans=[]
        for t in re.finditer(r'if \((.*?)\) (ADVANCE|SKIP)\((\d+)\);', b, re.S):
            cond=re.sub(r'\s+',' ',t.group(1)); 
            if cond=='eof': continue
            trans.append((cond,t.group(2),int(t.group(3))))
        am=re.search(r'ADVANCE_MAP\((.*?)\);', b, re.S)
        if am:
            pairs=re.findall(r"('(?:\\.|[^'])*'|0x[0-9a-f]+|\d+), (\d+),", am.group(1))
            for c,tg in pairs: trans.append((c,'ADVANCE',int(tg)))
        states[st]=(acc.group(1) if acc else None, eof, trans)
    return states
def sig(states, st, depth=2):
    acc,eof,trans=states[st]
    if depth==0: return (acc,eof,tuple((c,k) for c,k,t in trans))
    return (acc,eof,tuple((c,k,sig(states,t,depth-1)) for c,k,t in trans))
