impl Language {
    pub unsafe fn from_raw(ptr: *const TSLanguage) -> Self {
        Self { ptr }
    }

    #[inline]
    fn raw(&self) -> &TSLanguage {
        unsafe { &*self.ptr }
    }

    pub fn abi_version(&self) -> u32 {
        self.raw().abi_version
    }

    pub fn name(&self) -> Option<String> {
        let raw = self.raw();
        if raw.abi_version >= 15 && !raw.name.is_null() {
            unsafe { Some(CStr::from_ptr(raw.name).to_string_lossy().into_owned()) }
        } else {
            None
        }
    }

    pub fn metadata(&self) -> Option<TSLanguageMetadata> {
        let raw = self.raw();
        if raw.abi_version >= 15 {
            Some(raw.metadata)
        } else {
            None
        }
    }

    pub fn symbol_count(&self) -> u32 {
        self.raw().symbol_count + self.raw().alias_count
    }

    pub fn token_count(&self) -> u32 {
        self.raw().token_count
    }

    pub fn external_token_count(&self) -> u32 {
        self.raw().external_token_count
    }

    pub fn state_count(&self) -> u32 {
        self.raw().state_count
    }

    pub fn field_count(&self) -> u32 {
        self.raw().field_count
    }

    pub fn has_external_scanner(&self) -> bool {
        self.raw().external_token_count > 0
    }

    pub fn keyword_capture_token(&self) -> TSSymbol {
        self.raw().keyword_capture_token
    }

    pub fn has_keyword_lex_fn(&self) -> bool {
        self.raw().keyword_lex_fn.is_some()
    }

    pub fn is_symbol_external(&self, symbol: TSSymbol) -> bool {
        0 < symbol && (symbol as u32) < self.raw().external_token_count + 1
    }

    pub fn symbol_name(&self, symbol: TSSymbol) -> &str {
        if symbol == TS_BUILTIN_SYM_ERROR {
            "ERROR"
        } else if symbol == TS_BUILTIN_SYM_ERROR_REPEAT {
            "_ERROR"
        } else if (symbol as u32) < self.symbol_count() {
            unsafe {
                let p = *self.raw().symbol_names.add(symbol as usize);
                CStr::from_ptr(p).to_str().unwrap_or("")
            }
        } else {
            ""
        }
    }

    pub fn symbol_metadata(&self, symbol: TSSymbol) -> TSSymbolMetadata {
        if symbol == TS_BUILTIN_SYM_ERROR {
            TSSymbolMetadata { visible: true, named: true, supertype: false }
        } else if symbol == TS_BUILTIN_SYM_ERROR_REPEAT {
            TSSymbolMetadata { visible: false, named: false, supertype: false }
        } else {
            unsafe { *self.raw().symbol_metadata.add(symbol as usize) }
        }
    }

    pub fn public_symbol(&self, symbol: TSSymbol) -> TSSymbol {
        if symbol == TS_BUILTIN_SYM_ERROR {
            return symbol;
        }
        unsafe { *self.raw().public_symbol_map.add(symbol as usize) }
    }

    pub fn field_name(&self, field_id: TSFieldId) -> Option<&str> {
        if field_id == 0 || field_id as u32 > self.raw().field_count {
            return None;
        }
        unsafe {
            let p = *self.raw().field_names.add(field_id as usize);
            if p.is_null() {
                None
            } else {
                CStr::from_ptr(p).to_str().ok()
            }
        }
    }

    pub fn field_id_for_name(&self, name: &str) -> Option<TSFieldId> {
        for i in 1..=self.raw().field_count {
            if self.field_name(i as TSFieldId) == Some(name) {
                return Some(i as TSFieldId);
            }
        }
        None
    }

    pub fn symbol_for_name(&self, name: &str, named: bool) -> Option<TSSymbol> {
        if name == "ERROR" && named {
            return Some(TS_BUILTIN_SYM_ERROR);
        }
        let count = self.symbol_count();
        for i in 0..count {
            let metadata = self.symbol_metadata(i as TSSymbol);
            if (!metadata.visible && !metadata.supertype) || metadata.named != named {
                continue;
            }
            if self.symbol_name(i as TSSymbol) == name {
                return Some(self.public_symbol(i as TSSymbol));
            }
        }
        None
    }

    pub fn lex_mode(&self, state: TSStateId) -> LexMode {
        let raw = self.raw();
        unsafe {
            if raw.abi_version >= 15 {
                let m = &*(raw.lex_modes as *const TSLexerMode).add(state as usize);
                LexMode {
                    lex_state: m.lex_state,
                    external_lex_state: m.external_lex_state,
                    reserved_word_set_id: m.reserved_word_set_id,
                }
            } else {
                let m = &*(raw.lex_modes as *const TSLexMode).add(state as usize);
                LexMode {
                    lex_state: m.lex_state,
                    external_lex_state: m.external_lex_state,
                    reserved_word_set_id: 0,
                }
            }
        }
    }

    /// Returns the table value for a given symbol and state. For terminals this is an
    /// index into the parse actions table, for non-terminals it is a successor state.
    pub fn lookup(&self, state: TSStateId, symbol: TSSymbol) -> u16 {
        let raw = self.raw();
        unsafe {
            if state as u32 >= raw.large_state_count {
                let index = *raw
                    .small_parse_table_map
                    .add(state as usize - raw.large_state_count as usize);
                let mut data = raw.small_parse_table.add(index as usize);
                let group_count = *data;
                data = data.add(1);
                for _ in 0..group_count {
                    let section_value = *data;
                    data = data.add(1);
                    let symbol_count = *data;
                    data = data.add(1);
                    for _ in 0..symbol_count {
                        let s = *data;
                        data = data.add(1);
                        if s == symbol {
                            return section_value;
                        }
                    }
                }
                0
            } else {
                *raw
                    .parse_table
                    .add(state as usize * raw.symbol_count as usize + symbol as usize)
            }
        }
    }

    pub fn has_actions(&self, state: TSStateId, symbol: TSSymbol) -> bool {
        self.lookup(state, symbol) != 0
    }

    pub fn table_entry(&self, state: TSStateId, symbol: TSSymbol) -> TableEntry {
        if symbol == TS_BUILTIN_SYM_ERROR || symbol == TS_BUILTIN_SYM_ERROR_REPEAT {
            return TableEntry { actions: Vec::new(), reusable: false };
        }
        let action_index = self.lookup(state, symbol);
        self.actions_at(action_index)
    }

    fn actions_at(&self, action_index: u16) -> TableEntry {
        let raw = self.raw();
        unsafe {
            let entry = raw.parse_actions.add(action_index as usize);
            let header = (*entry).entry;
            let mut actions = Vec::with_capacity(header.count as usize);
            for i in 0..header.count as usize {
                let action = (*entry.add(1 + i)).action;
                actions.push(convert_action(action));
            }
            TableEntry { actions, reusable: header.reusable }
        }
    }

    pub fn has_reduce_action(&self, state: TSStateId, symbol: TSSymbol) -> bool {
        let entry = self.table_entry(state, symbol);
        matches!(entry.actions.first(), Some(ParseAction::Reduce { .. }))
    }

    pub fn next_state(&self, state: TSStateId, symbol: TSSymbol) -> TSStateId {
        if symbol == TS_BUILTIN_SYM_ERROR || symbol == TS_BUILTIN_SYM_ERROR_REPEAT {
            0
        } else if (symbol as u32) < self.raw().token_count {
            let entry = self.table_entry(state, symbol);
            if let Some(ParseAction::Shift { state: next, extra, .. }) = entry.actions.last() {
                if *extra {
                    state
                } else {
                    *next
                }
            } else {
                0
            }
        } else {
            self.lookup(state, symbol)
        }
    }

    /// Iterate over all symbols valid in a state, along with their table entries.
    pub fn lookaheads(&self, state: TSStateId) -> Vec<(TSSymbol, u16)> {
        let raw = self.raw();
        let mut result = Vec::new();
        unsafe {
            if state as u32 >= raw.large_state_count {
                let index = *raw
                    .small_parse_table_map
                    .add(state as usize - raw.large_state_count as usize);
                let mut data = raw.small_parse_table.add(index as usize);
                let group_count = *data;
                data = data.add(1);
                for _ in 0..group_count {
                    let section_value = *data;
                    data = data.add(1);
                    let symbol_count = *data;
                    data = data.add(1);
                    for _ in 0..symbol_count {
                        result.push((*data, section_value));
                        data = data.add(1);
                    }
                }
            } else {
                let row = raw.parse_table.add(state as usize * raw.symbol_count as usize);
                for symbol in 0..raw.symbol_count {
                    let value = *row.add(symbol as usize);
                    if value != 0 {
                        result.push((symbol as TSSymbol, value));
                    }
                }
            }
        }
        result
    }

    pub fn state_is_primary(&self, state: TSStateId) -> bool {
        let raw = self.raw();
        if raw.abi_version >= 14 {
            unsafe { state == *raw.primary_state_ids.add(state as usize) }
        } else {
            true
        }
    }

    pub fn enabled_external_tokens(&self, external_scanner_state: u16) -> Option<*const bool> {
        let raw = self.raw();
        if external_scanner_state == 0 {
            None
        } else {
            unsafe {
                Some(
                    raw.external_scanner
                        .states
                        .add(raw.external_token_count as usize * external_scanner_state as usize),
                )
            }
        }
    }

    pub fn external_scanner_symbol(&self, external_index: usize) -> TSSymbol {
        unsafe { *self.raw().external_scanner.symbol_map.add(external_index) }
    }

    pub fn alias_at(&self, production_id: u16, child_index: u32) -> TSSymbol {
        if production_id == 0 {
            return 0;
        }
        let raw = self.raw();
        unsafe {
            *raw.alias_sequences.add(
                production_id as usize * raw.max_alias_sequence_length as usize + child_index as usize,
            )
        }
    }

    pub fn alias_sequence(&self, production_id: u16) -> Vec<TSSymbol> {
        let raw = self.raw();
        if production_id == 0 {
            return Vec::new();
        }
        let mut result = Vec::with_capacity(raw.max_alias_sequence_length as usize);
        for i in 0..raw.max_alias_sequence_length as usize {
            unsafe {
                result.push(
                    *raw.alias_sequences
                        .add(production_id as usize * raw.max_alias_sequence_length as usize + i),
                );
            }
        }
        result
    }

    pub fn field_map(&self, production_id: u16) -> &[TSFieldMapEntry] {
        let raw = self.raw();
        if raw.field_count == 0 {
            return &[];
        }
        unsafe {
            let slice = *raw.field_map_slices.add(production_id as usize);
            std::slice::from_raw_parts(
                raw.field_map_entries.add(slice.index as usize),
                slice.length as usize,
            )
        }
    }

    pub fn aliases_for_symbol(&self, original_symbol: TSSymbol) -> Vec<TSSymbol> {
        let raw = self.raw();
        unsafe {
            let mut idx = 0;
            loop {
                let symbol = *raw.alias_map.add(idx);
                idx += 1;
                if symbol == 0 || symbol > original_symbol {
                    break;
                }
                let count = *raw.alias_map.add(idx) as usize;
                idx += 1;
                if symbol == original_symbol {
                    return std::slice::from_raw_parts(raw.alias_map.add(idx), count).to_vec();
                }
                idx += count;
            }
            vec![*raw.public_symbol_map.add(original_symbol as usize)]
        }
    }

    pub fn supertypes(&self) -> Vec<TSSymbol> {
        let raw = self.raw();
        if raw.abi_version < 15 || raw.supertype_count == 0 {
            return Vec::new();
        }
        unsafe {
            std::slice::from_raw_parts(raw.supertype_symbols, raw.supertype_count as usize).to_vec()
        }
    }

    pub fn subtypes(&self, supertype: TSSymbol) -> Vec<TSSymbol> {
        let raw = self.raw();
        if raw.abi_version < 15 || raw.supertype_count == 0 {
            return Vec::new();
        }
        unsafe {
            let slice = *raw.supertype_map_slices.add(supertype as usize);
            std::slice::from_raw_parts(
                raw.supertype_map_entries.add(slice.index as usize),
                slice.length as usize,
            )
            .to_vec()
        }
    }

    pub fn reserved_words(&self, state: TSStateId) -> Vec<TSSymbol> {
        let raw = self.raw();
        if raw.abi_version < 15 || raw.reserved_words.is_null() {
            return Vec::new();
        }
        let mode = self.lex_mode(state);
        if mode.reserved_word_set_id == 0 {
            return Vec::new();
        }
        unsafe {
            let start = raw
                .reserved_words
                .add(mode.reserved_word_set_id as usize * raw.max_reserved_word_set_size as usize);
            let mut result = Vec::new();
            for i in 0..raw.max_reserved_word_set_size as usize {
                let s = *start.add(i);
                if s == 0 {
                    break;
                }
                result.push(s);
            }
            result
        }
    }

    pub unsafe fn lex(&self, lexer: *mut TSLexer, state: TSStateId) -> bool {
        (self.raw().lex_fn.unwrap())(lexer, state)
    }

    pub unsafe fn keyword_lex(&self, lexer: *mut TSLexer, state: TSStateId) -> bool {
        match self.raw().keyword_lex_fn {
            Some(f) => f(lexer, state),
            None => false,
        }
    }

    pub fn external_scanner(&self) -> &TSExternalScanner {
        &self.raw().external_scanner
    }
}

fn convert_action(action: TSParseAction) -> ParseAction {
    unsafe {
        match action.type_ {
            TS_PARSE_ACTION_TYPE_SHIFT => ParseAction::Shift {
                state: action.shift.state,
                extra: action.shift.extra,
                repetition: action.shift.repetition,
            },
            TS_PARSE_ACTION_TYPE_REDUCE => ParseAction::Reduce {
                symbol: action.reduce.symbol,
                child_count: action.reduce.child_count as u32,
                dynamic_precedence: action.reduce.dynamic_precedence as i32,
                production_id: action.reduce.production_id,
            },
            TS_PARSE_ACTION_TYPE_ACCEPT => ParseAction::Accept,
            _ => ParseAction::Recover,
        }
    }
}

/// A dynamically loaded parser library.
pub struct LoadedLibrary {
    handle: *mut c_void,
}

impl LoadedLibrary {
    pub fn open(path: &std::path::Path) -> Result<Self, String> {
        let c_path = std::ffi::CString::new(path.to_string_lossy().as_bytes()).unwrap();
        let handle = unsafe { libc::dlopen(c_path.as_ptr(), libc::RTLD_NOW | libc::RTLD_LOCAL) };
        if handle.is_null() {
            let err = unsafe { CStr::from_ptr(libc::dlerror()) }.to_string_lossy().into_owned();
            return Err(err);
        }
        Ok(Self { handle })
    }

    pub fn language(&self, function_name: &str) -> Result<Language, String> {
        let c_name = std::ffi::CString::new(function_name).unwrap();
        let sym = unsafe { libc::dlsym(self.handle, c_name.as_ptr()) };
        if sym.is_null() {
            let err = unsafe { CStr::from_ptr(libc::dlerror()) }.to_string_lossy().into_owned();
            return Err(err);
        }
        let f: unsafe extern "C" fn() -> *const TSLanguage = unsafe { std::mem::transmute(sym) };
        let ptr = unsafe { f() };
        Ok(unsafe { Language::from_raw(ptr) })
    }
}

impl Drop for LoadedLibrary {
    fn drop(&mut self) {
        // Intentionally leak the library so that language pointers remain valid.
        let _ = c_int::default();
    }
}
