}

#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct TSLexMode {
    pub lex_state: u16,
    pub external_lex_state: u16,
}

#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct TSLexerMode {
    pub lex_state: u16,
