//! The lexer that is passed to the generated lexing functions.
#![allow(dead_code)]

use super::language::{TSLexer, TSSymbol};
use super::point::{Length, Point};
use std::ffi::c_char;

pub const TS_DECODE_ERROR: i32 = -1;
const BYTE_ORDER_MARK: i32 = 0xFEFF;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum InputEncoding {
    Utf8,
    Utf16LE,
    Utf16BE,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Range {
    pub start_byte: u32,
    pub end_byte: u32,
    pub start_point: Point,
    pub end_point: Point,
}

impl Range {
    pub fn full() -> Self {
        Range {
            start_byte: 0,
            end_byte: u32::MAX,
            start_point: Point::new(0, 0),
            end_point: Point::new(u32::MAX, u32::MAX),
        }
    }
}

#[repr(C)]
pub struct Lexer {
    pub data: TSLexer,
    pub current_position: Length,
    pub token_start_position: Length,
    pub token_end_position: Length,
    pub included_ranges: Vec<Range>,
    pub input: Vec<u8>,
    pub encoding: InputEncoding,
    pub current_included_range_index: usize,
    pub lookahead_size: u32,
    pub did_get_column: bool,
    pub at_end: bool,
    pub log: Option<Box<dyn FnMut(&str)>>,
}

pub fn decode_utf8(bytes: &[u8]) -> (i32, u32) {
    if bytes.is_empty() {
        return (0, 1);
    }
    let b0 = bytes[0];
    if b0 < 0x80 {
        return (b0 as i32, 1);
    }
    let (len, init) = if b0 & 0xE0 == 0xC0 {
        (2, (b0 & 0x1F) as u32)
    } else if b0 & 0xF0 == 0xE0 {
        (3, (b0 & 0x0F) as u32)
    } else if b0 & 0xF8 == 0xF0 {
        (4, (b0 & 0x07) as u32)
    } else {
        return (TS_DECODE_ERROR, 1);
    };
    if bytes.len() < len {
        return (TS_DECODE_ERROR, 1);
    }
    let mut cp = init;
    for b in &bytes[1..len] {
        if b & 0xC0 != 0x80 {
            return (TS_DECODE_ERROR, 1);
        }
        cp = (cp << 6) | (b & 0x3F) as u32;
    }
    // Reject overlong encodings and surrogates.
    let valid = match len {
        2 => cp >= 0x80,
        3 => cp >= 0x800 && !(0xD800..=0xDFFF).contains(&cp),
        4 => (0x10000..=0x10FFFF).contains(&cp),
        _ => false,
    };
    if !valid {
        return (TS_DECODE_ERROR, 1);
    }
    (cp as i32, len as u32)
}

pub fn decode_utf16(bytes: &[u8], big_endian: bool) -> (i32, u32) {
    if bytes.len() < 2 {
        return (TS_DECODE_ERROR, 1);
    }
    let read = |i: usize| -> u32 {
        if big_endian {
            ((bytes[i] as u32) << 8) | bytes[i + 1] as u32
        } else {
            ((bytes[i + 1] as u32) << 8) | bytes[i] as u32
        }
    };
    let w1 = read(0);
    if (0xD800..0xDC00).contains(&w1) {
        if bytes.len() < 4 {
            return (TS_DECODE_ERROR, 2);
        }
        let w2 = read(2);
        if (0xDC00..0xE000).contains(&w2) {
            let cp = 0x10000 + ((w1 - 0xD800) << 10) + (w2 - 0xDC00);
            return (cp as i32, 4);
        }
        return (TS_DECODE_ERROR, 2);
    }
    if (0xDC00..0xE000).contains(&w1) {
        return (TS_DECODE_ERROR, 2);
    }
    (w1 as i32, 2)
}

unsafe extern "C" fn lexer_advance(lexer: *mut TSLexer, skip: bool) {
    let this = &mut *(lexer as *mut Lexer);
    if this.at_end {
        return;
    }
    if let Some(log) = &mut this.log {
        let c = this.data.lookahead;
        let msg = if skip {
            format!("skip character:{}", describe_char(c))
        } else {
            format!("consume character:{}", describe_char(c))
        };
        log(&msg);
    }
    this.do_advance(skip);
}

pub fn describe_char(c: i32) -> String {
    match c {
        0 => "''".to_string(),
        10 => "'\\n'".to_string(),
        9 => "'\\t'".to_string(),
        13 => "'\\r'".to_string(),
        39 => "'\\''".to_string(),
        92 => "'\\\\'".to_string(),
        _ => {
            if let Some(ch) = char::from_u32(c as u32) {
                if c >= 32 && c < 127 {
                    format!("'{ch}'")
                } else {
                    format!("{c}")
                }
            } else {
                format!("{c}")
            }
        }
    }
}

unsafe extern "C" fn lexer_mark_end(lexer: *mut TSLexer) {
    let this = &mut *(lexer as *mut Lexer);
    this.mark_end();
}

unsafe extern "C" fn lexer_get_column(lexer: *mut TSLexer) -> u32 {
    let this = &mut *(lexer as *mut Lexer);
    this.get_column()
}

unsafe extern "C" fn lexer_is_at_included_range_start(lexer: *const TSLexer) -> bool {
    let this = &*(lexer as *const Lexer);
    if this.current_included_range_index < this.included_ranges.len() {
        let range = &this.included_ranges[this.current_included_range_index];
        this.current_position.bytes == range.start_byte
    } else {
        false
    }
}

unsafe extern "C" fn lexer_eof(lexer: *const TSLexer) -> bool {
    let this = &*(lexer as *const Lexer);
    this.eof()
}

unsafe extern "C" fn lexer_log(_lexer: *const TSLexer, _fmt: *const c_char, mut _args: ...) {
    // External scanner logging is ignored (formatting varargs is not portable here).
}

impl Lexer {
    pub fn new() -> Box<Self> {
        Box::new(Lexer {
            data: TSLexer {
                lookahead: 0,
                result_symbol: 0,
                advance: Some(lexer_advance),
                mark_end: Some(lexer_mark_end),
                get_column: Some(lexer_get_column),
                is_at_included_range_start: Some(lexer_is_at_included_range_start),
                eof: Some(lexer_eof),
                log: Some(lexer_log),
            },
            current_position: Length::zero(),
            token_start_position: Length::zero(),
            token_end_position: Length::undefined(),
            included_ranges: vec![Range::full()],
            input: Vec::new(),
            encoding: InputEncoding::Utf8,
            current_included_range_index: 0,
            lookahead_size: 0,
            did_get_column: false,
            at_end: false,
            log: None,
        })
    }

    pub fn as_ts_lexer(&mut self) -> *mut TSLexer {
        &mut self.data as *mut TSLexer
    }

    pub fn set_input(&mut self, input: Vec<u8>, encoding: InputEncoding) {
        self.input = input;
        self.encoding = encoding;
        self.goto(Length::zero());
    }

    pub fn set_included_ranges(&mut self, ranges: &[Range]) -> bool {
        if ranges.is_empty() {
            self.included_ranges = vec![Range::full()];
            return true;
        }
        let mut prev_end = 0;
        for r in ranges {
            if r.start_byte < prev_end || r.end_byte < r.start_byte {
                return false;
            }
            prev_end = r.end_byte;
        }
        self.included_ranges = ranges.to_vec();
        true
    }

    pub fn reset(&mut self, position: Length) {
        if position != self.current_position {
            self.goto(position);
        }
    }

    pub fn eof(&self) -> bool {
        self.current_included_range_index == self.included_ranges.len()
    }

    fn current_range(&self) -> Option<&Range> {
        self.included_ranges.get(self.current_included_range_index)
    }

    fn get_lookahead(&mut self) {
        let pos = self.current_position.bytes as usize;
        if pos >= self.input.len() {
            self.lookahead_size = 1;
            self.data.lookahead = 0;
            return;
        }
        let (cp, size) = match self.encoding {
            InputEncoding::Utf8 => decode_utf8(&self.input[pos..]),
            InputEncoding::Utf16LE => decode_utf16(&self.input[pos..], false),
            InputEncoding::Utf16BE => decode_utf16(&self.input[pos..], true),
        };
        self.data.lookahead = cp;
        self.lookahead_size = if cp == TS_DECODE_ERROR { 1 } else { size };
    }

    pub fn goto(&mut self, position: Length) {
        self.current_position = position;
        let mut found_included_range = false;
        for i in 0..self.included_ranges.len() {
            let range = self.included_ranges[i];
            if range.end_byte > self.current_position.bytes && range.end_byte > range.start_byte {
                if range.start_byte >= self.current_position.bytes {
                    self.current_position = Length {
                        bytes: range.start_byte,
                        extent: range.start_point,
                    };
                }
                self.current_included_range_index = i;
                found_included_range = true;
                break;
            }
        }

        if found_included_range {
            self.at_end = false;
            self.lookahead_size = 0;
            self.data.lookahead = 0;
        } else {
            self.current_included_range_index = self.included_ranges.len();
            let last = *self.included_ranges.last().unwrap();
            let end_bytes = last.end_byte.min(self.input.len() as u32);
            let end_point = if last.end_byte as usize > self.input.len() {
                self.point_at_byte(end_bytes)
            } else {
                last.end_point
            };
            self.current_position = Length {
                bytes: end_bytes,
                extent: end_point,
            };
            self.at_end = true;
            self.lookahead_size = 1;
            self.data.lookahead = 0;
        }
    }

    /// Compute the point for a byte offset by scanning the input (used only
    /// when the included range extends beyond the input).
    fn point_at_byte(&self, byte: u32) -> Point {
        let mut point = Point::new(0, 0);
        let slice = &self.input[..(byte as usize).min(self.input.len())];
        let mut i = 0;
