use std::cmp::Ordering;

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub struct Point {
    pub row: u32,
    pub column: u32,
}

impl Point {
    pub const fn new(row: u32, column: u32) -> Self {
        Point { row, column }
    }

    pub fn max() -> Self {
        Point { row: u32::MAX, column: u32::MAX }
    }

    pub fn add(self, other: Point) -> Point {
        if other.row > 0 {
            Point::new(self.row + other.row, other.column)
        } else {
            Point::new(self.row, self.column + other.column)
        }
    }

    pub fn sub(self, other: Point) -> Point {
        if self.row > other.row {
            Point::new(self.row - other.row, self.column)
        } else {
            Point::new(0, self.column.saturating_sub(other.column))
        }
    }
}

impl PartialOrd for Point {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for Point {
    fn cmp(&self, other: &Self) -> Ordering {
        (self.row, self.column).cmp(&(other.row, other.column))
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Length {
    pub bytes: u32,
    pub extent: Point,
}

impl Length {
    pub const fn zero() -> Self {
        Length { bytes: 0, extent: Point::new(0, 0) }
    }

    pub fn undefined() -> Self {
        Length { bytes: u32::MAX, extent: Point::new(0, 1) }
    }

    pub fn is_undefined(&self) -> bool {
        self.bytes == u32::MAX && self.extent.row == 0 && self.extent.column == 1
    }

    pub fn add(self, other: Length) -> Length {
        Length {
            bytes: self.bytes + other.bytes,
            extent: self.extent.add(other.extent),
        }
    }

    pub fn sub(self, other: Length) -> Length {
        Length {
            bytes: self.bytes - other.bytes,
            extent: self.extent.sub(other.extent),
        }
    }

    pub fn saturating_sub(self, other: Length) -> Length {
        if self.bytes > other.bytes {
            self.sub(other)
        } else {
            Length::zero()
        }
    }
