use super::point::{Length, Point};
use std::ffi::c_char;

pub const TS_DECODE_ERROR: i32 = -1;
const BYTE_ORDER_MARK: i32 = 0xFEFF;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum InputEncoding {
    Utf8,
    Utf16LE,
    Utf16BE,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Range {
    pub start_byte: u32,
    pub end_byte: u32,
    pub start_point: Point,
    pub end_point: Point,
}

impl Range {
    pub fn full() -> Self {
        Range {
            start_byte: 0,
            end_byte: u32::MAX,
            start_point: Point::new(0, 0),
            end_point: Point::new(u32::MAX, u32::MAX),
        }
    }
