    pub current_included_range_index: usize,
    pub lookahead_size: u32,
    pub did_get_column: bool,
    pub at_end: bool,
    pub log: Option<Box<dyn FnMut(&str)>>,
}

pub fn decode_utf8(bytes: &[u8]) -> (i32, u32) {
    if bytes.is_empty() {
        return (0, 1);
    }
    let b0 = bytes[0];
    if b0 < 0x80 {
        return (b0 as i32, 1);
    }
    let (len, init) = if b0 & 0xE0 == 0xC0 {
        (2, (b0 & 0x1F) as u32)
    } else if b0 & 0xF0 == 0xE0 {
        (3, (b0 & 0x0F) as u32)
    } else if b0 & 0xF8 == 0xF0 {
        (4, (b0 & 0x07) as u32)
    } else {
        return (TS_DECODE_ERROR, 1);
    };
    if bytes.len() < len {
        return (TS_DECODE_ERROR, 1);
    }
    let mut cp = init;
    for b in &bytes[1..len] {
        if b & 0xC0 != 0x80 {
            return (TS_DECODE_ERROR, 1);
        }
        cp = (cp << 6) | (b & 0x3F) as u32;
    }
    // Reject overlong encodings and surrogates.
    let valid = match len {
        2 => cp >= 0x80,
        3 => cp >= 0x800 && !(0xD800..=0xDFFF).contains(&cp),
        4 => (0x10000..=0x10FFFF).contains(&cp),
        _ => false,
    };
    if !valid {
        return (TS_DECODE_ERROR, 1);
    }
    (cp as i32, len as u32)
}

pub fn decode_utf16(bytes: &[u8], big_endian: bool) -> (i32, u32) {
    if bytes.len() < 2 {
        return (TS_DECODE_ERROR, 1);
    }
    let read = |i: usize| -> u32 {
        if big_endian {
            ((bytes[i] as u32) << 8) | bytes[i + 1] as u32
        } else {
            ((bytes[i + 1] as u32) << 8) | bytes[i] as u32
        }
    };
    let w1 = read(0);
    if (0xD800..0xDC00).contains(&w1) {
        if bytes.len() < 4 {
            return (TS_DECODE_ERROR, 2);
        }
        let w2 = read(2);
        if (0xDC00..0xE000).contains(&w2) {
            let cp = 0x10000 + ((w1 - 0xD800) << 10) + (w2 - 0xDC00);
            return (cp as i32, 4);
        }
        return (TS_DECODE_ERROR, 2);
    }
    if (0xDC00..0xE000).contains(&w1) {
        return (TS_DECODE_ERROR, 2);
    }
    (w1 as i32, 2)
}

