//! Syntax tree nodes as produced by the parser.
#![allow(dead_code)]

use super::language::{Language, TSStateId, TSSymbol, TS_BUILTIN_SYM_END, TS_BUILTIN_SYM_ERROR, TS_BUILTIN_SYM_ERROR_REPEAT};
use super::point::Length;
use std::rc::Rc;

pub const ERROR_COST_PER_RECOVERY: u32 = 500;
pub const ERROR_COST_PER_MISSING_TREE: u32 = 110;
pub const ERROR_COST_PER_SKIPPED_TREE: u32 = 100;
pub const ERROR_COST_PER_SKIPPED_LINE: u32 = 30;
pub const ERROR_COST_PER_SKIPPED_CHAR: u32 = 1;
pub const TS_TREE_STATE_NONE: TSStateId = u16::MAX;

#[derive(Debug)]
pub struct SubtreeData {
    pub symbol: TSSymbol,
    pub parse_state: TSStateId,
    pub padding: Length,
    pub size: Length,
    pub lookahead_bytes: u32,
    pub error_cost: u32,
    pub visible: bool,
    pub named: bool,
    pub extra: bool,
    pub fragile_left: bool,
    pub fragile_right: bool,
    pub has_changes: bool,
    pub has_external_tokens: bool,
    pub has_external_scanner_state_change: bool,
    pub depends_on_column: bool,
    pub is_missing: bool,
    pub is_keyword: bool,
    // Non-terminal data
    pub visible_child_count: u32,
    pub named_child_count: u32,
    pub visible_descendant_count: u32,
    pub dynamic_precedence: i32,
    pub repeat_depth: u16,
    pub production_id: u16,
    pub first_leaf_symbol: TSSymbol,
    pub first_leaf_parse_state: TSStateId,
    pub children: Vec<Subtree>,
    // External scanner state for external tokens
    pub external_scanner_state: Vec<u8>,
    // Lookahead char for error leaves
    pub lookahead_char: i32,
}

#[derive(Clone, Debug)]
pub struct Subtree(pub Rc<SubtreeData>);

impl std::ops::Deref for Subtree {
    type Target = SubtreeData;
    fn deref(&self) -> &SubtreeData {
        &self.0
    }
}

impl Subtree {
    pub fn ptr_eq(&self, other: &Subtree) -> bool {
        Rc::ptr_eq(&self.0, &other.0)
    }

    pub fn make_mut(&mut self) -> &mut SubtreeData {
        Rc::make_mut(&mut self.0)
    }

    pub fn new_leaf(
        symbol: TSSymbol,
        padding: Length,
        size: Length,
        lookahead_bytes: u32,
        parse_state: TSStateId,
        has_external_tokens: bool,
        depends_on_column: bool,
        is_keyword: bool,
        language: &Language,
    ) -> Subtree {
        let metadata = language.symbol_metadata(symbol);
        Subtree(Rc::new(SubtreeData {
            symbol,
            parse_state,
            padding,
            size,
            lookahead_bytes,
            error_cost: 0,
            visible: metadata.visible,
            named: metadata.named,
            extra: symbol == TS_BUILTIN_SYM_END,
            fragile_left: false,
            fragile_right: false,
            has_changes: false,
            has_external_tokens,
            has_external_scanner_state_change: false,
            depends_on_column,
            is_missing: false,
            is_keyword,
            visible_child_count: 0,
            named_child_count: 0,
            visible_descendant_count: 0,
            dynamic_precedence: 0,
            repeat_depth: 0,
            production_id: 0,
            first_leaf_symbol: 0,
            first_leaf_parse_state: 0,
            children: Vec::new(),
            external_scanner_state: Vec::new(),
            lookahead_char: 0,
        }))
    }

    pub fn new_error(
        lookahead_char: i32,
        padding: Length,
        size: Length,
        bytes_scanned: u32,
        parse_state: TSStateId,
        language: &Language,
    ) -> Subtree {
        let mut result = Self::new_leaf(
            TS_BUILTIN_SYM_ERROR,
            padding,
            size,
            bytes_scanned,
            parse_state,
            false,
            false,
            false,
            language,
        );
        let data = result.make_mut();
        data.fragile_left = true;
        data.fragile_right = true;
        data.lookahead_char = lookahead_char;
        result
    }

    pub fn new_missing_leaf(
        symbol: TSSymbol,
        padding: Length,
        lookahead_bytes: u32,
        language: &Language,
    ) -> Subtree {
        let mut result = Self::new_leaf(
            symbol,
            padding,
            Length::zero(),
            lookahead_bytes,
            0,
            false,
            false,
            false,
            language,
        );
        result.make_mut().is_missing = true;
        result
    }

    pub fn new_node(
        symbol: TSSymbol,
        children: Vec<Subtree>,
        production_id: u16,
        language: &Language,
    ) -> Subtree {
        let metadata = language.symbol_metadata(symbol);
        let fragile = symbol == TS_BUILTIN_SYM_ERROR || symbol == TS_BUILTIN_SYM_ERROR_REPEAT;
        let mut data = SubtreeData {
            symbol,
            parse_state: 0,
            padding: Length::zero(),
            size: Length::zero(),
            lookahead_bytes: 0,
            error_cost: 0,
            visible: metadata.visible,
            named: metadata.named,
            extra: false,
            fragile_left: fragile,
            fragile_right: fragile,
            has_changes: false,
            has_external_tokens: false,
            has_external_scanner_state_change: false,
            depends_on_column: false,
            is_missing: false,
            is_keyword: false,
            visible_child_count: 0,
            named_child_count: 0,
            visible_descendant_count: 0,
            dynamic_precedence: 0,
            repeat_depth: 0,
            production_id,
            first_leaf_symbol: 0,
            first_leaf_parse_state: 0,
            children,
            external_scanner_state: Vec::new(),
            lookahead_char: 0,
        };
        data.summarize_children(language);
        Subtree(Rc::new(data))
    }

    pub fn new_error_node(children: Vec<Subtree>, extra: bool, language: &Language) -> Subtree {
        let mut result = Self::new_node(TS_BUILTIN_SYM_ERROR, children, 0, language);
        result.make_mut().extra = extra;
        result
    }

    pub fn child_count(&self) -> u32 {
        self.children.len() as u32
    }

    pub fn total_size(&self) -> Length {
        self.padding.add(self.size)
    }

    pub fn total_bytes(&self) -> u32 {
        self.padding.bytes + self.size.bytes
    }

    pub fn is_error(&self) -> bool {
        self.symbol == TS_BUILTIN_SYM_ERROR
    }

    pub fn is_eof(&self) -> bool {
        self.symbol == TS_BUILTIN_SYM_END
    }

    pub fn is_fragile(&self) -> bool {
        self.fragile_left || self.fragile_right
    }

    pub fn error_cost(&self) -> u32 {
        if self.is_missing {
            ERROR_COST_PER_MISSING_TREE + ERROR_COST_PER_RECOVERY
        } else {
            self.error_cost
        }
    }

    pub fn leaf_symbol(&self) -> TSSymbol {
        if self.children.is_empty() {
            self.symbol
        } else {
            self.first_leaf_symbol
        }
    }

    pub fn leaf_parse_state(&self) -> TSStateId {
        if self.children.is_empty() {
            self.parse_state
        } else {
            self.first_leaf_parse_state
        }
    }

    pub fn set_symbol(&mut self, symbol: TSSymbol, language: &Language) {
        let metadata = language.symbol_metadata(symbol);
        let data = self.make_mut();
        data.symbol = symbol;
        data.visible = metadata.visible;
        data.named = metadata.named;
    }

    pub fn set_extra(&mut self, extra: bool) {
        self.make_mut().extra = extra;
    }

    pub fn set_children(&mut self, children: Vec<Subtree>, language: &Language) {
        let data = self.make_mut();
        data.children = children;
        data.summarize_children(language);
    }
}

impl SubtreeData {
    pub fn summarize_children(&mut self, language: &Language) {
        self.named_child_count = 0;
        self.visible_child_count = 0;
        self.error_cost = 0;
        self.repeat_depth = 0;
        self.visible_descendant_count = 0;
        self.has_external_tokens = false;
        self.depends_on_column = false;
        self.has_external_scanner_state_change = false;
        self.dynamic_precedence = 0;

        let mut structural_index = 0usize;
        let alias_sequence = language.alias_sequence(self.production_id);
        let mut lookahead_end_byte = 0u32;

        let child_count = self.children.len();
        for i in 0..child_count {
            let child = &self.children[i];

            if self.size.extent.row == 0 && child.depends_on_column {
                self.depends_on_column = true;
            }

            if child.has_external_scanner_state_change {
                self.has_external_scanner_state_change = true;
            }

            if i == 0 {
                self.padding = child.padding;
                self.size = child.size;
            } else {
                self.size = self.size.add(child.total_size());
            }

            let child_lookahead_end_byte = self.padding.bytes + self.size.bytes + child.lookahead_bytes;
            if child_lookahead_end_byte > lookahead_end_byte {
                lookahead_end_byte = child_lookahead_end_byte;
            }

            if child.symbol != TS_BUILTIN_SYM_ERROR_REPEAT {
                self.error_cost += child.error_cost();
            }

            let grandchild_count = child.child_count();
            if self.symbol == TS_BUILTIN_SYM_ERROR || self.symbol == TS_BUILTIN_SYM_ERROR_REPEAT {
                if !child.extra && !(child.is_error() && grandchild_count == 0) {
                    if child.visible {
                        self.error_cost += ERROR_COST_PER_SKIPPED_TREE;
                    } else if grandchild_count > 0 {
                        self.error_cost += ERROR_COST_PER_SKIPPED_TREE * child.visible_child_count;
                    }
                }
            }

            self.dynamic_precedence += child.dynamic_precedence;
            self.visible_descendant_count += child.visible_descendant_count;

            let alias = alias_sequence.get(structural_index).copied().unwrap_or(0);
            if !alias_sequence.is_empty() && alias != 0 && !child.extra {
                self.visible_descendant_count += 1;
                self.visible_child_count += 1;
                if language.symbol_metadata(alias).named {
                    self.named_child_count += 1;
                }
            } else if child.visible {
                self.visible_descendant_count += 1;
                self.visible_child_count += 1;
                if child.named {
                    self.named_child_count += 1;
                }
            } else if grandchild_count > 0 {
                self.visible_child_count += child.visible_child_count;
                self.named_child_count += child.named_child_count;
            }

            if child.has_external_tokens {
                self.has_external_tokens = true;
            }

            if child.is_error() {
                self.fragile_left = true;
                self.fragile_right = true;
                self.parse_state = TS_TREE_STATE_NONE;
            }

            if !child.extra {
                structural_index += 1;
            }
        }

        self.lookahead_bytes = lookahead_end_byte - self.size.bytes - self.padding.bytes;

        if self.symbol == TS_BUILTIN_SYM_ERROR || self.symbol == TS_BUILTIN_SYM_ERROR_REPEAT {
            self.error_cost += ERROR_COST_PER_RECOVERY
                + ERROR_COST_PER_SKIPPED_CHAR * self.size.bytes
                + ERROR_COST_PER_SKIPPED_LINE * self.size.extent.row;
        }

        if child_count > 0 {
            let first_child = &self.children[0];
            let last_child = &self.children[child_count - 1];

            self.first_leaf_symbol = first_child.leaf_symbol();
            self.first_leaf_parse_state = first_child.leaf_parse_state();

            if first_child.fragile_left {
                self.fragile_left = true;
            }
            if last_child.fragile_right {
                self.fragile_right = true;
            }

            if child_count >= 2 && !self.visible && !self.named && first_child.symbol == self.symbol {
                if first_child.repeat_depth > last_child.repeat_depth {
                    self.repeat_depth = first_child.repeat_depth + 1;
                } else {
                    self.repeat_depth = last_child.repeat_depth + 1;
                }
            }
        }
    }
}

/// Remove trailing extra tokens from a list of children, returning them separately.
pub fn remove_trailing_extras(children: &mut Vec<Subtree>) -> Vec<Subtree> {
    let mut trailing = Vec::new();
    while let Some(last) = children.last() {
        if last.extra {
            trailing.push(children.pop().unwrap());
        } else {
            break;
        }
    }
    trailing.reverse();
    trailing
}

/// Compare two subtrees structurally (used for debugging and testing).
pub fn subtree_compare(left: &Subtree, right: &Subtree) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    let o = left.symbol.cmp(&right.symbol);
    if o != Ordering::Equal {
        return o;
    }
    let o = left.child_count().cmp(&right.child_count());
    if o != Ordering::Equal {
        return o;
    }
    for (l, r) in left.children.iter().zip(right.children.iter()) {
        let o = subtree_compare(l, r);
        if o != Ordering::Equal {
            return o;
        }
    }
    Ordering::Equal
}
