//! The parse stack: a graph-structured stack supporting multiple versions.
#![allow(dead_code)]

use super::language::{TSStateId, ERROR_STATE};
use super::point::Length;
use super::subtree::{Subtree, ERROR_COST_PER_RECOVERY};

pub type StackVersion = usize;
pub const STACK_VERSION_NONE: StackVersion = usize::MAX;
const MAX_LINK_COUNT: usize = 8;
const MAX_ITERATOR_COUNT: usize = 64;

#[derive(Clone, Debug)]
pub struct StackLink {
    pub node: usize,
    pub subtree: Option<Subtree>,
    pub is_pending: bool,
}

#[derive(Clone, Debug)]
pub struct StackNode {
    pub state: TSStateId,
    pub position: Length,
    pub links: Vec<StackLink>,
    pub error_cost: u32,
    pub node_count: u32,
    pub dynamic_precedence: i32,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StackStatus {
    Active,
    Paused,
    Halted,
}

#[derive(Clone, Copy, Debug)]
pub struct StackSummaryEntry {
    pub position: Length,
    pub depth: u32,
    pub state: TSStateId,
}

#[derive(Clone, Debug)]
pub struct StackHead {
    pub node: usize,
    pub last_external_token: Option<Subtree>,
    pub summary: Option<Vec<StackSummaryEntry>>,
    pub node_count_at_last_error: u32,
    pub lookahead_when_paused: Option<Subtree>,
    pub status: StackStatus,
}

#[derive(Clone, Debug)]
pub struct StackSlice {
    pub version: StackVersion,
    pub subtrees: Vec<Subtree>,
}

#[derive(Clone)]
struct StackIterator {
    node: usize,
    subtrees: Vec<Subtree>,
    subtree_count: u32,
    is_pending: bool,
}

pub struct Stack {
    pub nodes: Vec<StackNode>,
    pub heads: Vec<StackHead>,
    base_node: usize,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum StackAction {
    None,
    Stop,
    Pop,
    PopStop,
}

fn subtree_is_equivalent(left: &Option<Subtree>, right: &Option<Subtree>) -> bool {
    match (left, right) {
        (None, None) => true,
        (Some(l), Some(r)) => {
            if l.ptr_eq(r) {
                return true;
            }
            if l.symbol != r.symbol {
                return false;
            }
            if l.error_cost() > 0 && r.error_cost() > 0 {
                return true;
            }
            l.padding.bytes == r.padding.bytes
                && l.size.bytes == r.size.bytes
                && l.child_count() == r.child_count()
                && l.extra == r.extra
                && external_scanner_state_eq(&Some(l.clone()), &Some(r.clone()))
        }
        _ => false,
    }
}

pub fn external_scanner_state_eq(a: &Option<Subtree>, b: &Option<Subtree>) -> bool {
    let empty: &[u8] = &[];
    let sa = a.as_ref().map(|t| t.external_scanner_state.as_slice()).unwrap_or(empty);
    let sb = b.as_ref().map(|t| t.external_scanner_state.as_slice()).unwrap_or(empty);
    sa == sb
}

fn subtree_node_count(subtree: &Subtree) -> u32 {
    if subtree.child_count() == 0 {
        1
    } else {
        subtree.visible_descendant_count + 1
    }
}

impl Stack {
    pub fn new() -> Self {
        let base_node = StackNode {
            state: 1,
            position: Length::zero(),
            links: Vec::new(),
            error_cost: 0,
            node_count: 0,
            dynamic_precedence: 0,
        };
        let mut stack = Stack {
            nodes: vec![base_node],
            heads: Vec::new(),
            base_node: 0,
        };
        stack.heads.push(StackHead {
            node: 0,
            last_external_token: None,
            summary: None,
            node_count_at_last_error: 0,
            lookahead_when_paused: None,
            status: StackStatus::Active,
        });
        stack
    }

    pub fn clear(&mut self) {
        self.heads.clear();
        self.heads.push(StackHead {
            node: self.base_node,
            last_external_token: None,
            summary: None,
            node_count_at_last_error: 0,
            lookahead_when_paused: None,
            status: StackStatus::Active,
        });
    }

    fn node_new(
        &mut self,
        previous_node: Option<usize>,
        subtree: Option<Subtree>,
        is_pending: bool,
        state: TSStateId,
    ) -> usize {
        let mut node = StackNode {
            state,
            position: Length::zero(),
            links: Vec::new(),
            error_cost: 0,
            node_count: 0,
            dynamic_precedence: 0,
        };
        if let Some(prev) = previous_node {
            let prev_node = &self.nodes[prev];
            node.position = prev_node.position;
            node.error_cost = prev_node.error_cost;
            node.dynamic_precedence = prev_node.dynamic_precedence;
            node.node_count = prev_node.node_count;
            if let Some(subtree) = &subtree {
                node.error_cost += subtree.error_cost();
                node.position = node.position.add(subtree.total_size());
                node.node_count += subtree_node_count(subtree);
                node.dynamic_precedence += subtree.dynamic_precedence;
            }
            node.links.push(StackLink {
                node: prev,
                subtree,
                is_pending,
            });
        }
        self.nodes.push(node);
        self.nodes.len() - 1
    }

    fn node_add_link(&mut self, self_id: usize, link: StackLink) {
        if link.node == self_id {
            return;
        }

        let link_count = self.nodes[self_id].links.len();
        for i in 0..link_count {
            let existing_link = self.nodes[self_id].links[i].clone();
            if subtree_is_equivalent(&existing_link.subtree, &link.subtree) {
                // If the previous nodes are the same, we don't need to add a new link.
                if existing_link.node == link.node {
                    return;
                }

                // If the previous nodes are mergeable, merge them recursively.
                let (existing_node, link_node) = (&self.nodes[existing_link.node], &self.nodes[link.node]);
                if existing_node.state == link_node.state
                    && existing_node.position.bytes == link_node.position.bytes
                    && existing_node.error_cost == link_node.error_cost
                {
                    let links = self.nodes[link.node].links.clone();
                    for l in links {
                        self.node_add_link(existing_link.node, l);
                    }
                    let dynamic_precedence = self.nodes[link.node].dynamic_precedence;
                    if dynamic_precedence > self.nodes[existing_link.node].dynamic_precedence {
                        self.nodes[existing_link.node].dynamic_precedence = dynamic_precedence;
                    }
                    return;
                }
            }
        }

        if self.nodes[self_id].links.len() == MAX_LINK_COUNT {
            return;
        }

        let mut node_count = self.nodes[link.node].node_count;
        let mut dynamic_precedence = self.nodes[link.node].dynamic_precedence;
        if let Some(subtree) = &link.subtree {
            node_count += subtree_node_count(subtree);
            dynamic_precedence += subtree.dynamic_precedence;
        }
        let node = &mut self.nodes[self_id];
        node.links.push(link);
        if node_count > node.node_count {
            node.node_count = node_count;
        }
        if dynamic_precedence > node.dynamic_precedence {
            node.dynamic_precedence = dynamic_precedence;
        }
    }

    fn add_version(&mut self, original_version: StackVersion, node: usize) -> StackVersion {
        let orig = &self.heads[original_version];
        let head = StackHead {
            node,
            node_count_at_last_error: orig.node_count_at_last_error,
            last_external_token: orig.last_external_token.clone(),
            summary: None,
            lookahead_when_paused: None,
            status: StackStatus::Active,
        };
        self.heads.push(head);
        self.heads.len() - 1
    }

    fn add_slice(
        &mut self,
        slices: &mut Vec<StackSlice>,
        original_version: StackVersion,
        node: usize,
        subtrees: Vec<Subtree>,
    ) {
        for i in (0..slices.len()).rev() {
            let version = slices[i].version;
            if self.heads[version].node == node {
                slices.insert(i + 1, StackSlice { version, subtrees });
                return;
            }
        }
        let version = self.add_version(original_version, node);
        slices.push(StackSlice { version, subtrees });
    }

    fn iter<F>(&mut self, version: StackVersion, mut callback: F, goal_subtree_count: i32) -> Vec<StackSlice>
    where
        F: FnMut(&StackNode, &StackIterator) -> StackAction,
    {
        let mut slices = Vec::new();
        let include_subtrees = goal_subtree_count >= 0;
        let mut iterators = vec![StackIterator {
            node: self.heads[version].node,
            subtrees: Vec::new(),
            subtree_count: 0,
            is_pending: true,
        }];

        while !iterators.is_empty() {
            let mut i = 0;
            let mut size = iterators.len();
            while i < size {
                let node_id = iterators[i].node;
                let action = callback(&self.nodes[node_id], &iterators[i]);
                let should_pop = matches!(action, StackAction::Pop | StackAction::PopStop);
                let should_stop = matches!(action, StackAction::Stop | StackAction::PopStop)
                    || self.nodes[node_id].links.is_empty();

                if should_pop {
                    let mut subtrees = iterators[i].subtrees.clone();
                    subtrees.reverse();
                    self.add_slice(&mut slices, version, node_id, subtrees);
                }

                if should_stop {
                    iterators.remove(i);
                    size -= 1;
                    continue;
                }

                let link_count = self.nodes[node_id].links.len();
                for j in 1..=link_count {
                    let (link, next_index) = if j == link_count {
                        (self.nodes[node_id].links[0].clone(), i)
                    } else {
                        if iterators.len() >= MAX_ITERATOR_COUNT {
                            continue;
                        }
                        let link = self.nodes[node_id].links[j].clone();
                        let current_iterator = iterators[i].clone();
                        iterators.push(current_iterator);
                        (link, iterators.len() - 1)
                    };

                    let next_iterator = &mut iterators[next_index];
                    next_iterator.node = link.node;
                    if let Some(subtree) = link.subtree {
                        if include_subtrees {
                            next_iterator.subtrees.push(subtree.clone());
                        }
                        if !subtree.extra {
                            next_iterator.subtree_count += 1;
                            if !link.is_pending {
                                next_iterator.is_pending = false;
                            }
                        }
                    } else {
                        next_iterator.subtree_count += 1;
                        next_iterator.is_pending = false;
                    }
                }
                i += 1;
            }
        }
        slices
    }

    pub fn version_count(&self) -> usize {
        self.heads.len()
    }

    pub fn state(&self, version: StackVersion) -> TSStateId {
        self.nodes[self.heads[version].node].state
    }

    pub fn position(&self, version: StackVersion) -> Length {
        self.nodes[self.heads[version].node].position
    }

    pub fn push(&mut self, version: StackVersion, subtree: Option<Subtree>, pending: bool, state: TSStateId) {
        let head_node = self.heads[version].node;
        let is_none = subtree.is_none();
        let new_node = self.node_new(Some(head_node), subtree, pending, state);
        if is_none {
            self.heads[version].node_count_at_last_error = self.nodes[new_node].node_count;
        }
        self.heads[version].node = new_node;
    }

    pub fn pop_count(&mut self, version: StackVersion, count: u32) -> Vec<StackSlice> {
        self.iter(
            version,
            |_, iterator| {
                if iterator.subtree_count == count {
                    StackAction::PopStop
                } else {
                    StackAction::None
                }
            },
            count as i32,
        )
    }

    pub fn pop_pending(&mut self, version: StackVersion) -> Vec<StackSlice> {
        let mut pop = self.iter(
            version,
            |_, iterator| {
                if iterator.subtree_count >= 1 {
                    if iterator.is_pending {
                        StackAction::PopStop
                    } else {
                        StackAction::Stop
                    }
                } else {
                    StackAction::None
                }
            },
            0,
        );
        if !pop.is_empty() {
            let v = pop[0].version;
            self.renumber_version(v, version);
            pop[0].version = version;
        }
        pop
    }

    pub fn pop_error(&mut self, version: StackVersion) -> Vec<Subtree> {
        let node_id = self.heads[version].node;
        let has_error_link = self.nodes[node_id]
            .links
            .iter()
            .any(|l| l.subtree.as_ref().is_some_and(|s| s.is_error()));
        if has_error_link {
            let mut found_error = false;
            let pop = self.iter(
                version,
                |_, iterator| {
                    if !iterator.subtrees.is_empty() {
                        if !found_error && iterator.subtrees[0].is_error() {
                            found_error = true;
                            StackAction::PopStop
                        } else {
                            StackAction::Stop
                        }
                    } else {
                        StackAction::None
                    }
                },
                1,
            );
            if !pop.is_empty() {
                let v = pop[0].version;
                self.renumber_version(v, version);
                return pop.into_iter().next().unwrap().subtrees;
            }
        }
        Vec::new()
    }

    pub fn pop_all(&mut self, version: StackVersion) -> Vec<StackSlice> {
        self.iter(
            version,
            |node, _| {
                if node.links.is_empty() {
                    StackAction::Pop
                } else {
                    StackAction::None
                }
            },
            0,
        )
    }

    pub fn record_summary(&mut self, version: StackVersion, max_depth: u32) {
        let mut summary: Vec<StackSummaryEntry> = Vec::new();
        self.iter(
            version,
            |node, iterator| {
                let state = node.state;
                let depth = iterator.subtree_count;
                if depth > max_depth {
                    return StackAction::Stop;
                }
                for entry in summary.iter().rev() {
                    if entry.depth < depth {
                        break;
                    }
                    if entry.depth == depth && entry.state == state {
                        return StackAction::None;
                    }
                }
                summary.push(StackSummaryEntry {
                    position: node.position,
                    depth,
                    state,
                });
                StackAction::None
            },
            -1,
        );
        self.heads[version].summary = Some(summary);
    }

    pub fn get_summary(&self, version: StackVersion) -> Option<&Vec<StackSummaryEntry>> {
        self.heads[version].summary.as_ref()
    }

    pub fn depth(&self, version: StackVersion) -> u32 {
        let mut node = self.heads[version].node;
        let mut depth = 0;
        while !self.nodes[node].links.is_empty() {
            node = self.nodes[node].links[0].node;
            depth += 1;
        }
        depth
    }

    pub fn dynamic_precedence(&self, version: StackVersion) -> i32 {
        self.nodes[self.heads[version].node].dynamic_precedence
    }

    pub fn has_advanced_since_error(&self, version: StackVersion) -> bool {
        let head = &self.heads[version];
        let mut node = head.node;
        if self.nodes[node].error_cost == 0 {
            return true;
        }
        loop {
            let n = &self.nodes[node];
            if n.links.is_empty() {
                return false;
            }
            if let Some(subtree) = &n.links[0].subtree {
                if subtree.total_bytes() > 0 {
                    return true;
                } else if n.links[0].node != node && self.nodes[n.links[0].node].error_cost < n.error_cost {
                    return true;
                }
            }
            node = n.links[0].node;
        }
    }

    pub fn error_cost(&self, version: StackVersion) -> u32 {
        let head = &self.heads[version];
        let node = &self.nodes[head.node];
        let mut result = node.error_cost;
        if head.status == StackStatus::Paused
            || (node.state == ERROR_STATE && node.links.first().is_some_and(|l| l.subtree.is_none()))
        {
            result += ERROR_COST_PER_RECOVERY;
        }
        result
    }

    pub fn node_count_since_error(&mut self, version: StackVersion) -> u32 {
        let node_count = self.nodes[self.heads[version].node].node_count;
        let head = &mut self.heads[version];
        if node_count < head.node_count_at_last_error {
            head.node_count_at_last_error = node_count;
        }
        node_count - head.node_count_at_last_error
    }

    pub fn last_external_token(&self, version: StackVersion) -> Option<Subtree> {
        self.heads[version].last_external_token.clone()
    }

    pub fn set_last_external_token(&mut self, version: StackVersion, token: Option<Subtree>) {
        self.heads[version].last_external_token = token;
    }

    pub fn copy_version(&mut self, version: StackVersion) -> StackVersion {
        let mut head = self.heads[version].clone();
        head.summary = None;
        self.heads.push(head);
        self.heads.len() - 1
    }

    pub fn remove_version(&mut self, version: StackVersion) {
        self.heads.remove(version);
    }

    pub fn renumber_version(&mut self, v1: StackVersion, v2: StackVersion) {
        if v1 == v2 {
            return;
        }
        assert!(v2 < v1);
        assert!(v1 < self.heads.len());
        if self.heads[v2].summary.is_some() && self.heads[v1].summary.is_none() {
            let summary = self.heads[v2].summary.take();
            self.heads[v1].summary = summary;
        }
        let source = self.heads.remove(v1);
        self.heads[v2] = source;
    }

    pub fn swap_versions(&mut self, v1: StackVersion, v2: StackVersion) {
        self.heads.swap(v1, v2);
    }

    pub fn can_merge(&self, v1: StackVersion, v2: StackVersion) -> bool {
        let head1 = &self.heads[v1];
        let head2 = &self.heads[v2];
        let node1 = &self.nodes[head1.node];
        let node2 = &self.nodes[head2.node];
        head1.status == StackStatus::Active
            && head2.status == StackStatus::Active
            && node1.state == node2.state
            && node1.position.bytes == node2.position.bytes
            && node1.error_cost == node2.error_cost
            && external_scanner_state_eq(&head1.last_external_token, &head2.last_external_token)
    }

    pub fn merge(&mut self, v1: StackVersion, v2: StackVersion) -> bool {
        if !self.can_merge(v1, v2) {
            return false;
        }
        let node1 = self.heads[v1].node;
        let node2 = self.heads[v2].node;
        let links = self.nodes[node2].links.clone();
        for link in links {
            self.node_add_link(node1, link);
        }
        if self.nodes[node1].state == ERROR_STATE {
            self.heads[v1].node_count_at_last_error = self.nodes[node1].node_count;
        }
        self.remove_version(v2);
        true
    }

    pub fn halt(&mut self, version: StackVersion) {
        self.heads[version].status = StackStatus::Halted;
    }

    pub fn pause(&mut self, version: StackVersion, lookahead: Subtree) {
        let node_count = self.nodes[self.heads[version].node].node_count;
        let head = &mut self.heads[version];
        head.status = StackStatus::Paused;
        head.lookahead_when_paused = Some(lookahead);
        head.node_count_at_last_error = node_count;
    }

    pub fn is_active(&self, version: StackVersion) -> bool {
        self.heads[version].status == StackStatus::Active
    }

    pub fn is_paused(&self, version: StackVersion) -> bool {
        self.heads[version].status == StackStatus::Paused
    }

    pub fn is_halted(&self, version: StackVersion) -> bool {
        self.heads[version].status == StackStatus::Halted
    }

    pub fn resume(&mut self, version: StackVersion) -> Subtree {
        let head = &mut self.heads[version];
        assert!(head.status == StackStatus::Paused);
        let result = head.lookahead_when_paused.take().unwrap();
        head.status = StackStatus::Active;
        result
    }

    pub fn head_node(&self, version: StackVersion) -> &StackNode {
        &self.nodes[self.heads[version].node]
    }
}
