                last_external_token: None,
                token: None,
            },
            external_scanner_payload: std::ptr::null_mut(),
            external_scanner_buffer: vec![0u8; TREE_SITTER_SERIALIZATION_BUFFER_SIZE],
            accept_count: 0,
            operation_count: 0,
            has_scanner_error: false,
            logger: None,
            timeout: None,
            start_time: Instant::now(),
            included_ranges: vec![],
        };
