                    external_scanner_state_len = self.external_scanner_serialize();
                    let empty: &[u8] = &[];
                    let old_state = external_token
                        .as_ref()
                        .map(|t| t.external_scanner_state.as_slice())
                        .unwrap_or(empty);
                    external_scanner_state_changed =
                        old_state != &self.external_scanner_buffer[..external_scanner_state_len];

                    if self.lexer.token_end_position.bytes <= current_position.bytes
                        && (error_mode || !self.stack.has_advanced_since_error(version))
                        && !external_scanner_state_changed
                    {
