            log!(
                self,
                "lex_internal state:{}, row:{}, column:{}",
                lex_mode.lex_state,
                current_position.extent.row,
                current_position.extent.column
            );
            self.lexer.start();
            let lexer_ptr = self.lexer.as_ts_lexer();
            found_token = unsafe { self.language.lex(lexer_ptr, lex_mode.lex_state) };
            self.lexer.finish(&mut lookahead_end_byte);
