            let mut symbol = self.lexer.result_symbol();
            let padding = self.lexer.token_start_position.sub(start_position);
            let size = self
                .lexer
                .token_end_position
                .sub(self.lexer.token_start_position);
            let lookahead_bytes = lookahead_end_byte - self.lexer.token_end_position.bytes;

            if found_external_token {
                symbol = self.language.external_scanner_symbol(symbol as usize);
            } else if symbol == self.language.keyword_capture_token() && symbol != 0 {
                let end_byte = self.lexer.token_end_position.bytes;
                let start = self.lexer.token_start_position;
                self.lexer.reset(start);
                self.lexer.start();

                let lexer_ptr = self.lexer.as_ts_lexer();
                is_keyword = unsafe { self.language.keyword_lex(lexer_ptr, 0) };

                if is_keyword && self.lexer.token_end_position.bytes == end_byte {
                    let keyword = self.lexer.result_symbol();
                    if self.language.has_actions(parse_state, keyword)
                        || self.language.reserved_words(parse_state).contains(&keyword)
                    {
                        symbol = keyword;
                    }
                }
            }

            let mut tree = Subtree::new_leaf(
                symbol,
                padding,
                size,
                lookahead_bytes,
                parse_state,
                found_external_token,
                called_get_column,
                is_keyword,
                &self.language,
            );

            if found_external_token {
                let data = tree.make_mut();
                data.external_scanner_state =
                    self.external_scanner_buffer[..external_scanner_state_len].to_vec();
                data.has_external_scanner_state_change = external_scanner_state_changed;
            }
            result = tree;
        }

        log!(
            self,
            "lexed_lookahead sym:{}, size:{}",
            self.language.symbol_name(result.symbol),
            result.total_size().bytes
        );
        Some(result)
    }

    fn can_reuse_first_leaf(&self, state: TSStateId, tree: &Subtree, table_entry: &TableEntry) -> bool {
        let current_lex_mode = self.language.lex_mode(state);
        let leaf_symbol = tree.leaf_symbol();
        let leaf_state = tree.leaf_parse_state();
        let leaf_lex_mode = self.language.lex_mode(leaf_state);

        if current_lex_mode.lex_state == u16::MAX {
            return false;
        }

        if !table_entry.actions.is_empty()
            && leaf_lex_mode.lex_state == current_lex_mode.lex_state
            && leaf_lex_mode.external_lex_state == current_lex_mode.external_lex_state
            && (leaf_symbol != self.language.keyword_capture_token()
                || (!tree.is_keyword && tree.parse_state == state))
        {
            return true;
        }

        if tree.size.bytes == 0 && leaf_symbol != TS_BUILTIN_SYM_END {
            return false;
        }

        current_lex_mode.external_lex_state == 0 && table_entry.reusable
    }

    fn get_cached_token(
        &self,
        state: TSStateId,
        position: u32,
        last_external_token: &Option<Subtree>,
        table_entry: &mut TableEntry,
    ) -> Option<Subtree> {
        if let Some(token) = &self.token_cache.token {
            if self.token_cache.byte_index == position
                && external_scanner_state_eq(&self.token_cache.last_external_token, last_external_token)
            {
                *table_entry = self.language.table_entry(state, token.symbol);
                if self.can_reuse_first_leaf(state, token, table_entry) {
                    return Some(token.clone());
                }
            }
        }
        None
    }

    fn set_cached_token(&mut self, byte_index: u32, last_external_token: Option<Subtree>, token: Subtree) {
        self.token_cache.byte_index = byte_index;
        self.token_cache.last_external_token = last_external_token;
        self.token_cache.token = Some(token);
    }

    fn shift(&mut self, version: StackVersion, state: TSStateId, lookahead: Subtree, extra: bool) {
        let is_leaf = lookahead.child_count() == 0;
        let mut subtree_to_push = lookahead;
        if extra != subtree_to_push.extra && is_leaf {
            subtree_to_push.set_extra(extra);
        }
        let has_external = subtree_to_push.has_external_tokens;
        let last_external = if has_external {
            last_external_token(&subtree_to_push)
        } else {
            None
        };
        self.stack.push(version, Some(subtree_to_push), !is_leaf, state);
        if has_external {
            self.stack.set_last_external_token(version, last_external);
        }
    }

    fn select_tree(&mut self, left: &Subtree, right: &Subtree) -> bool {
        let name = |s: TSSymbol| self.language.symbol_name(s).to_string();
        if right.error_cost() < left.error_cost() {
            log!(
                self,
                "select_smaller_error symbol:{}, over_symbol:{}",
                name(right.symbol),
                name(left.symbol)
            );
            return true;
        }
        if left.error_cost() < right.error_cost() {
            log!(
                self,
                "select_smaller_error symbol:{}, over_symbol:{}",
                name(left.symbol),
                name(right.symbol)
            );
            return false;
        }
        if right.dynamic_precedence > left.dynamic_precedence {
            log!(
                self,
                "select_higher_precedence symbol:{}, prec:{}, over_symbol:{}, other_prec:{}",
                name(right.symbol),
                right.dynamic_precedence,
                name(left.symbol),
                left.dynamic_precedence
            );
            return true;
        }
        if left.dynamic_precedence > right.dynamic_precedence {
            log!(
                self,
                "select_higher_precedence symbol:{}, prec:{}, over_symbol:{}, other_prec:{}",
                name(left.symbol),
                left.dynamic_precedence,
                name(right.symbol),
                right.dynamic_precedence
            );
            return false;
        }
        if left.error_cost() > 0 {
            return true;
        }
        match subtree_compare(left, right) {
            std::cmp::Ordering::Less => {
                log!(
                    self,
                    "select_earlier symbol:{}, over_symbol:{}",
                    name(left.symbol),
                    name(right.symbol)
                );
                false
            }
            std::cmp::Ordering::Greater => {
                log!(
                    self,
                    "select_earlier symbol:{}, over_symbol:{}",
                    name(right.symbol),
                    name(left.symbol)
                );
                true
            }
            std::cmp::Ordering::Equal => {
                log!(
                    self,
                    "select_existing symbol:{}, over_symbol:{}",
                    name(left.symbol),
                    name(right.symbol)
                );
                false
            }
        }
    }

    fn select_children(&mut self, left: &Subtree, children: &[Subtree]) -> bool {
        let scratch_tree = Subtree::new_node(left.symbol, children.to_vec(), 0, &self.language);
        self.select_tree(left, &scratch_tree)
    }

    fn reduce(
        &mut self,
        version: StackVersion,
        symbol: TSSymbol,
        count: u32,
        dynamic_precedence: i32,
        production_id: u16,
        is_fragile: bool,
        end_of_non_terminal_extra: bool,
    ) -> StackVersion {
        let initial_version_count = self.stack.version_count();

        let pop = self.stack.pop_count(version, count);
        let mut removed_version_count = 0usize;
        let mut i = 0;
        while i < pop.len() {
            let slice = &pop[i];
            let slice_version = slice.version - removed_version_count;

            if slice_version > MAX_VERSION_COUNT + MAX_VERSION_COUNT_OVERFLOW {
                self.stack.remove_version(slice_version);
                removed_version_count += 1;
                while i + 1 < pop.len() {
                    if pop[i + 1].version != slice.version {
                        break;
                    }
                    i += 1;
                }
                i += 1;
                continue;
            }

            let mut children = slice.subtrees.clone();
            let mut trailing_extras = remove_trailing_extras(&mut children);

            let mut parent = Subtree::new_node(symbol, children, production_id, &self.language);

            while i + 1 < pop.len() {
                let next_slice = &pop[i + 1];
                if next_slice.version != slice.version {
                    break;
                }
                i += 1;

                let mut children = next_slice.subtrees.clone();
                let trailing_extras2 = remove_trailing_extras(&mut children);

                if self.select_children(&parent, &children) {
                    trailing_extras = trailing_extras2;
                    parent = Subtree::new_node(symbol, children, production_id, &self.language);
                }
            }

            let state = self.stack.state(slice_version);
            let next_state = self.language.next_state(state, symbol);
            {
                let data = parent.make_mut();
                if end_of_non_terminal_extra && next_state == state {
                    data.extra = true;
                }
                if is_fragile || pop.len() > 1 || initial_version_count > 1 {
                    data.fragile_left = true;
                    data.fragile_right = true;
                    data.parse_state = TS_TREE_STATE_NONE;
                } else {
                    data.parse_state = state;
                }
                data.dynamic_precedence += dynamic_precedence;
            }

            self.stack.push(slice_version, Some(parent), false, next_state);
            for extra in trailing_extras {
                self.stack.push(slice_version, Some(extra), false, next_state);
            }

            for j in 0..slice_version {
                if j == version {
                    continue;
                }
                if self.stack.merge(j, slice_version) {
                    removed_version_count += 1;
                    break;
                }
            }
            i += 1;
        }

        if self.stack.version_count() > initial_version_count {
            initial_version_count
        } else {
            STACK_VERSION_NONE
        }
    }

    fn accept(&mut self, version: StackVersion, lookahead: Subtree) {
        assert!(lookahead.is_eof());
        self.stack.push(version, Some(lookahead), false, 1);

        let pop = self.stack.pop_all(version);
        for slice in &pop {
            let mut trees = slice.subtrees.clone();
            let mut root: Option<Subtree> = None;
            for j in (0..trees.len()).rev() {
                let tree = trees[j].clone();
                if !tree.extra {
                    let children: Vec<Subtree> = tree.children.clone();
                    trees.splice(j..j + 1, children);
                    root = Some(Subtree::new_node(
                        tree.symbol,
                        trees.clone(),
                        tree.production_id,
                        &self.language,
                    ));
                    break;
                }
            }

            let root = root.expect("accept: no root");
            self.accept_count += 1;

            if let Some(finished) = self.finished_tree.clone() {
                if self.select_tree(&finished, &root) {
                    self.finished_tree = Some(root);
                }
            } else {
                self.finished_tree = Some(root);
            }
        }

        self.stack.remove_version(pop[0].version);
        self.stack.halt(version);
    }

    fn do_all_potential_reductions(&mut self, starting_version: StackVersion, lookahead_symbol: TSSymbol) -> bool {
        let initial_version_count = self.stack.version_count();

        let mut can_shift_lookahead_symbol = false;
        let mut version = starting_version;
        let mut i = 0;
        loop {
            let version_count = self.stack.version_count();
            if version >= version_count {
                break;
            }

            let mut merged = false;
            for j in initial_version_count..version {
                if self.stack.merge(j, version) {
                    merged = true;
                    break;
                }
            }
            if merged {
                continue;
            }

            let state = self.stack.state(version);
            let mut has_shift_action = false;
            let mut reduce_actions: Vec<ReduceAction> = Vec::new();

            let (first_symbol, end_symbol) = if lookahead_symbol != 0 {
                (lookahead_symbol, lookahead_symbol + 1)
            } else {
                (1, self.language.token_count() as TSSymbol)
            };

            for symbol in first_symbol..end_symbol {
                let entry = self.language.table_entry(state, symbol);
                for action in &entry.actions {
                    match action {
                        ParseAction::Shift { extra, repetition, .. } => {
                            if !extra && !repetition {
                                has_shift_action = true;
                            }
                        }
                        ParseAction::Recover => {
                            has_shift_action = true;
                        }
                        ParseAction::Reduce {
                            symbol,
                            child_count,
                            dynamic_precedence,
                            production_id,
                        } => {
                            if *child_count > 0 {
                                let action = ReduceAction {
                                    symbol: *symbol,
                                    count: *child_count,
                                    dynamic_precedence: *dynamic_precedence,
                                    production_id: *production_id,
                                };
                                if !reduce_actions.contains(&action) {
                                    reduce_actions.push(action);
                                }
                            }
                        }
                        ParseAction::Accept => {}
                    }
                }
            }

            let mut reduction_version = STACK_VERSION_NONE;
            for action in &reduce_actions {
                reduction_version = self.reduce(
                    version,
                    action.symbol,
                    action.count,
                    action.dynamic_precedence,
                    action.production_id,
                    true,
                    false,
                );
            }

            if has_shift_action {
                can_shift_lookahead_symbol = true;
            } else if reduction_version != STACK_VERSION_NONE && i < MAX_VERSION_COUNT {
                self.stack.renumber_version(reduction_version, version);
                i += 1;
                continue;
            } else if lookahead_symbol != 0 {
                self.stack.remove_version(version);
            }

            if version == starting_version {
                version = version_count;
            } else {
                version += 1;
            }
            i += 1;
        }

        can_shift_lookahead_symbol
    }

    fn handle_error(&mut self, version: StackVersion, lookahead: Subtree) {
        let previous_version_count = self.stack.version_count();

        self.do_all_potential_reductions(version, 0);
        let version_count = self.stack.version_count();
        let position = self.stack.position(version);

        let mut did_insert_missing_token = false;
        let mut v = version;
        while v < version_count {
            if !did_insert_missing_token {
                let state = self.stack.state(v);
                for missing_symbol in 1..(self.language.token_count() as TSSymbol) {
                    let state_after_missing_symbol = self.language.next_state(state, missing_symbol);
                    if state_after_missing_symbol == 0 || state_after_missing_symbol == state {
                        continue;
                    }

                    if self
                        .language
                        .has_reduce_action(state_after_missing_symbol, lookahead.leaf_symbol())
                    {
                        self.lexer.reset(position);
                        self.lexer.mark_end();
                        let padding = self.lexer.token_end_position.sub(position);
                        let lookahead_bytes = lookahead.total_bytes() + lookahead.lookahead_bytes;

                        let version_with_missing_tree = self.stack.copy_version(v);
                        let missing_tree = Subtree::new_missing_leaf(
                            missing_symbol,
                            padding,
                            lookahead_bytes,
                            &self.language,
                        );
                        self.stack.push(
                            version_with_missing_tree,
                            Some(missing_tree),
                            false,
                            state_after_missing_symbol,
                        );

                        if self.do_all_potential_reductions(
                            version_with_missing_tree,
                            lookahead.leaf_symbol(),
                        ) {
                            log!(
                                self,
                                "recover_with_missing symbol:{}, state:{}",
                                self.language.symbol_name(missing_symbol),
                                self.stack.state(version_with_missing_tree)
                            );
                            did_insert_missing_token = true;
                            break;
                        }
                    }
                }
            }

            self.stack.push(v, None, false, ERROR_STATE);
            v = if v == version { previous_version_count } else { v + 1 };
        }

        for _ in previous_version_count..version_count {
            let did_merge = self.stack.merge(version, previous_version_count);
            assert!(did_merge);
        }

        self.stack.record_summary(version, MAX_SUMMARY_DEPTH);

        self.recover(version, lookahead);
    }

    fn recover_to_state(&mut self, version: StackVersion, depth: u32, goal_state: TSStateId) -> bool {
        let mut pop = self.stack.pop_count(version, depth);
        let mut previous_version = STACK_VERSION_NONE;

        let mut i = 0;
        while i < pop.len() {
            let slice_version = pop[i].version;

            if slice_version == previous_version {
                pop.remove(i);
                continue;
            }

            if self.stack.state(slice_version) != goal_state {
                self.stack.halt(slice_version);
                pop.remove(i);
                continue;
            }

            let mut subtrees = pop[i].subtrees.clone();
            let error_trees = self.stack.pop_error(slice_version);
            if !error_trees.is_empty() {
                assert!(error_trees.len() == 1);
                let error_tree = &error_trees[0];
                if error_tree.child_count() > 0 {
                    let mut new_subtrees = error_tree.children.clone();
                    new_subtrees.extend(subtrees);
                    subtrees = new_subtrees;
                }
            }

            let trailing_extras = remove_trailing_extras(&mut subtrees);

            if !subtrees.is_empty() {
                let error = Subtree::new_error_node(subtrees, true, &self.language);
                self.stack.push(slice_version, Some(error), false, goal_state);
            }

            for tree in trailing_extras {
                self.stack.push(slice_version, Some(tree), false, goal_state);
            }

            previous_version = slice_version;
            i += 1;
        }

        previous_version != STACK_VERSION_NONE
    }

    fn version_status(&mut self, version: StackVersion) -> ErrorStatus {
        let mut cost = self.stack.error_cost(version);
        let is_paused = self.stack.is_paused(version);
        if is_paused {
            cost += ERROR_COST_PER_SKIPPED_TREE;
        }
        ErrorStatus {
            cost,
            node_count: self.stack.node_count_since_error(version),
            dynamic_precedence: self.stack.dynamic_precedence(version),
            is_in_error: is_paused || self.stack.state(version) == ERROR_STATE,
        }
    }

    fn compare_versions(a: ErrorStatus, b: ErrorStatus) -> ErrorComparison {
        if !a.is_in_error && b.is_in_error {
            return if a.cost < b.cost {
                ErrorComparison::TakeLeft
            } else {
                ErrorComparison::PreferLeft
            };
        }
        if a.is_in_error && !b.is_in_error {
            return if b.cost < a.cost {
                ErrorComparison::TakeRight
            } else {
                ErrorComparison::PreferRight
            };
        }
        if a.cost < b.cost {
            return if (b.cost - a.cost) * (1 + a.node_count) > MAX_COST_DIFFERENCE {
                ErrorComparison::TakeLeft
            } else {
                ErrorComparison::PreferLeft
            };
        }
        if b.cost < a.cost {
            return if (a.cost - b.cost) * (1 + b.node_count) > MAX_COST_DIFFERENCE {
                ErrorComparison::TakeRight
            } else {
                ErrorComparison::PreferRight
            };
        }
        if a.dynamic_precedence > b.dynamic_precedence {
            return ErrorComparison::PreferLeft;
        }
        if b.dynamic_precedence > a.dynamic_precedence {
            return ErrorComparison::PreferRight;
        }
        ErrorComparison::None
    }

    fn better_version_exists(&mut self, version: StackVersion, is_in_error: bool, cost: u32) -> bool {
        if let Some(finished) = &self.finished_tree {
            if finished.error_cost() <= cost {
                return true;
            }
        }

        let position = self.stack.position(version);
        let status = ErrorStatus {
            cost,
            is_in_error,
            dynamic_precedence: self.stack.dynamic_precedence(version),
            node_count: self.stack.node_count_since_error(version),
        };

        let n = self.stack.version_count();
        for i in 0..n {
            if i == version || !self.stack.is_active(i) || self.stack.position(i).bytes < position.bytes {
                continue;
            }
            let status_i = self.version_status(i);
            match Self::compare_versions(status, status_i) {
                ErrorComparison::TakeRight => return true,
                ErrorComparison::PreferRight => {
                    if self.stack.can_merge(i, version) {
                        return true;
                    }
                }
                _ => {}
            }
        }
        false
    }

    fn recover(&mut self, version: StackVersion, mut lookahead: Subtree) {
        let mut did_recover = false;
        let previous_version_count = self.stack.version_count();
        let position = self.stack.position(version);
        let summary = self.stack.get_summary(version).cloned();
        let node_count_since_error = self.stack.node_count_since_error(version);
        let current_error_cost = self.stack.error_cost(version);

        if let Some(summary) = summary {
            if !lookahead.is_error() {
                for entry in &summary {
                    if entry.state == ERROR_STATE {
                        continue;
                    }
                    if entry.position.bytes == position.bytes {
                        continue;
                    }
                    let mut depth = entry.depth;
                    if node_count_since_error > 0 {
                        depth += 1;
                    }

                    let mut would_merge = false;
                    for j in 0..previous_version_count {
                        if self.stack.state(j) == entry.state && self.stack.position(j).bytes == position.bytes {
                            would_merge = true;
                            break;
                        }
                    }
                    if would_merge {
                        continue;
                    }

                    let new_cost = current_error_cost
                        + entry.depth * ERROR_COST_PER_SKIPPED_TREE
                        + (position.bytes - entry.position.bytes) * ERROR_COST_PER_SKIPPED_CHAR
                        + (position.extent.row - entry.position.extent.row) * ERROR_COST_PER_SKIPPED_LINE;
                    if self.better_version_exists(version, false, new_cost) {
                        break;
                    }

                    if self.language.has_actions(entry.state, lookahead.symbol) {
                        if self.recover_to_state(version, depth, entry.state) {
                            did_recover = true;
                            log!(self, "recover_to_previous state:{}, depth:{}", entry.state, depth);
                            break;
                        }
                    }
                }
            }
        }

        let mut i = previous_version_count;
        while i < self.stack.version_count() {
            if !self.stack.is_active(i) {
                self.stack.remove_version(i);
            } else {
                i += 1;
            }
        }

        if did_recover && self.stack.version_count() > MAX_VERSION_COUNT {
            self.stack.halt(version);
            return;
        }

        if did_recover && lookahead.has_external_scanner_state_change {
            self.stack.halt(version);
            return;
        }

        if lookahead.is_eof() {
            log!(self, "recover_eof");
            let parent = Subtree::new_error_node(Vec::new(), false, &self.language);
            self.stack.push(version, Some(parent), false, 1);
            self.accept(version, lookahead);
            return;
        }

        let new_cost = current_error_cost
            + ERROR_COST_PER_SKIPPED_TREE
            + lookahead.total_bytes() * ERROR_COST_PER_SKIPPED_CHAR
            + lookahead.total_size().extent.row * ERROR_COST_PER_SKIPPED_LINE;
        if self.better_version_exists(version, false, new_cost) {
            self.stack.halt(version);
            return;
        }

        let entry = self.language.table_entry(1, lookahead.symbol);
        if let Some(ParseAction::Shift { extra: true, .. }) = entry.actions.last() {
            lookahead.set_extra(true);
        }

        log!(self, "skip_token symbol:{}", self.language.symbol_name(lookahead.symbol));
        let has_external = lookahead.has_external_tokens;
        let last_external = if has_external { last_external_token(&lookahead) } else { None };
        let mut error_repeat = Subtree::new_node(
            TS_BUILTIN_SYM_ERROR_REPEAT,
            vec![lookahead],
            0,
            &self.language,
        );

        if node_count_since_error > 0 {
            let pop = self.stack.pop_count(version, 1);
            if pop.len() > 1 {
                while self.stack.version_count() > pop[0].version + 1 {
                    self.stack.remove_version(pop[0].version + 1);
                }
            }
            self.stack.renumber_version(pop[0].version, version);
            let mut subtrees = pop[0].subtrees.clone();
            subtrees.push(error_repeat);
            error_repeat = Subtree::new_node(TS_BUILTIN_SYM_ERROR_REPEAT, subtrees, 0, &self.language);
        }

        self.stack.push(version, Some(error_repeat), false, ERROR_STATE);
        if has_external {
            self.stack.set_last_external_token(version, last_external);
        }
    }

    fn condense_stack(&mut self) -> u32 {
        let mut made_changes = false;
        let mut min_error_cost = u32::MAX;
        let mut i = 0usize;
        while i < self.stack.version_count() {
            if self.stack.is_halted(i) {
                self.stack.remove_version(i);
                continue;
            }

            let status_i = self.version_status(i);
            if !status_i.is_in_error && status_i.cost < min_error_cost {
                min_error_cost = status_i.cost;
            }

            let mut j = 0usize;
            let mut restart = false;
            while j < i {
                let status_j = self.version_status(j);
                match Self::compare_versions(status_j, status_i) {
                    ErrorComparison::TakeLeft => {
                        made_changes = true;
                        self.stack.remove_version(i);
                        restart = true;
                        break;
                    }
                    ErrorComparison::PreferLeft | ErrorComparison::None => {
                        if self.stack.merge(j, i) {
                            made_changes = true;
                            restart = true;
                            break;
                        }
                    }
                    ErrorComparison::PreferRight => {
                        made_changes = true;
                        if self.stack.merge(j, i) {
                            restart = true;
                            break;
                        } else {
                            self.stack.swap_versions(i, j);
                        }
                    }
                    ErrorComparison::TakeRight => {
                        made_changes = true;
                        self.stack.remove_version(j);
                        i -= 1;
                        continue;
                    }
                }
                j += 1;
            }
            if restart {
                // `i` was removed or merged; re-examine the same index.
                continue;
            }
            i += 1;
        }

        while self.stack.version_count() > MAX_VERSION_COUNT {
            self.stack.remove_version(MAX_VERSION_COUNT);
            made_changes = true;
        }

        if self.stack.version_count() > 0 {
            let mut has_unpaused_version = false;
            let mut i = 0;
            while i < self.stack.version_count() {
                if self.stack.is_paused(i) {
                    if !has_unpaused_version && (self.accept_count as usize) < MAX_VERSION_COUNT {
                        log!(self, "resume version:{}", i);
                        min_error_cost = self.stack.error_cost(i);
                        let lookahead = self.stack.resume(i);
                        self.handle_error(i, lookahead);
                        has_unpaused_version = true;
                        i += 1;
                    } else {
                        self.stack.remove_version(i);
                    }
                } else {
                    has_unpaused_version = true;
                    i += 1;
                }
            }
        }

        if made_changes {
            log!(self, "condense");
        }
        min_error_cost
    }

    fn breakdown_top_of_stack(&mut self, version: StackVersion) -> bool {
        let mut did_break_down = false;
        let mut pending;

        loop {
            let pop = self.stack.pop_pending(version);
            if pop.is_empty() {
                break;
            }

            did_break_down = true;
            pending = false;
            for slice in &pop {
                let mut state = self.stack.state(slice.version);
                let parent = slice.subtrees[0].clone();

                for child in parent.children.iter() {
                    pending = child.child_count() > 0;
                    if child.is_error() {
                        state = ERROR_STATE;
                    } else if !child.extra {
                        state = self.language.next_state(state, child.symbol);
                    }
                    self.stack.push(slice.version, Some(child.clone()), pending, state);
                }

                for tree in slice.subtrees.iter().skip(1) {
                    self.stack.push(slice.version, Some(tree.clone()), false, state);
                }

                log!(self, "breakdown_top_of_stack tree:{}", self.language.symbol_name(parent.symbol));
            }
            if !pending {
                break;
            }
        }

        did_break_down
    }

    fn advance(&mut self, version: StackVersion, _allow_node_reuse: bool) -> bool {
        let mut state = self.stack.state(version);
        let position = self.stack.position(version).bytes;
        let last_external_token = self.stack.last_external_token(version);

        let mut table_entry = TableEntry::default();
        let mut lookahead = self.get_cached_token(state, position, &last_external_token, &mut table_entry);

        let mut needs_lex = lookahead.is_none();
        loop {
            if needs_lex {
                needs_lex = false;
                lookahead = self.lex(version, state);
                if self.has_scanner_error {
                    return false;
                }

                if let Some(l) = &lookahead {
                    self.set_cached_token(position, last_external_token.clone(), l.clone());
                    table_entry = self.language.table_entry(state, l.symbol);
                } else {
                    table_entry = self.language.table_entry(state, TS_BUILTIN_SYM_END);
                }
            }

            self.operation_count += 1;
            if self.operation_count == OP_COUNT_PER_PARSER_TIMEOUT_CHECK {
                self.operation_count = 0;
                if let Some(timeout) = self.timeout {
                    if self.start_time.elapsed() > timeout {
                        return false;
                    }
                }
            }

            let mut last_reduction_version = STACK_VERSION_NONE;
            for action in table_entry.actions.clone() {
                match action {
                    ParseAction::Shift { state: next, extra, repetition } => {
                        if repetition {
                            continue;
                        }
                        let next_state;
                        if extra {
                            next_state = state;
                            log!(self, "shift_extra");
                        } else {
                            next_state = next;
                            log!(self, "shift state:{}", next_state);
                        }
                        let l = lookahead.take().unwrap();
                        self.shift(version, next_state, l, extra);
                        return true;
                    }
                    ParseAction::Reduce { symbol, child_count, dynamic_precedence, production_id } => {
                        let is_fragile = table_entry.actions.len() > 1;
                        let end_of_non_terminal_extra = lookahead.is_none();
                        log!(
                            self,
                            "reduce sym:{}, child_count:{}",
                            self.language.symbol_name(symbol),
                            child_count
                        );
                        let reduction_version = self.reduce(
                            version,
                            symbol,
                            child_count,
                            dynamic_precedence,
                            production_id,
                            is_fragile,
                            end_of_non_terminal_extra,
                        );
                        if reduction_version != STACK_VERSION_NONE {
                            last_reduction_version = reduction_version;
                        }
                    }
                    ParseAction::Accept => {
                        log!(self, "accept");
                        let l = lookahead.take().unwrap();
                        self.accept(version, l);
                        return true;
                    }
                    ParseAction::Recover => {
                        let l = lookahead.take().unwrap();
                        self.recover(version, l);
                        return true;
                    }
                }
            }

            if last_reduction_version != STACK_VERSION_NONE {
                self.stack.renumber_version(last_reduction_version, version);
                state = self.stack.state(version);
                match &lookahead {
                    None => needs_lex = true,
                    Some(l) => {
                        table_entry = self.language.table_entry(state, l.leaf_symbol());
                    }
                }
                continue;
            }

            let Some(l) = lookahead.as_mut() else {
                self.stack.halt(version);
                return true;
            };

            if l.is_keyword && l.symbol != self.language.keyword_capture_token() {
                let capture = self.language.keyword_capture_token();
                table_entry = self.language.table_entry(state, capture);
                if !table_entry.actions.is_empty() {
                    log!(
                        self,
                        "switch from_keyword:{}, to_word_token:{}",
                        self.language.symbol_name(l.symbol),
                        self.language.symbol_name(capture)
                    );
                    l.set_symbol(capture, &self.language);
                    continue;
                }
            }

            if state == ERROR_STATE {
                let l = lookahead.take().unwrap();
                self.recover(version, l);
                return true;
            }

            if self.breakdown_top_of_stack(version) {
                state = self.stack.state(version);
                lookahead = None;
                needs_lex = true;
                continue;
            }

            log!(self, "detect_error lookahead:{}", self.language.symbol_name(l.symbol));
            let l = lookahead.take().unwrap();
            self.stack.pause(version, l);
            return true;
        }
    }
}

/// Find the last external token within a subtree.
pub fn last_external_token(tree: &Subtree) -> Option<Subtree> {
    let mut tree = tree.clone();
    loop {
        if tree.child_count() == 0 {
            return if tree.has_external_tokens { Some(tree) } else { None };
        }
        let mut next = None;
        for child in tree.children.iter().rev() {
            if child.has_external_tokens {
                next = Some(child.clone());
                break;
            }
        }
        match next {
            Some(n) => tree = n,
            None => return None,
        }
    }
}
