            return &[];
        }
        &source[start..end]
    }

    pub fn id(&self) -> usize {
        std::rc::Rc::as_ptr(&self.subtree.0) as usize
    }
}

impl PartialEq for Node<'_> {
    fn eq(&self, other: &Self) -> bool {
        self.subtree.ptr_eq(&other.subtree) && self.position == other.position
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum CursorStep {
    None,
    Hidden,
    Visible,
}

#[derive(Clone)]
struct CursorEntry {
    subtree: Subtree,
    position: Length,
    child_index: u32,
    structural_child_index: u32,
    descendant_index: u32,
}

struct ChildIterator {
    parent: Option<Subtree>,
    position: Length,
    child_index: u32,
    structural_child_index: u32,
    descendant_index: u32,
    alias_sequence: Vec<TSSymbol>,
}

impl ChildIterator {
    fn next(&mut self) -> Option<(CursorEntry, bool)> {
        let parent = self.parent.as_ref()?;
        if self.child_index as usize >= parent.children.len() {
            return None;
        }
        let child = &parent.children[self.child_index as usize];
        let entry = CursorEntry {
            subtree: child.clone(),
            position: self.position,
            child_index: self.child_index,
            structural_child_index: self.structural_child_index,
            descendant_index: self.descendant_index,
        };
        let mut visible = child.visible;
        let extra = child.extra;
        if !extra && !self.alias_sequence.is_empty() {
            if self.alias_sequence.get(self.structural_child_index as usize).copied().unwrap_or(0) != 0 {
                visible = true;
            }
            self.structural_child_index += 1;
        } else if !extra {
            self.structural_child_index += 1;
        }
        self.descendant_index += child.visible_descendant_count;
        if visible {
            self.descendant_index += 1;
        }

        self.position = self.position.add(child.size);
        self.child_index += 1;

        if (self.child_index as usize) < parent.children.len() {
            let next_child = &parent.children[self.child_index as usize];
            self.position = self.position.add(next_child.padding);
        }
        Some((entry, visible))
    }
}

pub struct TreeCursor<'a> {
    tree: &'a Tree,
    stack: Vec<CursorEntry>,
    root_alias_symbol: TSSymbol,
}

impl<'a> TreeCursor<'a> {
    pub fn new(tree: &'a Tree) -> Self {
        TreeCursor {
            tree,
            stack: vec![CursorEntry {
                subtree: tree.root.clone(),
                position: Length::zero(),
                child_index: 0,
                structural_child_index: 0,
                descendant_index: 0,
            }],
            root_alias_symbol: 0,
        }
    }

    pub fn reset(&mut self, node: &Node<'a>) {
        self.stack.clear();
        self.stack.push(CursorEntry {
            subtree: node.subtree.clone(),
            position: node.position,
            child_index: 0,
            structural_child_index: 0,
            descendant_index: 0,
        });
        self.root_alias_symbol = node.alias_symbol;
    }

    fn iterate_children(&self) -> ChildIterator {
        let last = self.stack.last().unwrap();
        if last.subtree.child_count() == 0 {
            return ChildIterator {
                parent: None,
                position: Length::zero(),
                child_index: 0,
                structural_child_index: 0,
                descendant_index: 0,
                alias_sequence: Vec::new(),
            };
        }
        ChildIterator {
            parent: Some(last.subtree.clone()),
            position: last.position,
            child_index: 0,
            structural_child_index: 0,
            descendant_index: last.descendant_index + 1,
            alias_sequence: self.tree.language.alias_sequence(last.subtree.production_id),
        }
    }

    fn goto_first_child_internal(&mut self) -> CursorStep {
        let mut iterator = self.iterate_children();
        while let Some((entry, visible)) = iterator.next() {
            if visible {
                self.stack.push(entry);
                return CursorStep::Visible;
            }
            if entry.subtree.visible_child_count > 0 {
                self.stack.push(entry);
                return CursorStep::Hidden;
            }
        }
        CursorStep::None
    }

    pub fn goto_first_child(&mut self) -> bool {
        loop {
            match self.goto_first_child_internal() {
                CursorStep::Hidden => continue,
                CursorStep::Visible => return true,
                CursorStep::None => return false,
            }
        }
    }

    fn goto_next_sibling_internal(&mut self) -> CursorStep {
        let initial_size = self.stack.len();
        while self.stack.len() > 1 {
            let entry = self.stack.pop().unwrap();
            let mut iterator = self.iterate_children();
            iterator.child_index = entry.child_index;
            iterator.structural_child_index = entry.structural_child_index;
            iterator.position = entry.position;
            iterator.descendant_index = entry.descendant_index;

            let mut visible = false;
            if let Some((_, v)) = iterator.next() {
                visible = v;
            }
            if visible && self.stack.len() + 1 < initial_size {
                break;
            }

            while let Some((entry, visible)) = iterator.next() {
                if visible {
                    self.stack.push(entry);
                    return CursorStep::Visible;
                }
                if entry.subtree.visible_child_count > 0 {
                    self.stack.push(entry);
                    return CursorStep::Hidden;
                }
            }
        }
        CursorStep::None
    }

    pub fn goto_next_sibling(&mut self) -> bool {
        match self.goto_next_sibling_internal() {
            CursorStep::Hidden => {
                self.goto_first_child();
                true
            }
            CursorStep::Visible => true,
            CursorStep::None => false,
        }
    }

    fn is_entry_visible(&self, index: usize) -> bool {
        let entry = &self.stack[index];
        if index == 0 || entry.subtree.visible {
            true
        } else if !entry.subtree.extra {
            let parent_entry = &self.stack[index - 1];
            self.tree
                .language
                .alias_at(parent_entry.subtree.production_id, entry.structural_child_index)
                != 0
        } else {
            false
        }
    }

    pub fn goto_parent(&mut self) -> bool {
        if self.stack.len() < 2 {
            return false;
        }
        for i in (0..self.stack.len() - 1).rev() {
            if self.is_entry_visible(i) {
                self.stack.truncate(i + 1);
                return true;
            }
        }
        false
    }

    pub fn node(&self) -> Node<'a> {
        let last = self.stack.last().unwrap();
        let mut alias_symbol = self.root_alias_symbol;
        if self.stack.len() > 1 && !last.subtree.extra {
            let parent_entry = &self.stack[self.stack.len() - 2];
            alias_symbol = self
                .tree
                .language
                .alias_at(parent_entry.subtree.production_id, last.structural_child_index);
        }
        let mut ancestors = Vec::new();
        for i in 0..self.stack.len() - 1 {
            if self.is_entry_visible(i) {
                ancestors.push((self.stack[i].subtree.clone(), self.stack[i].position));
            }
        }
        Node {
            tree: self.tree,
            subtree: last.subtree.clone(),
            position: last.position,
            alias_symbol,
            ancestors,
        }
    }

    pub fn field_id(&self) -> TSFieldId {
        if self.stack.len() < 2 {
            return 0;
        }
        for i in (1..self.stack.len()).rev() {
            let entry = &self.stack[i];
            let parent_entry = &self.stack[i - 1];

            if i != self.stack.len() - 1 && self.is_entry_visible(i) {
                break;
            }
            if entry.subtree.extra {
                break;
            }
            let field_map = self.tree.language.field_map(parent_entry.subtree.production_id);
            for map in field_map {
                if !map.inherited && map.child_index as u32 == entry.structural_child_index {
                    return map.field_id;
                }
            }
        }
        0
    }

    pub fn field_name(&self) -> Option<&'a str> {
        let id = self.field_id();
        if id == 0 {
            return None;
        }
        let lang: &'a Language = unsafe { &*(&self.tree.language as *const Language) };
        lang.field_name(id)
    }

    pub fn depth(&self) -> u32 {
        let mut d = 0;
        for i in 0..self.stack.len() - 1 {
            if self.is_entry_visible(i) {
                d += 1;
            }
        }
        d
    }
}
